/* 模擬試験（145問） */
GK.addQuestions([
/* ── T01 人工知能の定義 ── */
{ id: "M-001", set: "mock", sec: "T01", kw: ["AI 効果"], type: "best",
  stem: "次の事例のうち、AI 効果を表すものとして最も適切なものを1つ選べ。",
  choices: ["人工知能が自分より優れた人工知能を次々に生み出し、技術の進歩が人間には予測できないほど急になると考えられている", "単純な規則で応答するだけの会話プログラムと話した人が、プログラムが自分の話を理解していると感じた", "かつて人工知能の研究課題とされた文字認識やチェスのプログラムが、実用化されて仕組みが知られると、「単なる計算であり知能ではない」と受け止められるようになった", "室温に応じて冷房の強さを変えるだけのエアコンが、宣伝のために「AI 搭載」とうたわれた"],
  ans: 2,
  exp: "AI 効果は、AI の研究から生まれた技術が実現し、仕組みが知られると、人々がそれを知能とはみなさなくなる現象である。テスラーの「知能とは、機械がまだやっていないことである」という言葉が知られている。その結果、何を「人工知能」と呼ぶかは時代とともに移り変わる。",
  why: ["シンギュラリティ（技術的特異点）の考え方であり、AI 効果ではない。", "イライザ（ELIZA）のような単純な会話プログラムに対して人が理解を感じてしまう例であり、AI 効果とは向きが異なる。", "正しい。実現した技術が「知能ではない」とみなされるようになるのが AI 効果である。", "単純な制御プログラムが「AI」と呼ばれる例である。AI 効果は逆に、実現した技術が AI と呼ばれなくなる現象である。"],
  src: [{ t: "Larry Tesler. Tesler's Theorem and other adages and coinages", u: "https://www.nomodes.com/larry-tesler-consulting/adages-and-coinages" }] },
/* ── T02 人工知能分野で議論される問題 ── */
{ id: "M-002", set: "mock", sec: "T02", kw: ["中国語の部屋", "チューリングテスト"], type: "best",
  stem: "ある会話プログラムが、チューリングテストの形式で行われた審査で、多くの審査員に人間だと判定された。このプログラムを、サールの「中国語の部屋」の議論の立場から評価したものとして、最も適切なものを1つ選べ。",
  choices: ["審査員が人間と見分けられなかった以上、このプログラムは会話の意味を理解していると認めるべきである", "審査員に人間だと判定されたことは、プログラムが規則どおりに応答を組み立てられたことを示すにすぎず、会話の意味を理解している根拠にはならない", "このプログラムをセンサーやカメラを備えたロボットに組み込めば、記号の意味を理解していると認められる", "審査の会話時間が短かったことだけが問題であり、時間を十分に延ばして見分けられなければ理解していると認められる"],
  ans: 1,
  exp: "サールは1980年の論文で、中国語を知らない人が手引き書に従って記号を操作するだけで正しく応答できる部屋を考え、記号の操作（構文）だけでは意味の理解（意味論）にはならないと主張した。ふるまいが人間と区別できないことを根拠に理解を認めるチューリングテストの考え方への批判でもある。",
  why: ["ふるまいで判定するチューリングテスト側の考え方であり、サールが批判した立場である。", "正しい。中国語の部屋の議論の中心となる主張である。", "ロボットに組み込めば理解できるという反論（ロボット応答）に対し、サールは、センサーの入力も記号として処理されるだけだとして、理解は生じないと答えている。", "サールの議論は、会話の時間の長さにかかわらず、ふるまいのテストでは理解の有無を確かめられないというものである。"],
  src: [{ t: "Searle, J. R. (1980). Minds, brains, and programs. Behavioral and Brain Sciences 3(3)", u: "https://doi.org/10.1017/S0140525X00005756" }, { t: "Stanford Encyclopedia of Philosophy: The Chinese Room Argument", u: "https://plato.stanford.edu/entries/chinese-room/" }] },
{ id: "M-003", set: "mock", sec: "T02", kw: ["ダートマス会議"], type: "worst",
  stem: "ダートマス会議と、その開催を呼びかけた1955年の提案書に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["提案書は、1956年の夏にダートマス大学で、2か月間・10人で研究を行うことを計画していた", "提案書は、マッカーシー、ミンスキー、ロチェスター、シャノンの4人の連名で出された", "提案書は、学習をはじめとする知能のあらゆる特徴は、原理的には機械で模倣できるほど正確に記述できるという考えを掲げた", "提案書が挙げた研究テーマは記号の操作に限られ、ニューロンのネットワーク（神経回路網）は含まれていなかった"],
  ans: 3,
  exp: "提案書は、言語を使うプログラム、ニューロンのネットワーク（Neuron Nets）、計算の規模の理論、自己改良、抽象化、ランダム性と創造性などを研究テーマに挙げていた。ニューラルネットワークにつながる研究も、当初から人工知能のテーマに含まれていた。",
  why: ["適切。提案書には、1956年夏にダートマス大学で2か月間・10人で研究する計画が書かれている。", "適切。提案者はマッカーシー（ダートマス大学）、ミンスキー（ハーバード大学）、ロチェスター（IBM）、シャノン（ベル電話研究所）である。", "適切。提案書の中心となる考え（推測）である。", "不適切（これが正解）。研究テーマの1つに「Neuron Nets」が明記されている。"],
  src: [{ t: "McCarthy, J., Minsky, M. L., Rochester, N. & Shannon, C. E. (1955). A Proposal for the Dartmouth Summer Research Project on Artificial Intelligence", u: "https://www-formal.stanford.edu/jmc/history/dartmouth/dartmouth.html" }] },
{ id: "M-004", set: "mock", sec: "T02", kw: ["フレーム問題", "中国語の部屋", "シンボルグラウンディング問題", "チューリングテスト"], type: "worst",
  stem: "人工知能をめぐる代表的な問題・議論と、その提起者に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["フレーム問題は、哲学者デネットが最初に提起した問題であり、それをマッカーシーとヘイズが時限爆弾とロボットのたとえ話で広めた", "中国語の部屋は、サールが1980年に、記号の操作だけでは意味の理解にならないと主張するために示した思考実験である", "シンボルグラウンディング問題は、ハルナッドが1990年に提起した、記号を実世界の対象と結び付けることの難しさに関する問題である", "チューリングテストは、チューリングが1950年の論文で「模倣ゲーム」として提案した、機械の知能を会話によって判定する方法である"],
  ans: 0,
  exp: "フレーム問題は、1969年にマッカーシーとヘイズが、論理で行動の結果を記述するときの問題として示したものである。時限爆弾とロボットのたとえ話は、のちに哲学者デネットがこの問題を説明するために用いたもので、提起者とたとえ話の作者が逆になっている。",
  why: ["不適切（これが正解）。フレーム問題を最初に示したのはマッカーシーとヘイズ（1969年）であり、ロボットのたとえ話はデネットによるものである。", "適切。サールの1980年の論文で示された。", "適切。ハルナッドの1990年の論文で提起された。", "適切。チューリングの1950年の論文「Computing Machinery and Intelligence」で提案された。"],
  src: [{ t: "McCarthy, J. & Hayes, P. J. (1969). Some Philosophical Problems from the Standpoint of Artificial Intelligence", u: "https://www-formal.stanford.edu/jmc/mcchay69.pdf" }, { t: "Stanford Encyclopedia of Philosophy: The Frame Problem", u: "https://plato.stanford.edu/entries/frame-problem/" }, { t: "Dennett, D. C. Cognitive Wheels: The Frame Problem of AI（講義資料として公開されている本文）", u: "https://www.cs.sfu.ca/~vaughan/teaching/415/papers/dennett-cognitivewheels.html" }, { t: "Harnad, S. (1990). The Symbol Grounding Problem. Physica D 42", u: "https://doi.org/10.1016/0167-2789(90)90087-6" }] },
{ id: "M-005", set: "mock", sec: "T02", kw: ["ルールベース機械翻訳", "統計的機械翻訳"], type: "best",
  stem: "機械翻訳の方式の移り変わりに関する説明として、最も適切なものを1つ選べ。",
  choices: ["最初に対訳データから確率を学ぶ統計的機械翻訳が研究され、その精度の低さを補うために、1960年代から人が規則を書くルールベース機械翻訳へ移った", "ルールベース機械翻訳は、1966年の ALPAC 報告書で高く評価され、米国ではその後も研究費が増え続けた", "1950年代から人が作った辞書と文法規則で訳す方式が研究され、1990年代以降は対訳データから確率を学ぶ統計的機械翻訳が主流となり、2010年代半ば以降はニューラルネットワークで訳文を生成するニューラル機械翻訳が広まった", "ニューラル機械翻訳は、対訳データを使わず、人が書いた辞書と文法規則だけで訳文を生成する方式である"],
  ans: 2,
  exp: "機械翻訳は、1954年のジョージタウン大学と IBM の公開実験に代表されるルールベースの方式から始まった。1990年に IBM の研究者が統計的な方法を示し、1990年代以降は統計的機械翻訳が主流となった。2014年ごろからニューラルネットワークで訳文を生成する方法が提案され、2016年には Google が、自社で運用していたフレーズベース（統計的機械翻訳の一種）のシステムに比べ、文脈から切り離した単純な文を対象にした人手の評価で、翻訳の誤りを平均60%減らしたとするニューラル機械翻訳のシステム（GNMT）を発表した。",
  why: ["順序が逆である。人が規則を書く方式が先で、統計的機械翻訳は1990年ごろから広まった。", "ALPAC 報告書は機械翻訳の成果に否定的な評価を示し、米国での研究費は大きく減った。", "正しい。ルールベース → 統計的 → ニューラルという流れである。", "ニューラル機械翻訳は、大量の対訳データからニューラルネットワークで学習する方式である。"],
  src: [{ t: "Hutchins, J. (2004). The Georgetown-IBM experiment demonstrated in January 1954 (AMTA 2004)", u: "https://aclanthology.org/2004.amta-papers.12/" }, { t: "Hutchins, J. (1996). ALPAC: the (in)famous report. MT News International 14", u: "https://mt-archive.net/90/MTNI-1996-Hutchins.pdf" }, { t: "Brown, P. F. et al. (1990). A Statistical Approach to Machine Translation. Computational Linguistics 16(2)", u: "https://aclanthology.org/J90-2002/" }, { t: "Bahdanau, D., Cho, K. & Bengio, Y. (2014). Neural Machine Translation by Jointly Learning to Align and Translate", u: "https://arxiv.org/abs/1409.0473" }, { t: "Wu, Y. et al. (2016). Google's Neural Machine Translation System: Bridging the Gap between Human and Machine Translation", u: "https://arxiv.org/abs/1609.08144" }] },
/* ── T03 探索・推論 ── */
{ id: "M-006", set: "mock", sec: "T03", kw: ["幅優先探索", "深さ優先探索"], type: "calc",
  stem: "根 A の子が B と C、B の子が D と E、C の子が F と G である探索木がある（D・E・F・G に子はない）。ゴールは C である。ノードを訪れたときにゴールかどうかを確かめ、同じ親の子は左（B、D、F の側）から順に調べるものとする。C を見つけるまでに訪れるノードの数（A と C を含む）を、幅優先探索と深さ優先探索のそれぞれについて求めた組み合わせとして、正しいものを1つ選べ。",
  choices: ["幅優先探索 5 個・深さ優先探索 3 個", "幅優先探索 3 個・深さ優先探索 3 個", "幅優先探索 7 個・深さ優先探索 5 個", "幅優先探索 3 個・深さ優先探索 5 個"],
  ans: 3,
  exp: "幅優先探索は浅い順に A → B → C と訪れるので3個で C に着く。深さ優先探索は左の枝を深く進むので A → B → D → E と調べ、戻ってから C を訪れるため5個になる。浅い所にあるゴールは、幅優先探索のほうが早く見つけられる。",
  why: ["幅優先探索と深さ優先探索の値が入れ替わっている。", "深さ優先探索は先に B の下の D・E を調べるので、3個では C に着かない。", "幅優先探索は深さ1の C を、深さ2のノードより先に調べる。7個は木のノードをすべて訪れた場合の数である。", "正しい。幅優先探索は A・B・C の3個、深さ優先探索は A・B・D・E・C の5個である。"],
  src: [{ t: "Russell, S. & Norvig, P. AIMA lecture slides: Chapter 3 Problem solving and search", u: "https://aima.cs.berkeley.edu/slides-pdf/chapter03.pdf" }] },
{ id: "M-007", set: "mock", sec: "T03", kw: ["STRIPS", "SHRDLU"], type: "best",
  stem: "STRIPS と SHRDLU が扱った内容の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["STRIPS：積み木の世界で、人の英語の指示に従って物体を動かし、質問に答える／SHRDLU：行動を前提条件・追加リスト・削除リストで表し、行動の手順を自動で組み立てる", "STRIPS：行動を前提条件・追加リスト・削除リストで表し、目標を達成する行動の手順を自動で組み立てる／SHRDLU：積み木の世界で、人の英語の指示に従って物体を動かし、質問に答える", "STRIPS：質量分析のデータから、未知の有機化合物の分子構造を推定する／SHRDLU：感染症の原因菌を推定し、抗菌薬を助言する", "STRIPS：終局までランダムに指し進める試行を繰り返し、勝率で手を選ぶ／SHRDLU：大量の対訳データから翻訳の確率を学ぶ"],
  ans: 1,
  exp: "STRIPS は1971年にフィケスとニルソンが発表した自動計画（プランニング）の方式で、SRI の移動ロボット Shakey の研究で使われた。SHRDLU はウィノグラードが MIT で開発した、積み木の世界で英語の指示や質問に応じるプログラムである。",
  why: ["STRIPS と SHRDLU の内容が入れ替わっている。", "正しい。STRIPS は自動計画、SHRDLU は積み木の世界での自然言語の対話である。", "それぞれ DENDRAL と MYCIN の内容である。", "前者はモンテカルロ法によるゲームの探索、後者は統計的機械翻訳の内容である。"],
  src: [{ t: "Fikes, R. E. & Nilsson, N. J. (1971). STRIPS: A new approach to the application of theorem proving to problem solving. Artificial Intelligence 2", u: "https://doi.org/10.1016/0004-3702(71)90010-5" }, { t: "Winograd, T. (1971). Procedures as a Representation for Data in a Computer Program for Understanding Natural Language (MIT AI Technical Report 235)", u: "https://dspace.mit.edu/handle/1721.1/7095" }] },
{ id: "M-008", set: "mock", sec: "T03", kw: ["αβ 法", "Mini-Max 法"], type: "best",
  stem: "ゲームの探索で αβ 法を用いるとき、枝刈りできる量を増やすための工夫として、最も適切なものを1つ選べ。",
  choices: ["それぞれの局面で、有望そうな（良い結果になりそうな）手から先に調べるように、手を調べる順番を並べ替える", "それぞれの局面で、評価が低くなりそうな手から先に調べるように、手を調べる順番を並べ替える", "枝刈りを増やすためであれば、Mini-Max 法と異なる手が選ばれてもよいとして、評価値の比較を省く", "手を調べる順番は枝刈りの量に影響しないので、順番は無作為に決める"],
  ans: 0,
  exp: "αβ 法は、Mini-Max 法と同じ結論を保ったまま、結果に影響しない枝の探索を打ち切る。刈れる量は手を調べる順番に左右され、良い手を先に調べるほど多く刈れる。最もよい順番で調べられれば、同じ計算量でおよそ2倍の深さまで読めるとされる（Knuth & Moore, 1975）。",
  why: ["正しい。良い手を先に調べると早い段階で基準となる値が決まり、残りの手を早く打ち切れる。", "悪い手を先に調べると、打ち切りの基準となる値がなかなか決まらず、刈れる量は少なくなる。", "αβ 法の枝刈りは、Mini-Max 法と同じ結論になることが前提である。", "手の順番は枝刈りの量に大きく影響する。"],
  src: [{ t: "Knuth, D. E. & Moore, R. W. (1975). An analysis of alpha-beta pruning. Artificial Intelligence 6", u: "https://doi.org/10.1016/0004-3702(75)90019-3" }, { t: "Russell, S. & Norvig, P. AIMA lecture slides: Chapter 6 Game playing", u: "https://aima.cs.berkeley.edu/slides-pdf/chapter06.pdf" }] },
/* ── T04 知識表現とエキスパートシステム ── */
{ id: "M-009", set: "mock", sec: "T04", kw: ["セマンティック Web", "オントロジー"], type: "worst",
  stem: "セマンティック Web とオントロジーに関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["RDF は、情報を「主語・述語・目的語」の3つ組（トリプル）で表す枠組みである", "OWL は、W3C が定めた、オントロジーを記述するための言語である", "オントロジーを「概念化の明示的な仕様」と定義したのは、セマンティック Web の構想を示したバーナーズ＝リーらの2001年の記事である", "語彙の意味をオントロジーで共通に定めておくと、異なるサイトの情報をプログラムが組み合わせて扱いやすくなる"],
  ans: 2,
  exp: "知識工学でオントロジーを「概念化の明示的な仕様」と定義したのはグルーバー（1993）である。バーナーズ＝リーらの2001年の記事はセマンティック Web の構想を広く示したもので、オントロジーはその土台として位置づけられている。",
  why: ["適切。W3C の RDF の仕様が定める基本的な表し方である。", "適切。OWL（Web Ontology Language）は W3C の勧告である。", "不適切（これが正解）。この定義はグルーバー（1993）によるものである。", "適切。共通の語彙と意味をそろえることが、セマンティック Web でデータを組み合わせて推論する土台になる。"],
  src: [{ t: "Gruber, T. R. (1993). A translation approach to portable ontology specifications. Knowledge Acquisition 5", u: "https://doi.org/10.1006/knac.1993.1008" }, { t: "Berners-Lee, T., Hendler, J. & Lassila, O. (2001). The Semantic Web. Scientific American 284(5)", u: "https://doi.org/10.1038/scientificamerican0501-34" }, { t: "W3C. RDF 1.1 Concepts and Abstract Syntax", u: "https://www.w3.org/TR/rdf11-concepts/" }, { t: "W3C. OWL 2 Web Ontology Language Document Overview (Second Edition)", u: "https://www.w3.org/TR/owl2-overview/" }] },
{ id: "M-010", set: "mock", sec: "T04", kw: ["DENDRAL", "マイシン (MYCIN)", "Cyc プロジェクト", "ワトソン"], type: "best",
  stem: "知識を活用するシステムやプロジェクトを、始まった（または発表された）時期の古いものから順に並べたものとして、最も適切なものを1つ選べ。",
  choices: ["MYCIN → DENDRAL → Cyc プロジェクト → ワトソンのクイズ番組での勝利", "Cyc プロジェクト → DENDRAL → MYCIN → ワトソンのクイズ番組での勝利", "DENDRAL → Cyc プロジェクト → MYCIN → ワトソンのクイズ番組での勝利", "DENDRAL → MYCIN → Cyc プロジェクト → ワトソンのクイズ番組での勝利"],
  ans: 3,
  exp: "DENDRAL は1965年に始まった研究から生まれた、エキスパートシステムの草分けである。MYCIN は1970年代にスタンフォード大学で開発された。Cyc プロジェクトは1984年にレナートが始めた。IBM のワトソンがクイズ番組「Jeopardy!」で人間のチャンピオンに勝ったのは2011年である。",
  why: ["DENDRAL（1965年〜）のほうが MYCIN（1970年代）より前である。", "Cyc プロジェクト（1984年〜）は DENDRAL・MYCIN より後である。", "MYCIN（1970年代）は Cyc プロジェクト（1984年〜）より前である。", "正しい。1965年 → 1970年代 → 1984年 → 2011年の順である。"],
  src: [{ t: "Lindsay, R. K., Buchanan, B. G., Feigenbaum, E. A. & Lederberg, J. (1993). DENDRAL: A case study of the first expert system for scientific hypothesis formation. Artificial Intelligence 61", u: "https://doi.org/10.1016/0004-3702(93)90068-M" }, { t: "Buchanan & Shortliffe (1984). Chapter 1: The Context of the MYCIN Experiments", u: "https://people.dbmi.columbia.edu/~ehs7001/Buchanan-Shortliffe-1984/Chapter-01.pdf" }, { t: "Lenat, D. B. (1995). CYC: a large-scale investment in knowledge infrastructure. Communications of the ACM 38(11)", u: "https://doi.org/10.1145/219717.219745" }, { t: "IBM History: Watson, Jeopardy! champion", u: "https://www.ibm.com/history/watson-jeopardy" }] },
{ id: "M-011", set: "mock", sec: "T04", kw: ["ウェブマイニング", "データマイニング"], type: "best",
  stem: "次の分析のうち、ウェブマイニングに当たるものとして、最も適切なものを1つ選べ。",
  choices: ["通販サイトのアクセスログを分析し、利用者がどのような順にページを閲覧して購入に至るかの傾向を見つける", "専門家に質問を重ねて診断の手順を聞き出し、if-then 形式の規則として知識ベースに登録する", "実店舗の POS データを分析し、同時に買われやすい商品の組み合わせを見つける", "ある分野の概念どうしの is-a の関係を人手で定義し、共通の語彙として公開する"],
  ans: 0,
  exp: "ウェブマイニングは、ウェブ上のデータを対象にしたデータマイニングである。対象によって、ページの中身を扱うコンテンツマイニング、リンクのつながりを扱う構造マイニング、アクセスログなどの利用の記録を扱う利用（ユーセージ）マイニングに分けられる。アクセスログから閲覧の傾向を見つけるのは利用マイニングに当たる。",
  why: ["正しい。ウェブの利用の記録を対象にした、利用（ユーセージ）マイニングである。", "専門家から知識を聞き出す作業であり、インタビューシステムが支援する知識獲得に当たる。データから規則性を掘り出すマイニングではない。", "相関ルールの発見というデータマイニングの例だが、対象は実店舗の POS データであり、ウェブ上のデータではない。", "オントロジーの構築に当たり、データから知識を見つけ出すマイニングではない。"],
  src: [{ t: "Kosala, R. & Blockeel, H. (2000). Web Mining Research: A Survey. SIGKDD Explorations 2(1)", u: "https://arxiv.org/abs/cs/0011033" }, { t: "Agrawal, R., Imieliński, T. & Swami, A. (1993). Mining association rules between sets of items in large databases (SIGMOD 1993)", u: "https://doi.org/10.1145/170035.170072" }] },
{ id: "M-012", set: "mock", sec: "T04", kw: ["意味ネットワーク", "is-a の関係・has-a の関係・part-of の関係"], type: "best",
  stem: "意味ネットワークに「カナリア is-a 鳥」「ペンギン is-a 鳥」「鳥 is-a 動物」「動物 has-a 皮膚」という知識が表されている。is-a の関係の推移律と性質の継承を使って導ける知識として、最も適切なものを1つ選べ。",
  choices: ["動物 is-a 鳥", "カナリア has-a 皮膚", "カナリア is-a ペンギン", "皮膚 is-a 動物"],
  ans: 1,
  exp: "is-a の関係では推移律が成り立つので、「カナリア is-a 鳥」と「鳥 is-a 動物」から「カナリア is-a 動物」が導ける。さらに、上位の概念の性質は下位の概念に受け継がれるので、「動物 has-a 皮膚」から「カナリア has-a 皮膚」が導ける。コリンズとキリアン（1969）は、「カナリアは鳥である」より「カナリアは動物である」のように、階層をたどる段数が多い文ほど、人が正しいと判断するのに時間がかかるという実験結果を報告した。",
  why: ["is-a の関係には向きがあり、「鳥 is-a 動物」を逆にした「動物 is-a 鳥」は導けない。", "正しい。推移律で「カナリア is-a 動物」となり、動物の性質「皮膚を持つ」を継承する。", "カナリアとペンギンはどちらも鳥の下位概念（兄弟の関係）であり、一方が他方の一種ではない。", "皮膚は動物が持つもの（has-a の関係）であり、動物の一種ではない。"],
  src: [{ t: "Collins, A. M. & Quillian, M. R. (1969). Retrieval time from semantic memory. Journal of Verbal Learning and Verbal Behavior 8", u: "https://doi.org/10.1016/S0022-5371(69)80069-1" }, { t: "Brachman, R. J. (1983). What IS-A Is and Isn't: An Analysis of Taxonomic Links in Semantic Networks. Computer 16(10)", u: "https://doi.org/10.1109/MC.1983.1654194" }] },
/* ── T05 機械学習 ── */
{ id: "M-013", set: "mock", sec: "T05", kw: ["次元の呪い"], type: "worst",
  stem: "特徴量の数が多いデータで次元の呪いが心配されるときの対応として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["主成分分析などの次元削減を使って、特徴量の数を減らす", "予測に役立たない特徴量を取り除き、必要な特徴量に絞り込む", "次元が高いほどデータが空間を密に埋めて学習しやすくなるので、思いつく限りの特徴量を追加する", "特徴量の数に対して十分な量の学習データを集める"],
  ans: 2,
  exp: "次元の呪いとは、特徴量の数（次元）が増えると空間が指数関数的に広がり、データがまばらになって学習に必要なデータの量が急に増える現象である。対処としては、次元削減や特徴量の選択で次元を減らす、データを増やすなどがある。特徴量を増やすほど性能が上がるとは限らない。",
  why: ["適切。次元削減で次元を減らすのは代表的な対処である。", "適切。特徴量の選択によって次元を減らす方法である。", "不適切（これが正解）。次元が高いほどデータは空間の中でまばらになる。むやみに特徴量を増やすと、次元の呪いはかえって深刻になる。", "適切。必要なデータの量は次元とともに急に増えるため、データを増やすことも対処の1つになる。"],
  src: [{ t: "Bishop, C. M. (2006). Pattern Recognition and Machine Learning, Section 1.4 The Curse of Dimensionality", u: "https://www.microsoft.com/en-us/research/publication/pattern-recognition-machine-learning/" }, { t: "scikit-learn User Guide: Feature selection", u: "https://scikit-learn.org/stable/modules/feature_selection.html" }] },
/* ── T06 ディープラーニング ── */
{ id: "M-014", set: "mock", sec: "T06", kw: ["ImageNet", "ILSVRC"], type: "worst",
  stem: "ImageNet と ILSVRC に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["ImageNet は、WordNet の名詞の階層に沿って概念ごとに画像を集めた大規模な画像データベースであり、1400万枚を超える画像を収めている", "ILSVRC の分類部門は、ImageNet のうち1000クラス・約120万枚の学習画像からなる部分を用いた", "2015年には ResNet の top-5 誤り率が、人間の注釈者1人について見積もられた誤り率（約5.1%）を下回った", "ILSVRC の分類部門では、ImageNet に含まれる2万を超えるすべての概念を分類の対象とした"],
  ans: 3,
  exp: "ImageNet は2万を超える概念（synset）と1400万枚を超える画像を収めるが、ILSVRC の分類部門で使われたのは、そのうち1000クラス・約120万枚の学習画像からなる部分である。2015年には ResNet（複数のモデルのアンサンブル）が top-5 誤り率3.57%を記録して優勝し、Russakovsky ら（2015）が見積もった人間の注釈者1人の誤り率（約5.1%）を下回った。",
  why: ["適切。ImageNet の公式サイトは、14,197,122枚・21,841の synset を収め、WordNet の階層に沿って整理されているとしている。", "適切。ILSVRC2012 の分類部門は、1000クラス・120万枚の部分集合を使った。", "適切。ResNet の誤り率は3.57%で、見積もられた人間の誤り率約5.1%より低い。", "不適切（これが正解）。分類部門の対象は、ImageNet の全概念ではなく1000クラスである。"],
  src: [{ t: "ImageNet（公式サイト）", u: "https://www.image-net.org/" }, { t: "ImageNet Large Scale Visual Recognition Challenge 2012 (ILSVRC2012)", u: "https://www.image-net.org/challenges/LSVRC/2012/" }, { t: "Russakovsky, O. et al. (2015). ImageNet Large Scale Visual Recognition Challenge. International Journal of Computer Vision 115", u: "https://arxiv.org/abs/1409.0575" }, { t: "He, K. et al. (2016). Deep Residual Learning for Image Recognition", u: "https://arxiv.org/abs/1512.03385" }] },
{ id: "M-015", set: "mock", sec: "T06", kw: ["アルファ碁 (AlphaGo)"], type: "best",
  stem: "2016年にイ・セドル九段に勝ったアルファ碁（AlphaGo）の構成要素と役割の説明として、最も適切なものを1つ選べ。",
  choices: ["方策ネットワークが次に打つ手の候補の確率を、価値ネットワークが局面からの勝ちやすさを出力し、それらをモンテカルロ木探索に組み込んで手を選ぶ", "方策ネットワークが局面からの勝ちやすさを、価値ネットワークが次に打つ手の候補の確率を出力し、探索は行わずにその出力だけで手を選ぶ", "人が囲碁の知識をもとに設計した評価関数で局面を評価し、αβ 法で先読みして手を選ぶ", "人間の棋譜を一切使わず、1つのネットワークで手と局面の評価を同時に出力する"],
  ans: 0,
  exp: "アルファ碁は、手を選ぶための方策ネットワークと、局面を評価するための価値ネットワークという2つの深層ニューラルネットワークを、モンテカルロ木探索と組み合わせた。ネットワークは、人間の棋譜からの教師あり学習と、自己対局による強化学習で学習した。",
  why: ["正しい。方策ネットワークで有望な手を絞り、価値ネットワークで局面を評価しながら、モンテカルロ木探索で先読みする。", "2つのネットワークの役割が入れ替わっている。また、アルファ碁はモンテカルロ木探索を使った。", "人が設計した評価関数と αβ 法による探索は、チェスの Deep Blue などの従来の方法である。", "人間の棋譜を使わず、1つのネットワークで手と評価を出力するのは、2017年に発表されたアルファ碁ゼロの特徴である。"],
  src: [{ t: "Silver, D. et al. (2016). Mastering the game of Go with deep neural networks and tree search. Nature 529", u: "https://doi.org/10.1038/nature16961" }, { t: "Silver, D. et al. (2017). Mastering the game of Go without human knowledge. Nature 550", u: "https://doi.org/10.1038/nature24270" }] },
/* ── T07 教師あり学習 ── */
{ id: "M-016", set: "mock", sec: "T07", kw: ["単回帰分析", "線形回帰"], type: "calc",
  stem: "3組のデータ (x, y) = (1, 2), (2, 3), (3, 7) に、単回帰分析で直線 y = ax + b を最小二乗法で当てはめる。傾き a と切片 b の組み合わせとして正しいものを1つ選べ。なお、a = Σ(x − x̄)(y − ȳ) / Σ(x − x̄)<sup>2</sup>、b = ȳ − a x̄ である（x̄, ȳ はそれぞれの平均）。",
  choices: ["a = 2.5、b = 0", "a = 2.5、b = −1", "a = 2、b = 0", "a = 5、b = −6"],
  ans: 1,
  exp: "x̄ = 2、ȳ = 4 である。Σ(x − x̄)(y − ȳ) = (−1)(−2) + 0 × (−1) + 1 × 3 = 5、Σ(x − x̄)<sup>2</sup> = 1 + 0 + 1 = 2 なので、a = 5 / 2 = 2.5。b = 4 − 2.5 × 2 = −1 となる。",
  why: ["傾きは正しいが、切片は ȳ − a x̄ = 4 − 5 = −1 であり、0 ではない。", "正しい。a = 2.5、b = −1 で、残差の二乗和は 0.25 + 1 + 0.25 = 1.5 となり最小である。", "ȳ / x̄ = 2 を傾きとし、原点を通る直線にした誤りである。この直線の残差の二乗和は 2 で、1.5 より大きい。", "分母 Σ(x − x̄)<sup>2</sup> = 2 で割り忘れた値である。"],
  src: [{ t: "scikit-learn User Guide: Linear Models（Ordinary Least Squares）", u: "https://scikit-learn.org/stable/modules/linear_model.html" }, { t: "Hastie, Tibshirani & Friedman. The Elements of Statistical Learning (2nd ed.)", u: "https://hastie.su.domains/ElemStatLearn/" }] },
{ id: "M-017", set: "mock", sec: "T07", kw: ["サポートベクターマシン (SVM)", "カーネル"], type: "worst",
  stem: "サポートベクターマシン（SVM）のハイパーパラメータやカーネルに関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["ソフトマージンのパラメータ C を大きくするほど、訓練データの誤分類を許しにくくなり、マージンが狭くても訓練データをより正しく分ける境界が選ばれやすくなる", "線形カーネルを使った SVM の決定境界は、元の特徴量の空間で超平面（2次元なら直線）になる", "SVM で多クラス分類を行う場合、2クラスの組ごとに分類器を作る one-vs-one などの方法で、二値分類器を組み合わせることがある", "RBF カーネルのパラメータ γ を大きくするほど、1つの訓練データが影響する範囲が広がって境界がなめらかになり、過学習しにくくなる"],
  ans: 3,
  exp: "RBF カーネルの γ は、1つの訓練データの影響が届く範囲を決める。γ が大きいほど影響の範囲は狭くなり、境界は個々のデータに沿って複雑に曲がるため、過学習しやすくなる。γ が小さすぎると逆に単純になりすぎる。C は訓練データの正しい分類とマージンの大きさのバランスを決める。",
  why: ["適切。C が大きいほど誤分類への罰則が重くなり、マージンが狭くても訓練データを正しく分けようとする。", "適切。線形カーネルは入力どうしの内積そのものであり、境界は元の空間の超平面になる。", "適切。例えば scikit-learn の SVC は、one-vs-one で n(n − 1)/2 個の分類器を作る。", "不適切（これが正解）。γ が大きいほど影響の範囲は狭くなり、境界は複雑になって過学習しやすくなる。"],
  src: [{ t: "scikit-learn Examples: RBF SVM parameters", u: "https://scikit-learn.org/stable/auto_examples/svm/plot_rbf_parameters.html" }, { t: "scikit-learn User Guide: Support Vector Machines", u: "https://scikit-learn.org/stable/modules/svm.html" }] },
{ id: "M-018", set: "mock", sec: "T07", kw: ["ランダムフォレスト", "ブートストラップサンプリング"], type: "worst",
  stem: "ランダムフォレストに関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["各決定木は、元の訓練データからブートストラップサンプリングで作ったデータで学習する", "各決定木の学習に使われなかったデータ（out-of-bag）を使って、別に評価用のデータを取り分けなくても汎化誤差を見積もることができる", "決定木の本数を増やすほど過学習が進むため、木の本数はできるだけ少なくしたほうが汎化性能が高くなる", "学習したモデルから、各特徴量が予測にどの程度役立ったかを表す重要度を求めることができる"],
  ans: 2,
  exp: "Breiman（2001）は、ランダムフォレストは木の本数を増やしても過学習せず、汎化誤差は一定の値に近づくことを示した。本数を増やすと計算に時間はかかるが、本数を減らすほど汎化性能が上がるわけではない。",
  why: ["適切。各木はブートストラップサンプリング（復元抽出）したデータで学習する。", "適切。復元抽出では各木の学習に使われないデータが生じ、それを使った out-of-bag 推定で汎化誤差を見積もれる。", "不適切（これが正解）。木の本数を増やしても過学習は進まず、汎化誤差は一定の値に近づく。", "適切。特徴量の重要度を求められることは、ランダムフォレストがよく使われる理由の1つである。"],
  src: [{ t: "Breiman, L. (2001). Random Forests", u: "https://doi.org/10.1023/A:1010933404324" }, { t: "scikit-learn 1.2 User Guide: Ensemble methods", u: "https://scikit-learn.org/1.2/modules/ensemble.html" }] },
{ id: "M-019", set: "mock", sec: "T07", kw: ["ベクトル自己回帰モデル (VARモデル)", "自己回帰モデル (ARモデル)"], type: "best",
  stem: "ある国の物価上昇率・失業率・政策金利の3つの時系列は、互いに影響し合っていると考えられる。それぞれの過去の値をすべて使って、3つの時系列を同時に予測したい。最も適したモデルを1つ選べ。",
  choices: ["ベクトル自己回帰モデル（VAR モデル）", "自己回帰モデル（AR モデル）", "ロジスティック回帰", "k-means 法"],
  ans: 0,
  exp: "ベクトル自己回帰モデル（VAR モデル）は、複数の時系列を同時に扱い、各変数の現在の値を、自分自身と他の変数の過去の値で表す。変数どうしが影響し合う経済の時系列の分析に広く使われる。自己回帰モデル（AR モデル）は、1つの時系列を自分自身の過去の値だけで表す。",
  why: ["正しい。複数の時系列を、互いの過去の値も使って同時に予測できる。", "AR モデルは自分自身の過去の値だけを使うため、他の変数からの影響を取り込めない。", "ロジスティック回帰は、クラスに属する確率を出力する分類のモデルである。", "k-means 法は、データをクラスタに分ける教師なし学習の手法である。"],
  src: [{ t: "Hyndman & Athanasopoulos. Forecasting: Principles and Practice (3rd ed.), 12.3 Vector autoregressions", u: "https://otexts.com/fpp3/VAR.html" }, { t: "Hyndman & Athanasopoulos. Forecasting: Principles and Practice (3rd ed.), 9.3 Autoregressive models", u: "https://otexts.com/fpp3/AR.html" }] },
{ id: "M-020", set: "mock", sec: "T07", kw: ["多クラス分類"], type: "calc",
  stem: "5クラスの多クラス分類を、二値分類器を組み合わせて行う。「あるクラスか、それ以外か」を判定する one-vs-rest と、2クラスの組ごとに判定する one-vs-one のそれぞれで必要な二値分類器の数の組み合わせとして、正しいものを1つ選べ。",
  choices: ["one-vs-rest 5 個・one-vs-one 20 個", "one-vs-rest 5 個・one-vs-one 10 個", "one-vs-rest 10 個・one-vs-one 5 個", "one-vs-rest 4 個・one-vs-one 10 個"],
  ans: 1,
  exp: "one-vs-rest はクラスごとに1つの分類器を作るので、5クラスなら5個である。one-vs-one は2クラスの組ごとに1つ作るので、5 × 4 / 2 = 10 個である。クラスの数を n とすると、それぞれ n 個と n(n − 1)/2 個になる。",
  why: ["one-vs-one の 20 は 5 × 4 であり、同じ組を2回数えている。2で割って10個になる。", "正しい。one-vs-rest は n = 5 個、one-vs-one は n(n − 1)/2 = 10 個である。", "2つの方法の値が入れ替わっている。", "one-vs-rest はクラスの数だけ分類器を作るので、4個ではなく5個である。"],
  src: [{ t: "scikit-learn User Guide: Multiclass and multioutput algorithms", u: "https://scikit-learn.org/stable/modules/multiclass.html" }] },
{ id: "M-021", set: "mock", sec: "T07", kw: ["勾配ブースティング", "ブースティング"], type: "best",
  stem: "表形式のデータの予測で広く使われているライブラリ XGBoost や LightGBM が標準の設定で用いる学習手法の説明として、最も適切なものを1つ選べ。",
  choices: ["多数の決定木をそれぞれ独立に学習し、予測を多数決や平均でまとめる", "正解ラベルのないデータを、木の形で階層的にクラスタに分けていく", "1本の深い決定木を、すべての訓練データとすべての特徴量で一度に学習する", "決定木を1本ずつ順に加え、それまでの予測の損失を小さくする方向（損失関数の負の勾配）を次の木で学習して、予測に足し合わせていく"],
  ans: 3,
  exp: "XGBoost と LightGBM は、勾配ブースティング決定木（GBDT）の実装である。勾配ブースティングは、損失関数の負の勾配（二乗誤差なら残差）を次の弱学習器で学習し、それを足し合わせていくブースティングの手法である（Friedman, 2001）。",
  why: ["決定木を独立に学習して多数決・平均でまとめるのは、ランダムフォレストなどのバギング系の手法である。XGBoost・LightGBM にもランダムフォレストを学習する設定はあるが、標準の設定で用いるのは勾配ブースティング決定木である。", "階層的クラスタリングの説明であり、教師なし学習である。", "1本の決定木を学習するだけでは、アンサンブル学習にならない。", "正しい。XGBoost も LightGBM も、論文の題名に示すとおり木のブースティング（勾配ブースティング決定木）の実装である。"],
  src: [{ t: "Friedman, J. H. (2001). Greedy function approximation: A gradient boosting machine", u: "https://doi.org/10.1214/aos/1013203451" }, { t: "Chen, T. & Guestrin, C. (2016). XGBoost: A Scalable Tree Boosting System", u: "https://arxiv.org/abs/1603.02754" }, { t: "Ke, G. et al. (2017). LightGBM: A Highly Efficient Gradient Boosting Decision Tree (NIPS 2017)", u: "https://proceedings.neurips.cc/paper/2017/hash/6449f44a102fde848669bdd9eb6b76fa-Abstract.html" }, { t: "XGBoost Documentation: Random Forests(TM) in XGBoost", u: "https://xgboost.readthedocs.io/en/stable/tutorials/rf.html" }, { t: "LightGBM Documentation: Parameters（boosting）", u: "https://lightgbm.readthedocs.io/en/latest/Parameters.html" }] },
/* ── T08 教師なし学習 ── */
{ id: "M-022", set: "mock", sec: "T08", kw: ["主成分分析 (PCA)", "t-SNE", "多次元尺度構成法 (MDS)"], type: "best",
  stem: "次元削減の手法に関する説明として、最も適切なものを1つ選べ。",
  choices: ["主成分分析は非線形の次元削減手法であり、元の空間で近いデータどうしのまとまりを保つことを主な目的とする", "t-SNE は計算量が小さく、100万件規模のデータでも主成分分析より短い時間で処理できる", "多次元尺度構成法（MDS）は、データどうしの距離（非類似度）の関係をできるだけ保つように低次元に配置するので、都市間の距離の表から都市の位置関係を図にするような使い方ができる", "多次元尺度構成法（MDS）は、正解ラベルを使って、クラスどうしが最もよく分かれる方向を求める教師あり学習の手法である"],
  ans: 2,
  exp: "MDS は、データどうしの距離（似ていなさ）を入力とし、その関係をできるだけ保つように各データを低次元の空間に配置する。元の特徴量がなくても、距離の情報があれば位置関係を図にできる。主成分分析は分散が最大になる方向を求める線形の手法、t-SNE は局所的なまとまりを保つ非線形の可視化手法である。",
  why: ["主成分分析は線形の手法であり、データの分散が最大になる方向を順に求める。近いデータのまとまりを保つことを主な目的とするのは t-SNE である。", "t-SNE は計算量が大きく、scikit-learn の解説は、主成分分析なら数秒から数分で終わる100万件規模のデータで数時間かかることがあるとしている。", "正しい。距離の関係を保つように配置するのが MDS の考え方である。", "正解ラベルを使ってクラスを分ける方向を求めるのは線形判別分析などであり、MDS は正解ラベルを使わない。"],
  src: [{ t: "Torgerson, W. S. (1952). Multidimensional Scaling: I. Theory and Method", u: "https://doi.org/10.1007/BF02288916" }, { t: "scikit-learn User Guide: Manifold learning", u: "https://scikit-learn.org/stable/modules/manifold.html" }, { t: "scikit-learn User Guide: Decomposing signals in components", u: "https://scikit-learn.org/stable/modules/decomposition.html" }] },
{ id: "M-023", set: "mock", sec: "T08", kw: ["k-means 法", "ウォード法", "デンドログラム (樹形図)"], type: "best",
  stem: "k-means 法と、ウォード法などを用いる階層的クラスタリングの比較として、最も適切なものを1つ選べ。",
  choices: ["k-means 法はクラスタの数を事前に決める必要があるが、階層的クラスタリングでは、結果のデンドログラムを見ながらクラスタの数を後から決められる", "階層的クラスタリングは、最初に選ぶ中心の位置によって結果が変わるため、初期値を変えて何度も実行する必要がある", "ウォード法は、2つのクラスタに含まれるデータのうち、最も近いデータどうしの距離が最小になる組を併合する", "k-means 法は、1件ずつのデータを1つのクラスタとして始め、近いクラスタどうしを順に併合していく"],
  ans: 0,
  exp: "k-means 法は、指定した k 個の中心にデータを割り当て、中心を更新することを繰り返すため、k を事前に決める必要があり、初期値によって結果が変わる。階層的クラスタリングは、1件ずつのクラスタから順に併合していき、その過程をデンドログラムで表す。どの高さで切るかで、クラスタの数を後から決められる。",
  why: ["正しい。デンドログラムを切る高さを変えれば、クラスタの数を選び直せる。", "初期の中心の選び方で結果が変わるのは k-means 法の性質である。階層的クラスタリングには初期の中心がない。", "最も近いデータどうしの距離で併合するのは最短距離法（単連結法）である。ウォード法は、併合したときのクラスタ内の平方和の増加が最小になる組を併合する。", "1件ずつのクラスタから順に併合していくのは、階層的クラスタリング（凝集型）の手順である。"],
  src: [{ t: "Ward, J. H. (1963). Hierarchical Grouping to Optimize an Objective Function", u: "https://doi.org/10.1080/01621459.1963.10500845" }, { t: "scikit-learn User Guide: Clustering", u: "https://scikit-learn.org/stable/modules/clustering.html" }, { t: "SciPy API Reference: scipy.cluster.hierarchy.dendrogram", u: "https://docs.scipy.org/doc/scipy/reference/generated/scipy.cluster.hierarchy.dendrogram.html" }] },
{ id: "M-024", set: "mock", sec: "T08", kw: ["潜在的ディリクレ配分法 (LDA)", "トピックモデル"], type: "blank",
  stem: "潜在的ディリクレ配分法（LDA）では、各文書を（ア）が混ざり合ってできたものとみなし、各トピックを（イ）として表す。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）ただ1つのトピック　（イ）単語の出現確率の分布", "（ア）複数のトピック　（イ）単語の出現確率の分布", "（ア）複数のトピック　（イ）人があらかじめ定義した単語のリスト", "（ア）正解のクラスラベル　（イ）クラスどうしを分ける境界"],
  ans: 1,
  exp: "LDA は代表的なトピックモデルで、各文書にはトピックの混ざり具合（例：スポーツ70%・経済30%）があり、各トピックは単語の出現確率の分布で表されると考える。トピックは観測できない潜在的な変数として、文書中の単語から推定する。",
  why: ["LDA は、1つの文書に複数のトピックが含まれるとみなす点が特徴である。", "正しい。文書はトピックの混合、トピックは単語の確率分布である。", "トピックごとの単語の分布は、データから推定される。人があらかじめ定義するものではない。", "正解のクラスラベルを使ってクラスを分ける境界を求めるのは、同じく LDA と略される線形判別分析である。"],
  src: [{ t: "Blei, D. M., Ng, A. Y. & Jordan, M. I. (2003). Latent Dirichlet Allocation. JMLR 3", u: "https://www.jmlr.org/papers/v3/blei03a.html" }, { t: "Blei, D. M. (2012). Probabilistic topic models", u: "https://doi.org/10.1145/2133806.2133826" }] },
{ id: "M-025", set: "mock", sec: "T08", kw: ["コールドスタート問題", "協調フィルタリング", "コンテンツベースフィルタリング"], type: "worst",
  stem: "推薦システムのコールドスタート問題への対応として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["評価の履歴がない新しい商品には、ジャンルや説明文などの属性を使うコンテンツベースフィルタリングを組み合わせて推薦する", "新しい利用者には、最初にいくつかの商品を評価してもらい、その評価を手がかりに推薦する", "協調フィルタリングとコンテンツベースフィルタリングを組み合わせたハイブリッド型の推薦を用いる", "協調フィルタリングだけに切り替えれば、評価の履歴がない新しい商品も、他の利用者の評価にもとづいてすぐに推薦できる"],
  ans: 3,
  exp: "コールドスタート問題は、新しい利用者や新しい商品に評価・購買の履歴がほとんどないため、履歴にもとづく推薦ができない問題である。他の利用者の履歴だけに頼る協調フィルタリングで特に深刻になる。商品の属性を使う方法の併用や、新しい利用者から好みを聞き出す方法などで対処する。",
  why: ["適切。属性を使えば、評価の履歴がない商品も推薦できる（Schein ら, 2002）。", "適切。新しい利用者に評価してもらう商品の選び方は、Rashid ら（2002）が比較している。", "適切。ハイブリッド型は、協調フィルタリングとコンテンツベースフィルタリングのそれぞれの弱点を補う方法として使われる。", "不適切（これが正解）。協調フィルタリングは評価の履歴に頼るため、まだ誰も評価していない新しい商品は推薦できない。"],
  src: [{ t: "Schein, A. I. et al. (2002). Methods and metrics for cold-start recommendations", u: "https://doi.org/10.1145/564376.564421" }, { t: "Rashid, A. M. et al. (2002). Getting to know you: learning new user preferences in recommender systems (IUI 2002)", u: "https://doi.org/10.1145/502716.502737" }, { t: "Adomavicius, G. & Tuzhilin, A. (2005). Toward the next generation of recommender systems: a survey of the state-of-the-art and possible extensions", u: "https://doi.org/10.1109/TKDE.2005.99" }] },
/* ── T09 強化学習 ── */
{ id: "M-026", set: "mock", sec: "T09", kw: ["Q 学習", "SARSA"], type: "calc",
  stem: "状態 s で行動 a を取り、報酬 r = 1 と次の状態 s′ を得た。現在の Q(s, a) = 2、学習率 α = 0.5、割引率 γ = 0.9 である。s′ での行動価値は Q(s′, a<sub>1</sub>) = 4、Q(s′, a<sub>2</sub>) = 3 で、s′ では探索のために a<sub>2</sub> が選ばれた。Q 学習で更新した後の Q(s, a) の値として、正しいものを1つ選べ。",
  choices: ["2.85", "4.6", "3.3", "3.5"],
  ans: 2,
  exp: "Q 学習は、次の状態で実際に選んだ行動にかかわらず、次の状態での Q 値の最大値を使って更新する。目標は r + γ max Q(s′, a′) = 1 + 0.9 × 4 = 4.6 であり、Q(s, a) ← 2 + 0.5 × (4.6 − 2) = 3.3 となる。",
  why: ["実際に選ばれた a<sub>2</sub> の Q 値 3 を使って 2 + 0.5 × (1 + 0.9 × 3 − 2) = 2.85 としたもので、SARSA の更新である。", "目標の値 4.6 そのものであり、学習率 α = 0.5 で近づける計算をしていない。", "正しい。2 + 0.5 × (1 + 0.9 × 4 − 2) = 3.3 である。", "割引率をかけ忘れて 2 + 0.5 × (1 + 4 − 2) = 3.5 としたものである。"],
  src: [{ t: "Watkins, C. J. C. H. & Dayan, P. (1992). Q-learning", u: "https://doi.org/10.1007/BF00992698" }, { t: "Sutton, R. S. & Barto, A. G. Reinforcement Learning: An Introduction（6.4 Sarsa / 6.5 Q-Learning）", u: "http://incompleteideas.net/book/ebook/node64.html" }] },
{ id: "M-027", set: "mock", sec: "T09", kw: ["REINFORCE", "Actor-Critic", "SARSA", "方策勾配法"], type: "best",
  stem: "強化学習の手法を、価値関数を学習するアプローチと方策を直接学習するアプローチの観点から整理した説明として、最も適切なものを1つ選べ。",
  choices: ["Q 学習と SARSA は行動価値関数を学習する手法、REINFORCE は方策を直接更新する方策勾配法、Actor-Critic は方策と価値関数の両方を学習する手法である", "REINFORCE は行動価値関数だけを学習する手法であり、Q 学習は方策をパラメータで表して直接更新する方策勾配法である", "Actor-Critic は価値関数だけを学習し、行動を選ぶ方策は持たない手法である", "SARSA は方策勾配法の一種であり、エピソードの終わりに得た収益だけを使って方策のパラメータを更新する"],
  ans: 0,
  exp: "Q 学習と SARSA は行動価値関数を学習し、その値をもとに行動を選ぶ（価値ベース）。REINFORCE は方策をパラメータで表し、収益の期待値が大きくなる方向に直接更新する方策勾配法である（方策ベース）。Actor-Critic は、方策（Actor）と価値関数（Critic）を別々に持ち、両方を学習する。",
  why: ["正しい。価値ベース・方策ベース・両者の組み合わせという整理である。", "REINFORCE と Q 学習の説明が入れ替わっている。", "Actor-Critic は、行動を選ぶ方策（Actor）を持ち、価値関数（Critic）の評価をもとに Actor を更新する。", "SARSA は行動価値関数を1ステップごとに更新する TD 学習の手法である。エピソードの収益を使って方策を更新するのは REINFORCE である。"],
  src: [{ t: "Sutton, R. S. & Barto, A. G. Reinforcement Learning: An Introduction (2nd ed., 2018)", u: "http://incompleteideas.net/book/the-book-2nd.html" }, { t: "Williams, R. J. (1992). Simple statistical gradient-following algorithms for connectionist reinforcement learning", u: "https://doi.org/10.1007/BF00992696" }, { t: "Sutton, R. S. & Barto, A. G. Reinforcement Learning: An Introduction（6.6 Actor-Critic Methods）", u: "http://incompleteideas.net/book/ebook/node66.html" }] },
{ id: "M-028", set: "mock", sec: "T09", kw: ["バンディットアルゴリズム"], type: "best",
  stem: "ウェブサイトに表示する広告の候補が複数あり、クリックされる確率はどれも事前には分からない。各候補への表示の割り当てを最後まで一定の割合に固定して比べる方法と比べたとき、バンディットアルゴリズムで表示する広告を選ぶ利点として、最も適切なものを1つ選べ。",
  choices: ["一度も表示していない広告でも、過去のデータなしにクリックされる確率を正確に知ることができる", "試しながら、クリックされやすそうな広告により多くの表示を割り当てていくため、成績の悪い広告を表示し続けることによる損失を抑えやすい", "探索を一切行わず、最初の数回で成績の良かった広告だけを表示し続けるため、良い広告を見逃すおそれがない", "正解ラベル付きの大量の過去データで事前に学習するため、表示しながら試す必要がない"],
  ans: 1,
  exp: "バンディットアルゴリズムは、報酬の出方が分からない複数の選択肢から繰り返し選び、報酬の合計を最大にする方法である。探索（まだよく分からない候補を試す）と活用（良さそうな候補を選ぶ）のバランスをとりながら、成績の良い候補への割り当てを増やしていく。ニュース記事や広告の出し分けに使われている（Li ら, 2010）。",
  why: ["表示していない候補の成績は、試さなければ分からない。だから探索が必要になる。", "正しい。試しながら良い候補への割り当てを増やすことで、悪い候補に表示を割き続ける損失を抑えられる。", "探索をしないと、最初にたまたま成績の悪かった良い候補を、その後試さなくなるおそれがある。", "バンディットアルゴリズムは、正解ラベルではなく、試した結果の報酬（クリックなど）から学ぶ。"],
  src: [{ t: "Li, L. et al. (2010). A contextual-bandit approach to personalized news article recommendation", u: "https://doi.org/10.1145/1772690.1772758" }, { t: "Sutton, R. S. & Barto, A. G. Reinforcement Learning: An Introduction（2.2 Action-Value Methods）", u: "http://incompleteideas.net/book/ebook/node16.html" }] },
/* ── T10 モデルの選択・評価 ── */
{ id: "M-029", set: "mock", sec: "T10", kw: ["ROC 曲線・AUC", "混同行列", "偽陽性・偽陰性"], type: "calc",
  stem: "ある二値分類モデルで、しきい値を 0.5 にしたときの混同行列は、真陽性 30 件、偽陰性 10 件、偽陽性 12 件、真陰性 48 件であった。このしきい値に対応する ROC 曲線上の点の座標（横軸の値, 縦軸の値）として、正しいものを1つ選べ（小数第3位を四捨五入）。",
  choices: ["(0.75, 0.20)", "(0.80, 0.75)", "(0.29, 0.71)", "(0.20, 0.75)"],
  ans: 3,
  exp: "ROC 曲線は、横軸に偽陽性率（FPR）、縦軸に真陽性率（TPR）をとる。FPR = 偽陽性 / (偽陽性 + 真陰性) = 12 / 60 = 0.20、TPR = 真陽性 / (真陽性 + 偽陰性) = 30 / 40 = 0.75 なので、点は (0.20, 0.75) である。",
  why: ["横軸と縦軸の値が入れ替わっている。", "横軸に真陰性率（48 / 60 = 0.80）を使った誤りである。", "偽陽性 / (真陽性 + 偽陽性) = 12 / 42 ≒ 0.29 と、適合率 30 / 42 ≒ 0.71 を使った誤りである。", "正しい。横軸の偽陽性率は 0.20、縦軸の真陽性率は 0.75 である。"],
  src: [{ t: "Fawcett, T. (2006). An introduction to ROC analysis", u: "https://doi.org/10.1016/j.patrec.2005.10.010" }, { t: "scikit-learn User Guide: Metrics and scoring", u: "https://scikit-learn.org/stable/modules/model_evaluation.html" }] },
{ id: "M-030", set: "mock", sec: "T10", kw: ["平均絶対値誤差 (MAE)", "二乗平均平方根誤差 (RMSE)"], type: "calc",
  stem: "回帰モデルで、実測値が 5, 8, 10, 12 の4件のデータに対し、予測値が 5, 8, 10, 16 であった。平均絶対値誤差（MAE）と二乗平均平方根誤差（RMSE）の組み合わせとして、正しいものを1つ選べ。",
  choices: ["MAE = 1、RMSE = 2", "MAE = 1、RMSE = 4", "MAE = 4、RMSE = 2", "MAE = 1、RMSE = 1"],
  ans: 0,
  exp: "誤差は 0, 0, 0, −4 である。MAE = (0 + 0 + 0 + 4) / 4 = 1。MSE = (0 + 0 + 0 + 16) / 4 = 4 なので、RMSE = √4 = 2 となる。大きく外れた1件の影響で、RMSE は MAE より大きくなっている。誤差を二乗する RMSE は、大きな外れを重く評価する。",
  why: ["正しい。MAE = 1、RMSE = 2 である。", "4 は平方根をとる前の MSE の値である。", "4 は外れた1件の絶対誤差であり、4件で平均していない。", "RMSE は誤差を二乗して平均してから平方根をとるので、この例では MAE と等しくならない。"],
  src: [{ t: "scikit-learn User Guide: Metrics and scoring", u: "https://scikit-learn.org/stable/modules/model_evaluation.html" }] },
{ id: "M-031", set: "mock", sec: "T10", kw: ["赤池情報量規準 (AIC)", "ベイズ情報量規準 (BIC)"], type: "calc",
  stem: "データ数 n = 1000 のデータに2つのモデルを当てはめた。モデル A は最大対数尤度 ln L = −100、パラメータ数 k = 3、モデル B は ln L = −96、k = 5 であった。AIC = −2 ln L + 2k、BIC = −2 ln L + k ln n とし、ln 1000 ≒ 6.9 とする。AIC と BIC のそれぞれで選ばれるモデルの組み合わせとして、正しいものを1つ選べ。",
  choices: ["AIC：モデル A、BIC：モデル A", "AIC：モデル A、BIC：モデル B", "AIC：モデル B、BIC：モデル A", "AIC：モデル B、BIC：モデル B"],
  ans: 2,
  exp: "AIC は A が 200 + 6 = 206、B が 192 + 10 = 202 なので、値の小さい B が選ばれる。BIC は A が 200 + 3 × 6.9 = 220.7、B が 192 + 5 × 6.9 = 226.5 なので、A が選ばれる。データ数が多いと BIC の罰則（k ln n）は AIC の罰則（2k）より重く、パラメータの少ないモデルが選ばれやすい。",
  why: ["AIC では B（202）が A（206）より小さい。", "AIC と BIC の結果が逆である。", "正しい。AIC は B、BIC は A を選ぶ。", "BIC では A（220.7）が B（226.5）より小さい。"],
  src: [{ t: "Akaike, H. (1974). A new look at the statistical model identification", u: "https://doi.org/10.1109/TAC.1974.1100705" }, { t: "Schwarz, G. (1978). Estimating the Dimension of a Model", u: "https://doi.org/10.1214/aos/1176344136" }] },
{ id: "M-032", set: "mock", sec: "T10", kw: ["k- 分割交差検証", "交差検証"], type: "worst",
  stem: "交差検証に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["1つ抜き交差検証（Leave-One-Out）は、k をデータの件数と同じにした k-分割交差検証に当たる", "k-分割交差検証で k を大きくするほど、1回の学習に使うデータの件数は少なくなり、学習を行う回数も少なくなる", "層化 k-分割交差検証では、各グループのクラスの比率が全体の比率とほぼ同じになるようにデータを分ける", "時系列データでは、過去のデータで学習し、それより後の期間のデータで評価するように分ける"],
  ans: 1,
  exp: "k-分割交差検証では、データを k 個に分け、k − 1 個で学習して残りの1個で評価することを k 回繰り返す。k を大きくすると、1回の学習に使うデータの割合（(k − 1)/k）は大きくなり、学習の回数（k 回）も増える。",
  why: ["適切。データが n 件なら、k = n の k-分割交差検証が1つ抜き交差検証である。", "不適切（これが正解）。k を大きくすると、1回の学習に使う件数も学習の回数も増える。", "適切。クラスの比率が偏ったデータで、分け方による評価のぶれを抑えるために使う。", "適切。無作為に分けると未来のデータで学習して過去を評価することになりうるため、時間の順序を守って分ける。"],
  src: [{ t: "scikit-learn User Guide: Cross-validation", u: "https://scikit-learn.org/stable/modules/cross_validation.html" }, { t: "Stone, M. (1974). Cross-Validatory Choice and Assessment of Statistical Predictions", u: "https://doi.org/10.1111/j.2517-6161.1974.tb00994.x" }] },
{ id: "M-033", set: "mock", sec: "T10", kw: ["過学習", "汎化性能"], type: "best",
  stem: "限られた件数の訓練データに多項式回帰を当てはめ、多項式の次数（モデルの複雑さ）を1から順に上げていく。このときの訓練誤差とテスト誤差の変化の典型的な傾向として、最も適切なものを1つ選べ。",
  choices: ["次数を上げるほど、訓練誤差もテスト誤差も一貫して小さくなる", "次数を上げるほど訓練誤差は大きくなり、テスト誤差は小さくなる", "次数が低すぎる状態を過学習、次数が高すぎる状態を未学習という", "訓練誤差は次数を上げるにつれて小さくなる一方、テスト誤差はいったん小さくなった後、次数が高くなりすぎると大きくなる"],
  ans: 3,
  exp: "モデルを複雑にすると訓練データへの当てはまりは良くなり、訓練誤差は小さくなる。しかし複雑にしすぎると、訓練データのノイズまで学習する過学習が起き、未知のデータに対する誤差（テスト誤差）は大きくなる。実際のモデル選択では、テストデータとは別の検証データや交差検証で汎化誤差を見積もり、それが最も小さくなる程度の複雑さを選ぶ。",
  why: ["複雑にしすぎると過学習が起き、テスト誤差は大きくなる。", "訓練誤差は、次数を上げるほど小さくなるのが一般的である。", "逆である。単純すぎて訓練データの傾向も捉えられない状態が未学習、複雑すぎて訓練データに合わせすぎた状態が過学習である。", "正しい。scikit-learn の例でも、次数1は未学習、次数4はよく当てはまり、それより高い次数では過学習になることが示されている。"],
  src: [{ t: "scikit-learn Examples: Underfitting vs. Overfitting", u: "https://scikit-learn.org/stable/auto_examples/model_selection/plot_underfitting_overfitting.html" }, { t: "Hastie, Tibshirani & Friedman. The Elements of Statistical Learning (2nd ed.)", u: "https://hastie.su.domains/ElemStatLearn/" }] },
/* ── T11 ニューラルネットワークとディープラーニング ── */
{ id: "M-034", set: "mock", sec: "T11", kw: ["CPU","GPU","TPU"], type: "worst",
  stem: "CPU・GPU・TPU の比較に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["CPU は、1つの処理の流れ（スレッド）をできるだけ速く実行するように設計されており、同時に実行できるスレッドは数十程度である", "初代の TPU は、重みを更新する学習の処理を速くするために設計されたチップであり、学習済みのモデルで予測する推論には使われなかった", "GPU は、1つのスレッドの性能を抑える代わりに数千のスレッドを並列に実行し、全体の処理量（スループット）を高めるように設計されている", "用途を機械学習の行列演算に絞った TPU は、同時期の CPU や GPU と比べて、推論の速さや電力あたりの性能で大きく上回る結果が報告されている"],
  ans: 1,
  exp: "TPU は Google が開発した機械学習向けの ASIC（特定用途向け集積回路）である。Jouppi ら（2017）によれば、初代 TPU は推論を高速化するために作られ、8ビットの積和演算器を65,536個もつ行列演算ユニットを備え、2015年からデータセンターで使われた。その後の世代は学習にも使われ、Google Cloud で提供されている。",
  why: ["適切。NVIDIA の CUDA の解説でも、CPU は一連の処理（スレッド）をできるだけ速く実行するよう設計され、並列に実行できるのは数十のスレッドだと説明されている。", "不適切（これが正解）。初代の TPU は推論を高速化するために作られた ASIC で、2015年から Google のデータセンターで推論に使われた。学習にも使われるようになったのは後の世代である。", "適切。同じ形の計算を大量に並列で行う行列演算に向くため、ディープラーニングの学習・推論に広く使われる。", "適切。Jouppi ら（2017）は、Google の推論処理で初代 TPU が同時期の CPU・GPU より平均15〜30倍速く、電力あたりの性能は30〜80倍高かったと報告している。"],
  src: [{ t: "Jouppi, N. P. et al. (2017). In-Datacenter Performance Analysis of a Tensor Processing Unit", u: "https://arxiv.org/abs/1704.04760" }, { t: "NVIDIA. CUDA Programming Guide, 1.1 Introduction", u: "https://docs.nvidia.com/cuda/cuda-programming-guide/01-introduction/introduction.html" }, { t: "Google Cloud. Introduction to Cloud TPU", u: "https://docs.cloud.google.com/tpu/docs/intro-to-tpu" }] },
{ id: "M-035", set: "mock", sec: "T11", kw: ["単純パーセプトロン","多層パーセプトロン","隠れ層・入力層・出力層"], type: "best",
  stem: "2つの入力をもつ二値分類のデータで、一方のクラスの点は円の内側に集まり、もう一方のクラスの点はその円を外側から取り囲むように分布している。このデータで単純パーセプトロンを学習させたところ、何度学習し直しても誤って分類される点が多く残った。原因と対処の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["原因：出力層の活性化関数がステップ関数である。対処：隠れ層は加えず、出力層の活性化関数をシグモイド関数に替える", "原因：隠れ層が多すぎて勾配消失が起きている。対処：隠れ層の数を減らす", "原因：入力層のニューロンが2つしかない。対処：同じ2つの値を何回も重ねて入力し、入力層のニューロンを増やす", "原因：単純パーセプトロンの決定境界は1本の直線（超平面）に限られる。対処：非線形の活性化関数をもつ隠れ層を加え、多層パーセプトロンにする"],
  ans: 3,
  exp: "単純パーセプトロンは入力層と出力層だけからなり、入力の重み付き和で出力を決めるので、直線（超平面）で分けられる線形分離可能な問題しか解けない。円の内側と外側のように直線で分けられないデータを扱うには、非線形の活性化関数をもつ隠れ層を加えた多層パーセプトロンを使う。隠れ層のユニットが十分に多ければ、隠れ層1つでも有界閉集合上の連続関数を望む精度で近似できることが示されている（万能近似定理）。",
  why: ["隠れ層がなければ、出力層の関数をシグモイド関数に替えても、決定境界は入力の重み付き和が一定の値になる直線のままである。", "単純パーセプトロンは隠れ層をもたない。勾配消失は深いネットワークで起こる問題であり、この状況の原因ではない。", "同じ値を重ねて入力しても、出力は元の2つの入力の重み付き和で決まるので、決定境界は直線のままである。", "正しい。円の内側と外側は1本の直線では分けられない（線形分離不可能）。隠れ層が入力を別の表現に変換することで、曲がった決定境界を表せるようになる。"],
  src: [{ t: "Rosenblatt, F. (1958). The perceptron: A probabilistic model for information storage and organization in the brain", u: "https://doi.org/10.1037/h0042519" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 6 Deep Feedforward Networks", u: "https://www.deeplearningbook.org/contents/mlp.html" }] },
/* ── T12 活性化関数 ── */
{ id: "M-036", set: "mock", sec: "T12", kw: ["ソフトマックス関数"], type: "calc",
  stem: "3クラス分類の出力層で、ソフトマックス関数への入力が (ln 1, ln 3, ln 4) であった（ln は自然対数）。（ア）2番目のクラスの出力と、（イ）3つの入力すべてに 2 を足したときの2番目のクラスの出力の組み合わせとして、正しいものを1つ選べ。",
  choices: ["（ア）0.375　（イ）0.375", "（ア）0.375　（イ）0.375 より大きくなる", "（ア）約 0.44　（イ）約 0.44", "（ア）0.375　（イ）約 0.36"],
  ans: 0,
  exp: "ソフトマックス関数は y<sub>i</sub> = exp(z<sub>i</sub>) ÷ Σ exp(z<sub>j</sub>) である。exp(ln 1), exp(ln 3), exp(ln 4) は 1, 3, 4 で、合計 8 で割ると出力は (0.125, 0.375, 0.5) になる。すべての入力に同じ数 c を足すと、分子も分母も e<sup>c</sup> 倍になって打ち消し合うので、出力は変わらない。実装ではこの性質を使い、入力の最大値を引いてから計算して、指数関数の値があふれる（オーバーフローする）のを防ぐ。",
  why: ["正しい。exp を通すと 1, 3, 4 になり、3 ÷ 8 = 0.375。入力に同じ数を足しても出力は変わらない。", "入力すべてに 2 を足すと、分子にも分母の各項にも e² が掛かって打ち消し合うので、出力は変わらない。", "入力の値（ln 3 ≒ 1.10）をそのまま入力の合計（約 2.48）で割った値である。ソフトマックス関数は、指数関数を通してから合計で割る。", "（イ）は、指数関数を通した後の値（1, 3, 4）に 2 を足して (3 + 2) ÷ 14 と計算した値である。入力に足した数は指数の中に入るので、各項が e² 倍になるだけで出力は変わらない。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 4（4.1 Overflow and Underflow）", u: "https://www.deeplearningbook.org/contents/numerical.html" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 6 Deep Feedforward Networks", u: "https://www.deeplearningbook.org/contents/mlp.html" }] },
{ id: "M-037", set: "mock", sec: "T12", kw: ["ReLU 関数","Leaky ReLU 関数","tanh 関数","勾配消失問題"], type: "worst",
  stem: "隠れ層の活性化関数に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["tanh 関数は、出力が原点に対して対称で x = 0 での導関数が1なので、シグモイド関数より隠れ層で学習しやすいが、入力の絶対値が大きいと飽和して勾配が0に近づく", "Leaky ReLU 関数は負の入力にも小さな傾きをもつので、入力が常に負になったニューロンが更新されなくなる状態を防ぎやすい", "ReLU 関数は正の入力で導関数が1になるので、ReLU 関数を使うネットワークでは、層を深くしても重みの初期値の決め方は学習の成否に影響しない", "ReLU 関数は指数関数を使わないので計算が軽く、シグモイド関数や tanh 関数と比べて勾配消失が起きにくい"],
  ans: 2,
  exp: "ReLU 関数は勾配消失を起こしにくくするが、それだけで深いネットワークの学習がうまくいくわけではない。He ら（2015）は ReLU 用の初期値（前の層のニューロン数 n に対して分散 2/n）を導き、Xavier の初期値では学習が進まなかった30層のネットワークでも収束させた。ReLU 関数を使う場合も、初期値の工夫、バッチ正規化、スキップ結合などを組み合わせる。",
  why: ["適切。tanh 関数もシグモイド関数と同じく飽和するので、深いネットワークでは勾配消失が残る。", "適切。ReLU 関数では負の入力で勾配が0になり、ニューロンが学習しなくなることがある（dying ReLU）。Leaky ReLU 関数はこれを防ぎやすい。", "不適切（これが正解）。He ら（2015）は、ReLU を使う30層のネットワークで、Xavier の初期値では勾配が小さくなって学習が止まり、ReLU に合わせて導いた初期値（He の初期値）では収束することを示した。", "適切。正の側で導関数が1なので、層を重ねても勾配が縮みにくい。"],
  src: [{ t: "He, Zhang, Ren & Sun (2015). Delving Deep into Rectifiers: Surpassing Human-Level Performance on ImageNet Classification", u: "https://arxiv.org/abs/1502.01852" }, { t: "Maas, Hannun & Ng (2013). Rectifier Nonlinearities Improve Neural Network Acoustic Models", u: "https://ai.stanford.edu/~amaas/papers/relu_hybrid_icml2013_final.pdf" }, { t: "Glorot, X. & Bengio, Y. (2010). Understanding the difficulty of training deep feedforward neural networks", u: "https://proceedings.mlr.press/v9/glorot10a.html" }] },
/* ── T13 誤差関数 ── */
{ id: "M-038", set: "mock", sec: "T13", kw: ["平均二乗誤差関数","交差エントロピー","Contrastive Loss","カルバック・ライブラー情報量 (KL)"], type: "best",
  stem: "次の（ア）〜（エ）の学習で使う誤差関数（または誤差関数に含める項）の組み合わせとして、最も適切なものを1つ選べ。<br>（ア）部屋の広さや築年数から、住宅の価格（実数値）を予測する<br>（イ）手書きの数字の画像を、0〜9の10種類のどれか1つに分類する<br>（ウ）2枚の顔画像の組と「同一人物か別人か」のラベルを使い、同一人物の画像は近く、別人の画像は一定の距離以上離れるような埋め込みを学習する<br>（エ）変分オートエンコーダで、エンコーダが出力する潜在変数の分布を、標準正規分布から離れすぎないようにする",
  choices: ["（ア）交差エントロピー（イ）平均二乗誤差関数（ウ）Contrastive Loss（エ）KL 情報量", "（ア）平均二乗誤差関数（イ）交差エントロピー（ウ）Contrastive Loss（エ）KL 情報量", "（ア）平均二乗誤差関数（イ）交差エントロピー（ウ）KL 情報量（エ）Contrastive Loss", "（ア）平均二乗誤差関数（イ）Triplet Loss（ウ）交差エントロピー（エ）KL 情報量"],
  ans: 1,
  exp: "誤差関数はタスクに合わせて選ぶ。回帰は平均二乗誤差関数、分類は交差エントロピーが基本である。2つのデータの組（ペア）と「似ている・似ていない」のラベルから、似ているものは近く、似ていないものはマージン以上遠くなる埋め込みを学ぶのが Contrastive Loss である（Hadsell ら, 2006。顔の照合への応用は Chopra ら, 2005）。VAE の目的関数には、潜在変数の分布を事前分布（標準正規分布）に近づける KL 情報量の項が含まれる。",
  why: ["（ア）と（イ）が逆である。実数値を予測する回帰には平均二乗誤差関数、多クラス分類にはソフトマックス関数の出力と交差エントロピーを組み合わせる。", "正しい。回帰・多クラス分類・ペアによる距離学習・分布どうしの近さ、のそれぞれに対応する。", "（ウ）と（エ）が逆である。ペアと「似ている・似ていない」のラベルで埋め込みの距離を学ぶのが Contrastive Loss、2つの確率分布の違いを測るのが KL 情報量である。", "Triplet Loss はアンカー・ポジティブ・ネガティブの3つ組で距離の関係を学ぶ誤差関数で、10クラスの分類に使う代表的な誤差関数ではない。（ウ）はペアを使う距離学習なので Contrastive Loss が当てはまる。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 6 Deep Feedforward Networks", u: "https://www.deeplearningbook.org/contents/mlp.html" }, { t: "Hadsell, Chopra & LeCun (2006). Dimensionality Reduction by Learning an Invariant Mapping", u: "https://doi.org/10.1109/CVPR.2006.100" }, { t: "Chopra, Hadsell & LeCun (2005). Learning a Similarity Metric Discriminatively, with Application to Face Verification", u: "https://doi.org/10.1109/CVPR.2005.202" }, { t: "Kingma, D. P. & Welling, M. (2013). Auto-Encoding Variational Bayes", u: "https://arxiv.org/abs/1312.6114" }] },
/* ── T14 正則化 ── */
{ id: "M-039", set: "mock", sec: "T14", kw: ["ラッソ回帰","リッジ回帰","L1 正則化","L2 正則化"], type: "best",
  stem: "線形回帰のモデルについて、次の（ア）（イ）の要望がある。それぞれに適した手法の組み合わせとして、最も適切なものを1つ選べ。<br>（ア）説明変数が数千個あるが、予測に効くのはごく一部と考えられる。効かない変数の係数をちょうど0にして、使う変数を絞り込みたい<br>（イ）互いに相関の強い説明変数が含まれ、最小二乗法では係数の推定値が大きく振れる。どの変数も残したまま、係数を全体的に縮めて推定を安定させたい",
  choices: ["（ア）ラッソ回帰（イ）リッジ回帰", "（ア）リッジ回帰（イ）ラッソ回帰", "（ア）ラッソ回帰（イ）正則化を加えない最小二乗法による重回帰", "（ア）リッジ回帰（イ）リッジ回帰"],
  ans: 0,
  exp: "ラッソ回帰（Tibshirani, 1996）は、残差の二乗和に係数の絶対値の和（L1 正則化）を加えた回帰で、係数の一部をちょうど0にするため、変数選択の働きをもつ。リッジ回帰（Hoerl & Kennard, 1970）は、係数の二乗和（L2 正則化）を加えた回帰で、説明変数の相関が強い（多重共線性がある）ときにも係数を縮めて推定を安定させるが、係数はちょうど0にはなりにくい。",
  why: ["正しい。L1 正則化を使うラッソ回帰は係数をちょうど0にしやすく、L2 正則化を使うリッジ回帰は係数を縮めるが0にはしにくい。", "逆である。リッジ回帰は係数をちょうど0にしにくいので、変数を絞り込む働きは弱い。ラッソ回帰は、強く相関した変数のグループからその一部だけを選びがちである。", "（イ）で問題になっているのは、正則化を加えない最小二乗法で推定が不安定になることである。", "（イ）にはリッジ回帰が合うが、（ア）の「係数をちょうど0にして変数を絞り込む」にはラッソ回帰が合う。"],
  src: [{ t: "Tibshirani, R. (1996). Regression Shrinkage and Selection via the Lasso", u: "https://doi.org/10.1111/j.2517-6161.1996.tb02080.x" }, { t: "Hoerl, A. E. & Kennard, R. W. (1970). Ridge Regression: Biased Estimation for Nonorthogonal Problems", u: "https://doi.org/10.1080/00401706.1970.10488634" }, { t: "Zou, H. & Hastie, T. (2005). Regularization and Variable Selection Via the Elastic Net", u: "https://doi.org/10.1111/j.1467-9868.2005.00503.x" }] },
{ id: "M-040", set: "mock", sec: "T14", kw: ["正則化","ドロップアウト"], type: "worst",
  stem: "正則化に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["正則化の強さ λ を大きくしすぎると、重みが小さく抑えられすぎて、訓練データにも合わない未学習になることがある", "早期終了やデータ拡張も、訓練誤差ではなく汎化誤差を減らすことを意図した工夫として、広い意味の正則化に含まれる", "ドロップアウトの原論文の方式では、推論時はすべてのニューロンを使い、学習時にニューロンを残した確率 p を重みに掛けて、出力の大きさを学習時の期待値にそろえる", "ドロップアウトは、学習の最初に無作為に選んだ一部のニューロンを、学習の最後まで無効にし続けることで、ネットワークを小さくする手法である"],
  ans: 3,
  exp: "Srivastava ら（2014）のドロップアウトでは、訓練データを示すたびに新しい「間引いた」ネットワークを無作為に選んで学習する。そのため、指数関数的に多くのネットワークを平均するアンサンブル学習を、安い計算で近似していると解釈できる。推論時はドロップアウトを行わず、すべてのニューロンを使う。",
  why: ["適切。λ はハイパーパラメータで、検証データでの性能を見て調整する。", "適切。教科書 Deep Learning は、正則化を汎化誤差を減らすための学習アルゴリズムへの変更と広く定義し、データ拡張や早期終了も正則化の章で扱っている。", "適切。原論文は、推論時には重みを p 倍し、出力が学習時の期待値と同じになるようにしている。PyTorch などは逆に、学習時に残したニューロンの出力を拡大しておく方式をとる。", "不適切（これが正解）。ドロップアウトでは、無効にするニューロンを、訓練データを示すたびに無作為に選び直す。毎回異なる部分ネットワークを学習することになる。"],
  src: [{ t: "Srivastava, Hinton, Krizhevsky, Sutskever & Salakhutdinov (2014). Dropout: A Simple Way to Prevent Neural Networks from Overfitting", u: "https://jmlr.org/papers/v15/srivastava14a.html" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 7 Regularization for Deep Learning", u: "https://www.deeplearningbook.org/contents/regularization.html" }] },
/* ── T15 誤差逆伝播法 ── */
{ id: "M-041", set: "mock", sec: "T15", kw: ["連鎖律"], type: "calc",
  stem: "1つの入力 x に重み w を掛けて u = wx とし、シグモイド関数 σ で y = σ(u) を出力する。誤差を E = (1/2)(y − t)² とする。x = 2、w = 0、正解 t = 1 のとき、連鎖律 ∂E/∂w = (∂E/∂y) × (∂y/∂u) × (∂u/∂w) を使って求めた勾配の値として、正しいものを1つ選べ。シグモイド関数の導関数は σ(u)(1 − σ(u)) である。",
  choices: ["−1.0", "−0.125", "−0.25", "0.25"],
  ans: 2,
  exp: "u = 0 なので y = σ(0) = 0.5。∂E/∂y = y − t = −0.5、∂y/∂u = 0.5 × (1 − 0.5) = 0.25、∂u/∂w = x = 2 で、これらを掛けて ∂E/∂w = −0.25 となる。勾配が負なので、勾配降下法では w を増やす向きに更新され、出力 y は正解の1に近づく。誤差逆伝播法は、このように出力側から各段の局所的な微分を掛け合わせて勾配を求める。",
  why: ["シグモイド関数の導関数 ∂y/∂u = 0.25 を掛け忘れた値（(−0.5) × 2）である。", "∂u/∂w = x = 2 を掛け忘れた値（(−0.5) × 0.25）である。", "正しい。(−0.5) × 0.25 × 2 = −0.25 である。", "符号が逆である。∂E/∂y = y − t = 0.5 − 1 = −0.5 は負になる。"],
  src: [{ t: "Rumelhart, Hinton & Williams (1986). Learning representations by back-propagating errors", u: "https://doi.org/10.1038/323533a0" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 6 Deep Feedforward Networks", u: "https://www.deeplearningbook.org/contents/mlp.html" }] },
/* ── T16 最適化手法 ── */
{ id: "M-042", set: "mock", sec: "T16", kw: ["グリッドサーチ","ハイパーパラメータ"], type: "calc",
  stem: "学習率の候補を5つ、バッチサイズの候補を4つ、ドロップアウトの割合の候補を3つ用意し、すべての組み合わせを試すグリッドサーチを行う。それぞれの組み合わせの性能は、5-分割交差検証で評価する。このときモデルを学習する回数の合計として、正しいものを1つ選べ。最後に選んだ組み合わせで学習し直す分は数えない。",
  choices: ["12 回", "300 回", "60 回", "1,500 回"],
  ans: 1,
  exp: "組み合わせは 5 × 4 × 3 = 60 通りで、5-分割交差検証では1つの組み合わせにつき5回学習するので、60 × 5 = 300 回になる。scikit-learn の GridSearchCV も「候補の数 × 分割数」回の学習を行う。ハイパーパラメータの種類が増えると組み合わせの数が掛け算で増えることが、グリッドサーチの弱点である。",
  why: ["候補の数を足した値（5 + 4 + 3）である。グリッドサーチでは組み合わせの数は掛け算になる。", "正しい。5 × 4 × 3 = 60 通りの組み合わせを、それぞれ5回ずつ学習する。", "組み合わせの数（5 × 4 × 3）だけを数えている。5-分割交差検証では、1つの組み合わせにつき5回学習する。", "分割数の5を二重に掛けている（60 × 5 × 5）。"],
  src: [{ t: "scikit-learn API Reference: GridSearchCV", u: "https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.GridSearchCV.html" }, { t: "Bergstra, J. & Bengio, Y. (2012). Random Search for Hyper-Parameter Optimization", u: "https://jmlr.org/papers/v13/bergstra12a.html" }] },
{ id: "M-043", set: "mock", sec: "T16", kw: ["モーメンタム","学習率","勾配降下法"], type: "calc",
  stem: "モーメンタムを使った勾配降下法で、速度 v と重み w を v ← αv − η × ∂E/∂w、w ← w + v の順に更新する。現在 w = 1.0、v = −0.2、α = 0.9、学習率 η = 0.1、勾配 ∂E/∂w = 0.5 のとき、1回更新した後の w の値として正しいものを1つ選べ。",
  choices: ["0.77", "0.95", "0.87", "0.75"],
  ans: 0,
  exp: "モーメンタムでは、前の更新の勢い（速度 v）に係数 α を掛けて残しつつ、新しい勾配を加える。この例では v = −0.18 − 0.05 = −0.23 となり、w は 0.77 になる。前の速度と勾配が同じ向きなので、通常の勾配降下法（0.95）より大きく動いている。同じ向きの勾配が続く方向では加速し、向きが行ったり来たりする方向では打ち消し合って振動が抑えられる。",
  why: ["正しい。v = 0.9 × (−0.2) − 0.1 × 0.5 = −0.23、w = 1.0 − 0.23 = 0.77 である。", "速度を使わない通常の勾配降下法（w − η × ∂E/∂w）の値である。", "勾配の項の符号を誤った値（v = −0.18 + 0.05 = −0.13）である。勾配と逆の向きに進むので、η × ∂E/∂w は引く。", "前の速度に α を掛けずに足した値（v = −0.2 − 0.05 = −0.25）である。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 8 Optimization for Training Deep Models", u: "https://www.deeplearningbook.org/contents/optimization.html" }, { t: "Polyak, B. T. (1964). Some methods of speeding up the convergence of iteration methods", u: "https://doi.org/10.1016/0041-5553(64)90137-5" }] },
{ id: "M-044", set: "mock", sec: "T16", kw: ["AdaGrad","RMSprop","AdaDelta","Adam","AMSBound"], type: "worst",
  stem: "最適化手法とその特徴の組み合わせとして、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["AdaDelta：勾配の二乗の移動平均に加えて、過去の更新量の二乗の移動平均も使い、全体の学習率を手で選ぶ必要をなくすことを目指した", "Adam：勾配の移動平均と勾配の二乗の移動平均を使い、それらを0から始めることによる学習初期の偏りを補正してから更新に使う", "AdaGrad：勾配の二乗の指数移動平均の平方根で学習率を割るため、学習が進んでも学習率が0に近づきにくい", "AMSBound：AMSGrad に学習率の動的な上限と下限を加え、学習が進むにつれて SGD に近い振る舞いへなめらかに移るようにした"],
  ans: 2,
  exp: "学習率を自動で調整する手法は、AdaGrad（勾配の二乗の合計の平方根で割る）→ RMSprop・AdaDelta（合計の代わりに移動平均を使い、学習率が0に近づく問題を改善）→ Adam（勾配の移動平均と二乗の移動平均を併用し、偏りを補正）と発展した。さらに AdaBound・AMSBound は、学習率に動的な上限と下限を設けて、学習の終盤に SGD のように振る舞わせる。",
  why: ["適切。Zeiler（2012）は、AdaGrad の学習率が減り続けることと、全体の学習率を手で選ぶ必要があることの2点を改善するとしている。", "適切。Kingma & Ba（2014）は、0で初期化した移動平均が0の側に偏ることを、偏りの補正（bias correction）で打ち消している。", "不適切（これが正解）。AdaGrad は勾配の二乗をすべて足し合わせた値の平方根で割るため、学習が進むほど学習率が小さくなり、更新が止まりやすい。指数移動平均に替えてこれを改善したのは RMSprop である。", "適切。Luo ら（2019）が AdaBound（Adam に上限・下限を加えたもの）と同じ論文で提案した。"],
  src: [{ t: "Duchi, Hazan & Singer (2011). Adaptive Subgradient Methods for Online Learning and Stochastic Optimization", u: "https://jmlr.org/papers/v12/duchi11a.html" }, { t: "Hinton, G. (2012). Neural Networks for Machine Learning, Lecture 6", u: "https://www.cs.toronto.edu/~tijmen/csc321/slides/lecture_slides_lec6.pdf" }, { t: "Zeiler, M. D. (2012). ADADELTA: An Adaptive Learning Rate Method", u: "https://arxiv.org/abs/1212.5701" }, { t: "Kingma, D. P. & Ba, J. (2014). Adam: A Method for Stochastic Optimization", u: "https://arxiv.org/abs/1412.6980" }, { t: "Luo, Xiong, Liu & Sun (2019). Adaptive Gradient Methods with Dynamic Bound of Learning Rate", u: "https://arxiv.org/abs/1902.09843" }] },
{ id: "M-045", set: "mock", sec: "T16", kw: ["鞍点","局所最適解","大域最適解"], type: "best",
  stem: "深いニューラルネットワークの学習で、訓練誤差がほとんど下がらない平らな区間が長く続いた後、誤差が再び下がり始めた。学習率は適切な大きさで、誤差の振動や増加は見られなかった。この平らな区間について考えられる説明として、最も適切なものを1つ選べ。",
  choices: ["大域最適解に到達していた。大域最適解に到達した後も、学習を続ければ誤差はさらに下がることがある", "学習率が大きすぎて谷を飛び越え、誤差が発散していた", "局所最適解では勾配の大きさが最大になるため、重みが大きく動きすぎて誤差が変わらなかった", "勾配が0に近いが極小ではない鞍点のような点の付近を通っていたため、更新がほとんど進まなかった"],
  ans: 3,
  exp: "誤差関数の表面には、勾配が0でもある方向から見ると極小、別の方向から見ると極大になる鞍点がある。鞍点やそのまわりの平らな領域では勾配が小さく、勾配降下法の動きが遅くなるため、局所最適解で止まったように見えることがある。Dauphin ら（2014）は、高次元の最適化を難しくしている主な原因は、局所最適解よりも鞍点の多さだと論じた。",
  why: ["大域最適解は誤差が最も小さくなる解なので、そこからさらに誤差が下がることはない。誤差が再び下がった以上、大域最適解にいたとはいえない。", "学習率が大きすぎる場合は誤差が振動したり増えたりする。問題文の状況（振動や増加がない）とは合わない。", "局所最適解では勾配は0になる。勾配が最大になるわけではない。", "正しい。鞍点やそのまわりの平らな領域では勾配が小さく、動きが遅くなる。極小でない方向へ抜け出すと、誤差は再び下がる。"],
  src: [{ t: "Dauphin et al. (2014). Identifying and attacking the saddle point problem in high-dimensional non-convex optimization", u: "https://arxiv.org/abs/1406.2572" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 8 Optimization for Training Deep Models", u: "https://www.deeplearningbook.org/contents/optimization.html" }] },
{ id: "M-046", set: "mock", sec: "T16", kw: ["二重降下現象"], type: "blank",
  stem: "Belkin ら（2019）は、モデルを大きくしていくとテスト誤差がいったん悪化した後、（ア）を超えたあたりから再び下がる「二重降下」の曲線を示した。Nakkiran ら（2019）は、深層学習でこの現象がモデルの大きさだけでなく（イ）についても起こること、さらに条件によっては（ウ）とテストでの性能がかえって下がる場合があることを示した。（ア）〜（ウ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）モデルが訓練データにちょうど完全に当てはまる規模（補間のしきい値）（イ）学習のエポック数（ウ）訓練データを増やす", "（ア）訓練誤差が最大になる規模（イ）学習率（ウ）モデルを小さくする", "（ア）モデルが訓練データにちょうど完全に当てはまる規模（補間のしきい値）（イ）学習率（ウ）正則化を強める", "（ア）パラメータの数が訓練データの件数の半分になる規模（イ）学習のエポック数（ウ）検証データを減らす"],
  ans: 0,
  exp: "従来のバイアスとバリアンスのトレードオフの考え方では、モデルを複雑にしすぎるとテスト誤差は悪化し続けるとされてきた。Belkin ら（2019）は、訓練データにちょうど当てはまる規模（補間のしきい値）を超えてさらにモデルを大きくすると、テスト誤差が再び下がることを示した。Nakkiran ら（2019）は、この現象が学習のエポック数についても起こり、条件によっては訓練データを増やす（4倍にしても）とテストでの性能が下がる場合があることを示した。",
  why: ["正しい。Nakkiran らの論文の題名も「大きなモデルと多くのデータがかえって性能を下げる場合」を表している。", "モデルを大きくすると訓練誤差は下がっていき、補間のしきい値で訓練データにほぼ完全に当てはまる。Nakkiran らが示したのは、エポック数についての二重降下と、訓練データを増やすと性能が下がる場合である。", "（ア）は正しいが、Nakkiran らが示したのは学習率ではなくエポック数についての二重降下と、訓練データの量についての逆転である。", "テスト誤差が再び下がり始めるのは、モデルが訓練データに完全に当てはまる規模（補間のしきい値）を超えたあたりである。検証データの量は、論文が示した現象とは関係がない。"],
  src: [{ t: "Belkin, Hsu, Ma & Mandal (2019). Reconciling modern machine-learning practice and the classical bias–variance trade-off", u: "https://doi.org/10.1073/pnas.1903070116" }, { t: "Nakkiran et al. (2019). Deep Double Descent: Where Bigger Models and More Data Hurt", u: "https://arxiv.org/abs/1912.02292" }] },
{ id: "M-047", set: "mock", sec: "T16", kw: ["ハイパーパラメータ","早期終了","ランダムサーチ","ノーフリーランチの定理"], type: "worst",
  stem: "ハイパーパラメータの調整と汎化に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["ハイパーパラメータは検証データでの性能をもとに選び、テストデータは最終的な性能の評価にだけ使う", "ノーフリーランチの定理により、ランダムサーチは、どのような問題でもグリッドサーチより良いハイパーパラメータを見つけられることが保証されている", "早期終了では、検証データの誤差が決めた回数続けて改善しなければ学習を止め、検証誤差が最も小さかったときの重みを使う", "グリッドサーチでは、ハイパーパラメータの種類が増えると、試す組み合わせの数が掛け算で増える"],
  ans: 1,
  exp: "Bergstra と Bengio（2012）は、多くの問題では性能に大きく効くハイパーパラメータが少数であるため、ランダムサーチは同じ試行回数でもグリッドサーチより効率よく良い設定を見つけやすいことを、実験と理論で示した。これは「多くの場合に効率的」という主張であり、どんな問題でも必ず勝つという保証ではない。ノーフリーランチの定理（Wolpert & Macready, 1997）は、むしろ、あらゆる問題で最も優れた万能の手法は存在しないことを示している。",
  why: ["適切。テストデータで選ぶと、テストデータに合わせ込むことになり、最終的な性能を正しく評価できなくなる。", "不適切（これが正解）。ノーフリーランチの定理は、すべての問題で平均するとどの最適化アルゴリズムの性能も同じになることを示したもので、ある手法があらゆる問題で優れていることを保証するものではない。", "適切。教科書 Deep Learning の早期終了のアルゴリズムも、決めた回数（patience）改善しなければ止め、最良だったときのパラメータを返す。", "適切。例えば4種類を5通りずつ試すと 5⁴ = 625 通りになる。"],
  src: [{ t: "Bergstra, J. & Bengio, Y. (2012). Random Search for Hyper-Parameter Optimization", u: "https://jmlr.org/papers/v13/bergstra12a.html" }, { t: "Wolpert, D. H. & Macready, W. G. (1997). No free lunch theorems for optimization", u: "https://doi.org/10.1109/4235.585893" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 7 Regularization for Deep Learning", u: "https://www.deeplearningbook.org/contents/regularization.html" }] },
{ id: "M-048", set: "mock", sec: "T16", kw: ["バッチ学習","ミニバッチ学習","オンライン学習","確率的勾配降下法 (SGD)","エポック","イテレーション"], type: "best",
  stem: "訓練データ N 件を使う勾配降下法の学習方法に関する説明として、最も適切なものを1つ選べ。",
  choices: ["バッチ学習は、訓練データ全体を1回使い切る1エポックの間に、N 回重みを更新する", "ミニバッチ学習は、1回の更新に使うデータが訓練データ全体より少ないので、バッチ学習よりも勾配のばらつきが小さい", "オンライン学習はバッチサイズ1のミニバッチ学習とみなせ、1エポックで N 回重みを更新するが、1件ごとの偏りに引っぱられて更新がばらつきやすい", "確率的勾配降下法（SGD）の勾配のばらつきは学習の進み方を乱すだけであり、鞍点から抜け出す助けになるとは考えられていない"],
  ans: 2,
  exp: "1回の更新に使うデータの量で、バッチ学習（全データ、1エポックで1回更新）、ミニバッチ学習（少数ずつ、1エポックで N ÷ バッチサイズ回）、オンライン学習（1件ずつ、1エポックで N 回）に分かれる。使うデータが少ないほど1回の計算は軽いが、勾配のばらつきは大きくなる。そのばらつきは、鞍点から抜け出す助けにもなると考えられている。",
  why: ["バッチ学習は訓練データ全体で勾配を計算してから1回だけ更新するので、1エポックで1回の更新になる。", "逆である。一部のデータから求めた勾配は全データの勾配をばらつきを含んで推定したものなので、全データを使うバッチ学習よりばらつきが大きい。", "正しい。1エポック＝（データ数 ÷ バッチサイズ）イテレーションなので、バッチサイズ1なら N 回になる。", "勾配のばらつきは、鞍点などから抜け出す助けにもなると考えられている（Ge ら, 2015 など）。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 8 Optimization for Training Deep Models", u: "https://www.deeplearningbook.org/contents/optimization.html" }, { t: "Ge, Huang, Jin & Yuan (2015). Escaping From Saddle Points --- Online Stochastic Gradient for Tensor Decomposition", u: "https://arxiv.org/abs/1503.02101" }] },
/* ── T17 全結合層 ── */
{ id: "M-049", set: "mock", sec: "T17", kw: ["重み"], type: "calc",
  stem: "784 個の入力を受け取り、隠れ層1（256 ニューロン）、隠れ層2（128 ニューロン）、出力層（10 ニューロン）を順に全結合層でつないだネットワークがある。各ニューロンはバイアスを1つずつ持つ。このネットワークの学習するパラメータ（重みとバイアス）の総数として、正しいものを1つ選べ。",
  choices: ["1,178", "200,960", "234,752", "235,146"],
  ans: 3,
  exp: "全結合層のパラメータ数は（入力の数 ＋ 1）×（出力の数）で、＋1 はバイアスの分である。(784 ＋ 1) × 256 ＝ 200,960、(256 ＋ 1) × 128 ＝ 32,896、(128 ＋ 1) × 10 ＝ 1,290 で、合計 235,146 になる。パラメータの大部分は、入力の数が多い最初の層に集中している。",
  why: ["各層のニューロンの数を足した値（784 ＋ 256 ＋ 128 ＋ 10）である。パラメータの数は、つながる2つの層のニューロンの数の積で決まる。", "入力から隠れ層1への全結合層だけの数（(784 ＋ 1) × 256）である。残りの2つの層の分も足す必要がある。", "バイアスを数えていない値（784 × 256 ＋ 256 × 128 ＋ 128 × 10）である。", "正しい。200,960 ＋ 32,896 ＋ 1,290 ＝ 235,146 である。"],
  src: [{ t: "PyTorch documentation: torch.nn.Linear", u: "https://docs.pytorch.org/docs/stable/generated/torch.nn.Linear.html" }] },
/* ── T18 畳み込み層 ── */
{ id: "M-050", set: "mock", sec: "T18", kw: ["パディング","ストライド","フィルタ","特徴マップ"], type: "calc",
  stem: "縦64×横64×3チャネルの入力に、5×5 のフィルタを 16 個使い、パディング2、ストライド1で畳み込みを行う。各フィルタはバイアスを1つずつ持つ。出力の特徴マップの大きさ（縦×横×チャネル数）と、この層の学習するパラメータの数の組み合わせとして、正しいものを1つ選べ。",
  choices: ["64×64×16、1,216 個", "60×60×16、1,216 個", "64×64×16、1,200 個", "64×64×48、1,216 個"],
  ans: 0,
  exp: "出力の縦横は ⌊(I ＋ 2P − K) ÷ S⌋ ＋ 1 で求める。I ＝ 64、K ＝ 5、P ＝ 2、S ＝ 1 なら 64 になり、入力と同じ大きさが保たれる。出力のチャネル数（特徴マップの枚数）はフィルタの数に等しい。各フィルタは入力の全チャネル分の重み（5 × 5 × 3 ＝ 75 個）とバイアス1つをもつので、パラメータ数は 76 × 16 ＝ 1,216 で、入力画像の縦横の大きさにはよらない。",
  why: ["正しい。縦横は (64 ＋ 4 − 5) ÷ 1 ＋ 1 ＝ 64、チャネル数はフィルタの数の 16、パラメータは (5 × 5 × 3 ＋ 1) × 16 ＝ 1,216 である。", "パディングを考えずに (64 − 5) ÷ 1 ＋ 1 ＝ 60 とした値である。両側に2画素ずつ加わるので 2P ＝ 4 を足す。", "バイアスを数えていない値（5 × 5 × 3 × 16）である。", "出力のチャネル数はフィルタの数（16）に等しい。入力のチャネル数（3）を掛ける必要はない。"],
  src: [{ t: "Dumoulin, V. & Visin, F. (2016). A guide to convolution arithmetic for deep learning", u: "https://arxiv.org/abs/1603.07285" }, { t: "PyTorch documentation: torch.nn.Conv2d", u: "https://docs.pytorch.org/docs/stable/generated/torch.nn.Conv2d.html" }] },
{ id: "M-051", set: "mock", sec: "T18", kw: ["Depthwise Separable Convolution","Dilated Convolution","Atrous Convolution"], type: "best",
  stem: "次の（ア）（イ）の要望に適した畳み込みの手法の組み合わせとして、最も適切なものを1つ選べ。<br>（ア）スマートフォンで動かす画像分類のモデルで、畳み込みのパラメータ数と計算量を大幅に減らしたい<br>（イ）画素ごとにクラスを判定するセマンティックセグメンテーションで、特徴マップの解像度を落とさず、パラメータも増やさずに、各出力が見る入力の範囲（受容野）を広げたい",
  choices: ["（ア）Atrous Convolution（イ）Depthwise Separable Convolution", "（ア）Depthwise Separable Convolution（イ）カーネルを 3×3 から 7×7 に大きくした通常の畳み込み", "（ア）Depthwise Separable Convolution（イ）Atrous Convolution", "（ア）ストライド1の通常の 3×3 の畳み込み（イ）最大値プーリングを重ねて特徴マップを縮小する"],
  ans: 2,
  exp: "Depthwise Separable Convolution は、チャネルごとの畳み込み（Depthwise）と 1×1 の畳み込み（Pointwise）に分けることで、3×3 のカーネルなら計算量をおよそ 1/8〜1/9 にする（Howard ら, 2017）。Dilated Convolution（Atrous Convolution）は、カーネルの要素の間を空けて入力に当てることで、重みの数を変えずに受容野を広げる。Yu & Koltun（2016）は、解像度を失わずに受容野を広げられる点をセグメンテーションに生かした。",
  why: ["逆である。Atrous Convolution は受容野を広げる手法で、計算を軽くするための手法ではない。", "カーネルを大きくすると受容野は広がるが、重みの数が増える。「パラメータを増やさずに」という要望に合わない。", "正しい。（ア）は MobileNet などで使われる手法、（イ）は DeepLab で使われる手法である。Atrous Convolution は Dilated Convolution の別名である。", "通常の畳み込みのままでは、パラメータ数も計算量も減らない。プーリングを重ねると受容野は広がるが、特徴マップの解像度が下がる。"],
  src: [{ t: "Howard et al. (2017). MobileNets: Efficient Convolutional Neural Networks for Mobile Vision Applications", u: "https://arxiv.org/abs/1704.04861" }, { t: "Chen et al. (2018). DeepLab: Semantic Image Segmentation with Deep Convolutional Nets, Atrous Convolution, and Fully Connected CRFs", u: "https://doi.org/10.1109/TPAMI.2017.2699184" }, { t: "Yu, F. & Koltun, V. (2016). Multi-Scale Context Aggregation by Dilated Convolutions", u: "https://arxiv.org/abs/1511.07122" }] },
{ id: "M-052", set: "mock", sec: "T18", kw: ["畳み込みニューラルネットワーク (CNN)","畳み込み操作","カーネル"], type: "worst",
  stem: "畳み込み層と畳み込みニューラルネットワーク（CNN）に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["多くの深層学習ライブラリが「畳み込み」として計算しているのはカーネルを反転しない相互相関だが、カーネルの値は学習で決まるので、学習できる内容は変わらない", "畳み込み層のパラメータの数は、入力画像の縦横の大きさに比例して増える", "1×1 の畳み込みは、縦横の範囲を広げずに各位置でチャネル方向の重み付き和をとるので、チャネル数の変更やチャネル間の情報の混ぜ合わせに使われる", "CNN は画像のほか、音声の波形や時系列データのように、近くの値どうしが強く関係するデータにも使われる"],
  ans: 1,
  exp: "畳み込み層は、局所的な結合と重み共有（同じフィルタを全位置で使い回すこと）によって、全結合層よりはるかに少ないパラメータで済む。パラメータ数はカーネルの大きさ・入力チャネル数・フィルタの数で決まり、入力の縦横の大きさには関係しない。一方、計算量（積和の回数）は出力の位置の数に比例するので、入力が大きいほど増える。",
  why: ["適切。教科書 Deep Learning も、多くのライブラリは相互相関を実装して畳み込みと呼んでいると説明している。", "不適切（これが正解）。同じフィルタを入力のすべての位置で使い回すので、パラメータ数は（K × K × 入力チャネル数 ＋ 1）× フィルタの数で決まり、入力画像の縦横の大きさにはよらない。", "適切。MobileNet の Pointwise Convolution や、ResNet のボトルネック構造でチャネル数を減らす層として使われる。", "適切。時間の軸に沿って1次元の畳み込みを行う。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 9 Convolutional Networks", u: "https://www.deeplearningbook.org/contents/convnets.html" }, { t: "Howard et al. (2017). MobileNets: Efficient Convolutional Neural Networks for Mobile Vision Applications", u: "https://arxiv.org/abs/1704.04861" }, { t: "He, Zhang, Ren & Sun (2016). Deep Residual Learning for Image Recognition", u: "https://arxiv.org/abs/1512.03385" }] },
/* ── T19 正規化層 ── */
{ id: "M-053", set: "mock", sec: "T19", kw: ["グループ正規化","バッチ正規化"], type: "best",
  stem: "高解像度の画像を使う物体検出のモデルを学習する。GPU のメモリの制約から、GPU 1台あたりのバッチサイズは2しか取れない。この状況での正規化層の選び方として、最も適切なものを1つ選べ。",
  choices: ["バッチ正規化を使う。バッチサイズが小さいほど、ミニバッチの平均と分散を正確に推定できるため", "どの正規化層も、推論時は学習中に記録した平均と分散の移動平均を使うので、バッチサイズの影響は正規化の種類によらず同じであり、どれを選んでも差はない", "正規化層は過学習を防ぐ正則化の一種なので、正規化層を外し、代わりに L2 正則化を強めれば同じ効果が得られる", "グループ正規化を使う。データ1件ごとにチャネルのグループ内で平均と分散を求めるので、バッチサイズに左右されにくい"],
  ans: 3,
  exp: "バッチ正規化はミニバッチ内のデータで平均と分散を求めるため、バッチサイズが小さいと統計量の推定が不正確になる。物体検出・セグメンテーション・動画のように、メモリの制約で小さなバッチしか使えない課題で問題になる。グループ正規化はバッチ方向の統計を使わず、データごとにチャネルのグループ内で正規化するので、バッチサイズによらず安定した性能を示す。",
  why: ["逆である。バッチ正規化はミニバッチ内の統計量に頼るので、バッチサイズが小さいと推定が不正確になり、性能が落ちる。", "移動平均を推論時に使うのはバッチ正規化である。グループ正規化やレイヤー正規化は、学習時も推論時も、その入力自体から統計量を求める。", "正規化層の主な役割は、途中の値の分布をそろえて学習を速く安定させることである。正則化（過学習を防ぐための制約）とは別物で、L2 正則化で置き換えられるものではない。", "正しい。Wu & He（2018）は、ImageNet の画像分類（ResNet-50）でバッチサイズが2のとき、グループ正規化の誤り率がバッチ正規化より 10.6 ポイント低かった（24.1% 対 34.7%）と報告している。物体検出（COCO）でも、バッチ正規化の代わりに使えることを示している。"],
  src: [{ t: "Wu, Y. & He, K. (2018). Group Normalization", u: "https://arxiv.org/abs/1803.08494" }, { t: "Ioffe, S. & Szegedy, C. (2015). Batch Normalization: Accelerating Deep Network Training by Reducing Internal Covariate Shift", u: "https://arxiv.org/abs/1502.03167" }] },
/* ── T20 プーリング層 ── */
{ id: "M-054", set: "mock", sec: "T20", kw: ["最大値プーリング"], type: "best",
  stem: "プーリング層の設計に関する説明として、最も適切なものを1つ選べ。",
  choices: ["プーリングの領域を互いに重なるように動かすこともでき、AlexNet は 3×3 の領域をストライド2で動かす最大値プーリングを使った", "プーリング層は、最大値や平均値を正しく求めるための重みを学習するので、そのパラメータもモデルのパラメータ数に数える", "プーリングはチャネル方向にも値をまとめるので、出力の特徴マップのチャネル数は1になる", "プーリング層の代わりにストライド2の畳み込み層で特徴マップを縮小しても、学習するパラメータを持たない点はプーリング層と同じである"],
  ans: 0,
  exp: "プーリング層は、領域ごとに最大値や平均値をとって特徴マップを縮小する。学習するパラメータを持たず、チャネルごとに処理するのでチャネル数は変わらない。領域どうしを重ねて動かす方法もあり、AlexNet（Krizhevsky ら, 2012）は 3×3 の領域をストライド2で動かす最大値プーリングを使い、過学習もやや起きにくくなったと述べている。",
  why: ["正しい。原論文は、重なりのない 2×2・ストライド2 の場合と比べて、top-1・top-5 の誤り率がそれぞれ 0.4%・0.3% 下がったと報告している。", "プーリング層は、領域の大きさとストライドを決めれば計算が決まり、学習するパラメータを持たない。", "プーリングはチャネルごとに独立に行うので、チャネル数は変わらない。小さくなるのは縦横だけである。", "ストライド2の畳み込み層は、縮小しながらフィルタの重みを学習する。プーリングの代わりにこれを使う設計（Springenberg ら, 2015 など）もあるが、パラメータを持つ点が異なる。"],
  src: [{ t: "Krizhevsky, Sutskever & Hinton (2012). ImageNet Classification with Deep Convolutional Neural Networks", u: "https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html" }, { t: "Springenberg, Dosovitskiy, Brox & Riedmiller (2015). Striving for Simplicity: The All Convolutional Net", u: "https://arxiv.org/abs/1412.6806" }] },
/* ── T22 回帰結合層 ── */
{ id: "M-055", set: "mock", sec: "T22", kw: ["双方向 RNN (Bidirectional RNN)","時系列データ"], type: "best",
  stem: "双方向 RNN（Bidirectional RNN）をそのまま使うのに、最も適した課題を1つ選べ。",
  choices: ["工場のセンサーの値が1秒ごとに届くたびに、その時点までの値だけを使って、すぐに異常かどうかを判定する", "文章を1単語ずつ生成し、生成した単語を次の入力に使いながら続きを書いていく", "録音を終えた会話の音声ファイル全体を読み込んでから、各時点で話されている音素を判定する", "毎時刻の株価が届くたびに、次の時刻の株価を予測して、その場で売買の判断に使う"],
  ans: 2,
  exp: "双方向 RNN（Schuster & Paliwal, 1997）は、系列を前から処理する RNN と後ろから処理する RNN を組み合わせ、各時刻で過去と未来の両方の情報を使う。そのため、録音済みの音声の認識や、文全体を読んでからの品詞の判定のように、系列全体が先に分かっている課題に向く。届いたデータで即座に判断する課題や、1つずつ生成する課題には、そのままでは使えない。",
  why: ["判定の時点では、まだ届いていない後の値を使えない。後ろから処理する RNN の入力がそろわない。", "生成の時点では、後に続く単語はまだ存在しないので、後ろから処理する RNN を使えない。", "正しい。系列全体が先に分かっているので、各時点の判定に、その時点より前と後の両方の音を手がかりとして使える。", "予測の時点では未来の値が分からないので、系列の後ろからの処理を使えない。"],
  src: [{ t: "Schuster, M. & Paliwal, K. K. (1997). Bidirectional recurrent neural networks", u: "https://doi.org/10.1109/78.650093" }, { t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 10 Sequence Modeling: Recurrent and Recursive Nets", u: "https://www.deeplearningbook.org/contents/rnn.html" }] },
{ id: "M-056", set: "mock", sec: "T22", kw: ["リカレントニューラルネットワーク (RNN)"], type: "calc",
  stem: "入力が10次元、隠れ状態が20次元の単純な RNN を考える。隠れ状態は h<sub>t</sub> = tanh(W<sub>x</sub>x<sub>t</sub> ＋ W<sub>h</sub>h<sub>t−1</sub> ＋ b) で計算し、W<sub>x</sub> は 20×10 の行列、W<sub>h</sub> は 20×20 の行列、b は20個の値からなる。この RNN で長さ50の系列を処理するとき、この式に含まれる学習するパラメータの総数として、正しいものを1つ選べ。",
  choices: ["220", "620", "31,000", "600"],
  ans: 1,
  exp: "W<sub>x</sub> が 20 × 10 ＝ 200、W<sub>h</sub> が 20 × 20 ＝ 400、b が 20 で、合計 620 である。RNN は同じ重みをすべての時刻で使い回すので、系列が長くなってもパラメータの数は増えない。そのため、学習時と異なる長さの系列も同じネットワークで扱える。",
  why: ["回帰結合の重み W<sub>h</sub>（20 × 20 ＝ 400）を数えていない値である。", "正しい。200 ＋ 400 ＋ 20 ＝ 620 で、系列の長さにはよらない。", "時刻ごとに別の重みがあるとして 50 倍した値である。RNN の重みは全時刻で共有される。", "バイアス b の20個を数えていない値である。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 10 Sequence Modeling: Recurrent and Recursive Nets", u: "https://www.deeplearningbook.org/contents/rnn.html" }, { t: "Elman, J. L. (1990). Finding Structure in Time", u: "https://doi.org/10.1207/s15516709cog1402_1" }] },
{ id: "M-057", set: "mock", sec: "T22", kw: ["BPTT","教師強制","GRU","LSTM"], type: "worst",
  stem: "RNN の学習に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["BPTT では、系列が長いほど展開したネットワークが深くなるため、順伝播の途中の値を保存するメモリと計算量が増え、勾配消失・勾配爆発も起きやすくなる", "教師強制で学習したモデルは、推論時には自分の予測を次の入力に使うため、学習時と推論時で入力の性質が異なり、一度の誤りが後に積み重なりやすい", "GRU はリセットゲートと更新ゲートの2つのゲートをもち、記憶セルを持たないので、同じ大きさの隠れ状態なら3つのゲートと記憶セルをもつ LSTM よりパラメータが少ない", "BPTT では、時間方向に展開した各時刻に別々の重みがあるとみなし、各時刻の重みをその時刻の勾配だけで別々に更新する"],
  ans: 3,
  exp: "BPTT（Werbos, 1990）は、RNN を時間方向に展開して1つの深いネットワークとみなし、誤差逆伝播法を適用する方法である。展開しても各時刻の重みは同じものなので、共有する重みの勾配は全時刻の分を合計して求める。系列が長いと計算量・メモリが増え、勾配消失・勾配爆発も起きやすい。",
  why: ["適切。教科書 Deep Learning も、BPTT の計算量とメモリは系列の長さに比例して増えると説明している。", "適切。これを和らげるため、学習が進むにつれてモデル自身の予測を入力に使う割合を増やすスケジュールドサンプリング（Bengio ら, 2015）などが提案された。", "適切。GRU は Cho ら（2014）が提案した、LSTM を簡略化したユニットである。", "不適切（これが正解）。RNN の重みは全時刻で共有されている。BPTT では、共有する重みの勾配を、すべての時刻の分を足し合わせて求め、1つの重みとして更新する。"],
  src: [{ t: "Goodfellow, Bengio & Courville. Deep Learning, Chapter 10 Sequence Modeling: Recurrent and Recursive Nets", u: "https://www.deeplearningbook.org/contents/rnn.html" }, { t: "Werbos, P. J. (1990). Backpropagation through time: what it does and how to do it", u: "https://doi.org/10.1109/5.58337" }, { t: "Cho et al. (2014). Learning Phrase Representations using RNN Encoder-Decoder for Statistical Machine Translation", u: "https://arxiv.org/abs/1406.1078" }, { t: "Bengio, Vinyals, Jaitly & Shazeer (2015). Scheduled Sampling for Sequence Prediction with Recurrent Neural Networks", u: "https://arxiv.org/abs/1506.03099" }] },
/* ── T23 Attention ── */
{ id: "M-058", set: "mock", sec: "T23", kw: ["クエリ","キー","バリュー","Attention"], type: "calc",
  stem: "ある位置のクエリと、3つのキー k<sub>1</sub> ＝ (4, 2)、k<sub>2</sub> ＝ (0, 2)、k<sub>3</sub> ＝ (1, 3) との類似度をソフトマックス関数に通したところ、重みは (0.5, 0.3, 0.2) となった。それぞれのキーに対応するバリューが v<sub>1</sub> ＝ (2, 0)、v<sub>2</sub> ＝ (0, 10)、v<sub>3</sub> ＝ (5, 5) のとき、Attention の出力として正しいものを1つ選べ。",
  choices: ["(2.2, 2.2)", "約 (2.33, 5)", "(2, 4)", "(2, 0)"],
  ans: 2,
  exp: "Attention では、クエリと各キーの類似度をソフトマックス関数で合計1の重みに変え、その重みでバリューを加重平均したものを出力とする。重み（どこに注目するか）を決めるのはクエリとキーで、取り出す中身はバリューである。",
  why: ["重みでキーを加重平均した値である。キーは重みを決めるために使い、出力として取り出すのはバリューである。", "重みを使わずにバリューを単純に平均した値である。", "正しい。0.5 × (2, 0) ＋ 0.3 × (0, 10) ＋ 0.2 × (5, 5) ＝ (1, 0) ＋ (0, 3) ＋ (1, 1) ＝ (2, 4) である。", "重みが最も大きい v<sub>1</sub> だけを取り出した値である。Attention は、すべてのバリューを重みで加重平均する。"],
  src: [{ t: "Vaswani et al. (2017). Attention Is All You Need", u: "https://arxiv.org/abs/1706.03762" }, { t: "Bahdanau, Cho & Bengio (2014). Neural Machine Translation by Jointly Learning to Align and Translate", u: "https://arxiv.org/abs/1409.0473" }] },
{ id: "M-059", set: "mock", sec: "T23", kw: ["Transformer","Self-Attention","Source-Target Attention"], type: "blank",
  stem: "Transformer のデコーダの各層は、（ア）、（イ）、位置ごとの全結合層の3つのサブ層からなる。（ア）では、各位置がまだ生成していない後ろの位置を参照しないように隠したうえで、デコーダ側の系列の中の関係を計算する。（イ）では、クエリをデコーダ側から、キーとバリューをエンコーダの出力から作る。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）Masked Self-Attention（イ）Source-Target Attention", "（ア）Source-Target Attention（イ）Masked Self-Attention", "（ア）Masked Self-Attention（イ）エンコーダの各層と同じ Self-Attention", "（ア）双方向 RNN（イ）Source-Target Attention"],
  ans: 0,
  exp: "Transformer（Vaswani ら, 2017）のエンコーダの各層は Self-Attention と位置ごとの全結合層からなり、デコーダの各層はこれに、エンコーダの出力に対する Attention（Source-Target Attention）を加えた3つのサブ層からなる。デコーダの Self-Attention では、まだ生成していない後ろの位置を参照しないよう、該当する値を −∞ にして隠す（マスクする）。",
  why: ["正しい。（イ）は原論文では encoder-decoder attention と呼ばれている。", "逆である。後ろの位置を隠して同じ系列の中の関係を計算するのは Masked Self-Attention、クエリとキー・バリューの出どころが異なるのは Source-Target Attention である。", "Self-Attention はクエリ・キー・バリューをすべて同じ系列から作る。キーとバリューをエンコーダの出力から作るのは Source-Target Attention である。", "Transformer は回帰結合（RNN）を使わない。また、生成の時点で後ろの位置は参照できないので、双方向に処理することもできない。"],
  src: [{ t: "Vaswani et al. (2017). Attention Is All You Need", u: "https://arxiv.org/abs/1706.03762" }] },
{ id: "M-060", set: "mock", sec: "T23", kw: ["Seq2Seq","Attention","位置エンコーディング","Multi-Head Attention"], type: "worst",
  stem: "Seq2Seq から Transformer への発展に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Sutskever ら（2014）の Seq2Seq は、Attention を使わずに入力文を固定長のベクトルにまとめ、入力文の単語の順序を逆にすると性能が大きく上がると報告した", "Multi-Head Attention では、各ヘッドがモデルの全次元のまま Attention を計算するので、全体の計算量はヘッドの数にほぼ比例して増える", "Bahdanau ら（2014）は、デコーダが訳語を1つ出すたびに入力文の各単語への重みを計算し直す Attention を、機械翻訳に導入した", "Transformer の原論文は、学習で求める位置の埋め込みも試し、sin・cos 関数による位置エンコーディングとほぼ同じ結果を得た"],
  ans: 1,
  exp: "Seq2Seq（Sutskever ら, 2014）は入力文を固定長のベクトルにまとめるため、長い文で情報が失われやすかった。Bahdanau ら（2014）はこれを補う Attention を導入し、Vaswani ら（2017）は RNN を使わず Attention を中心に構成した Transformer を提案した。Multi-Head Attention は各ヘッドの次元を d<sub>model</sub> ÷ ヘッド数に小さくするので、計算量を大きく増やさずに、ヘッドごとに異なる観点で注目先を学習できる。",
  why: ["適切。入力文の単語の順序を逆にすると、入力と出力の近い単語どうしの距離が縮まり、学習しやすくなると説明している。", "不適切（これが正解）。原論文の基本の構成では d<sub>model</sub> ＝ 512 を8ヘッドに分け、各ヘッドの次元を 64 に小さくしているので、全体の計算量は全次元で1つの Attention を計算する場合とほぼ同じである。", "適切。固定長のベクトル1つに頼る必要がなくなり、長い文でも翻訳しやすくなった。", "適切。学習時より長い系列にも対応できる可能性があるとして、sin・cos の方式を選んだ。"],
  src: [{ t: "Sutskever, Vinyals & Le (2014). Sequence to Sequence Learning with Neural Networks", u: "https://arxiv.org/abs/1409.3215" }, { t: "Bahdanau, Cho & Bengio (2014). Neural Machine Translation by Jointly Learning to Align and Translate", u: "https://arxiv.org/abs/1409.0473" }, { t: "Vaswani et al. (2017). Attention Is All You Need", u: "https://arxiv.org/abs/1706.03762" }] },
/* ── T24 オートエンコーダ ── */
{ id: "M-061", set: "mock", sec: "T24", kw: ["VQ-VAE・ info VAE・β-VAE","変分オートエンコーダ (VAE)"], type: "best",
  stem: "変分オートエンコーダ（VAE）を改良した手法を使って、次の（ア）〜（ウ）を実現したい。それぞれに適した手法の組み合わせとして、最も適切なものを1つ選べ。<br>（ア）顔画像の生成で、潜在変数のある1つの次元を動かすと顔の向きだけが、別の次元を動かすと照明の当たり方だけが変わるような表現を得たい<br>（イ）潜在表現を離散的な記号の並びとして扱い、その並びの分布を自己回帰モデル（PixelCNN など）で別に学習して、高品質な画像を生成したい<br>（ウ）表現力の高いデコーダを使うと、デコーダだけでデータを再現できてしまい潜在変数が使われなくなる。入力と潜在変数の結び付きが保たれるような項を目的関数に加えたい",
  choices: ["（ア）VQ-VAE（イ）β-VAE（ウ）InfoVAE", "（ア）β-VAE（イ）InfoVAE（ウ）VQ-VAE", "（ア）InfoVAE（イ）VQ-VAE（ウ）β-VAE", "（ア）β-VAE（イ）VQ-VAE（ウ）InfoVAE"],
  ans: 3,
  exp: "β-VAE（Higgins ら, 2017）は、KL ダイバージェンスの項に1より大きい係数 β を掛け、潜在変数の各次元がデータの異なる要因を別々に表す表現を得やすくする。VQ-VAE（van den Oord ら, 2017）は、エンコーダの出力をコードブックの最も近いベクトルに置き換えて離散的な潜在表現にし、その並びの事前分布を PixelCNN などの自己回帰モデルで学習する。InfoVAE（Zhao ら, 2017）は、入力と潜在変数の相互情報量を大きく保つ項を加え、潜在変数が無視されにくくする。",
  why: ["（ア）と（イ）が逆である。潜在変数の次元ごとに異なる要因を表す（もつれのない）表現をねらうのが β-VAE、潜在表現を離散的なコードにするのが VQ-VAE である。", "（イ）と（ウ）が逆である。コードブックで潜在表現を離散化するのが VQ-VAE、入力と潜在変数の相互情報量を大きく保つ項を加えるのが InfoVAE である。", "（ア）と（ウ）が逆である。β-VAE は KL ダイバージェンスの項を強めてもつれのない表現をねらう手法で、相互情報量を保つ項を加えるのは InfoVAE である。", "正しい。β-VAE はもつれのない表現、VQ-VAE は離散的な潜在表現、InfoVAE は相互情報量を保つ項を特徴とする。"],
  src: [{ t: "Higgins et al. (2017). beta-VAE: Learning Basic Visual Concepts with a Constrained Variational Framework（ICLR 2017）", u: "https://openreview.net/forum?id=Sy2fzU9gl" }, { t: "van den Oord, Vinyals & Kavukcuoglu (2017). Neural Discrete Representation Learning", u: "https://arxiv.org/abs/1711.00937" }, { t: "Zhao, Song & Ermon (2019). InfoVAE: Balancing Learning and Inference in Variational Autoencoders（AAAI 2019。arXiv の第1版〔2017年6月〕の題名は InfoVAE: Information Maximizing Variational Autoencoders）", u: "https://doi.org/10.1609/aaai.v33i01.33015885" }] },
/* ── T25 データ拡張 ── */
{ id: "M-062", set: "mock", sec: "T25", kw: ["CutMix"], type: "calc",
  stem: "CutMix で、32×32 画素の画像 A のある領域を、画像 B の同じ位置の領域で置き換える。置き換える領域を 16×16 画素として中心を決めたところ、中心が画像の右端に近かったため領域の一部が画像の外にはみ出し、画像の内側で実際に置き換わったのは縦16×横8画素だった。原論文の手順どおり、実際に置き換わった面積の割合でラベルを混ぜるとき、混ぜた後のラベルとして正しいものを1つ選べ。",
  choices: ["A 0.75、B 0.25", "A 0.5、B 0.5", "A 0.875、B 0.125", "A 0.125、B 0.875"],
  ans: 2,
  exp: "CutMix（Yun ら, 2019）は、画像 A の長方形の領域を画像 B の同じ位置の領域で置き換え、ラベルを面積の割合で混ぜる。原論文の疑似コードでは、領域を画像の範囲に切り詰めた後、λ ＝ 1 −（置き換えた面積）÷（画像の面積）として、λ を実際の面積の割合に合わせ直している。この例では λ ＝ 1 − 128 ÷ 1,024 ＝ 0.875 で、ラベルは「A 0.875、B 0.125」となる。",
  why: ["はみ出す前の領域（16 × 16 ＝ 256 画素、25%）で計算した値である。原論文の手順では、画像の内側に切り詰めた後の面積で割合を求め直す。", "CutMix では、置き換えた面積の割合に応じてラベルを混ぜる。常に半分ずつにするわけではない。", "正しい。実際に置き換わった面積は 16 × 8 ＝ 128 画素で、画像全体 1,024 画素の 12.5% なので、B が 0.125、A が 0.875 になる。", "A と B が逆である。置き換えた領域が B の割合になる。"],
  src: [{ t: "Yun et al. (2019). CutMix: Regularization Strategy to Train Strong Classifiers with Localizable Features", u: "https://arxiv.org/abs/1905.04899" }] },
{ id: "M-063", set: "mock", sec: "T25", kw: ["RandAugument"], type: "best",
  stem: "画像分類で、データ拡張の方針（どの変換をどの強さで使うか）を自動で決めたい。ただし、方針の探索に大きな計算はかけられない。また、小さなモデル・小さなデータの代理の課題で探した方針を使い回すのではなく、目的のモデルとデータで直接調整したい。この要望に最も合う手法を1つ選べ。",
  choices: ["AutoAugment", "RandAugment", "Mixup", "Random Erasing"],
  ans: 1,
  exp: "AutoAugment（Cubuk ら, 2018）は、データ拡張の方針を強化学習による探索で求めたが、計算が大きく、小さな代理の課題で探した方針を使い回す必要があった。RandAugment（Cubuk ら, 2019）は探索空間を大幅に減らし、変換の数 N と共通の強さ M の2つだけを、目的のモデルとデータで単純なグリッドサーチによって決められるようにした。シラバスの表記は「RandAugument」だが、原論文の名称は RandAugment である。",
  why: ["AutoAugment は、変換の種類・適用する確率・強さからなる方針を、強化学習を使った探索で求める。探索に大きな計算が必要で、小さな代理の課題で探した方針を大きなモデルに使い回していたので、要望に合わない。", "正しい。用意した変換の中から各画像にランダムに N 個を選び、共通の強さ M で適用する。調整するハイパーパラメータが N と M の2つだけなので、目的のモデルとデータで単純なグリッドサーチによって直接決められる。", "Mixup は、2枚の画像とそのラベルを、ベータ分布から取り出した比率で混ぜ合わせる手法である。変換の方針を自動で決める手法ではない。", "Random Erasing は、一定の確率で、大きさと縦横比をランダムに決めた長方形の領域をランダムな値で塗りつぶす手法である。変換の方針を自動で決める手法ではない。"],
  src: [{ t: "Cubuk, Zoph, Shlens & Le (2019). RandAugment: Practical automated data augmentation with a reduced search space", u: "https://arxiv.org/abs/1909.13719" }, { t: "Cubuk et al. (2018). AutoAugment: Learning Augmentation Policies from Data", u: "https://arxiv.org/abs/1805.09501" }, { t: "Zhang, Cisse, Dauphin & Lopez-Paz (2017). mixup: Beyond Empirical Risk Minimization", u: "https://arxiv.org/abs/1710.09412" }, { t: "Zhong, Zheng, Kang, Li & Yang (2017). Random Erasing Data Augmentation", u: "https://arxiv.org/abs/1708.04896" }] },
{ id: "M-064", set: "mock", sec: "T25", kw: ["Brightness","Contrast","Random Flip","Crop"], type: "worst",
  stem: "画像のデータ拡張の使い方に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Brightness や Contrast を変更した画像では、画素の値を変えた割合に応じて、正解ラベルも元のクラスと他のクラスに分け直す必要がある", "果物の熟し具合を色で判定する課題では、色合いを大きく変える変換は画像の意味（ラベル）を変えてしまうおそれがあるので、使わないか強さを抑える", "犬と猫の写真の分類では Random Flip の左右反転が広く使われるが、文字の認識では「b」と「d」のように反転で別の文字に見える画像ができることがある", "Crop で切り抜く範囲を小さくしすぎると、対象の物体が写らなくなり、画像の中身とラベルが合わなくなることがある"],
  ans: 0,
  exp: "データ拡張では、ラベル（意味）を変えない範囲の変換を選ぶ。明るさ・コントラスト・反転・切り抜きは、適切な強さで使えばラベルを変えないので、ラベルはそのまま使う。一方、Mixup（2枚の画像全体を重ねる）や CutMix（一部の領域を置き換える）は、混ぜた割合に応じてラベルも混ぜる。どの変換が使えるかは課題によって異なる。",
  why: ["不適切（これが正解）。明るさやコントラストの変更はラベルを変えない範囲で行う変換で、ラベルはそのまま使う。ラベルも混ぜるのは、2枚の画像を混ぜる Mixup や CutMix である。", "適切。色そのものがラベルを決める課題では、色の変換で正解が変わってしまう。", "適切。反転してもラベルが変わらない課題かどうかを見極めて使う。", "適切。切り抜く大きさの範囲は、対象が写る程度に設定する。"],
  src: [{ t: "Krizhevsky, Sutskever & Hinton (2012). ImageNet Classification with Deep Convolutional Neural Networks", u: "https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html" }, { t: "torchvision documentation: ColorJitter", u: "https://docs.pytorch.org/vision/stable/generated/torchvision.transforms.v2.ColorJitter.html" }, { t: "Zhang, Cisse, Dauphin & Lopez-Paz (2017). mixup: Beyond Empirical Risk Minimization", u: "https://arxiv.org/abs/1710.09412" }, { t: "Yun et al. (2019). CutMix: Regularization Strategy to Train Strong Classifiers with Localizable Features", u: "https://arxiv.org/abs/1905.04899" }] },
/* ── T26 画像認識 ── */
{ id: "M-065", set: "mock", sec: "T26", kw: ["MobileNet"], type: "calc",
  stem: "入力が 10×10 で 32 チャネル、出力が 10×10 で 64 チャネルとなる 3×3 の畳み込み層がある（パディングで縦横の大きさは保たれ、バイアスは考えない）。この層を、MobileNet で使われる Depthwise Separable Convolution（チャネルごとの 3×3 の畳み込みと、1×1 の畳み込みの組み合わせ）に置き換えたときの積和演算の回数として、正しいものを1つ選べ。",
  choices: ["28,800 回", "204,800 回", "233,600 回", "1,843,200 回"],
  ans: 2,
  exp: "MobileNet の論文（Howard ら, 2017）では、カーネルの大きさを D<sub>K</sub>、入力・出力のチャネル数を M・N、特徴マップの大きさを D<sub>F</sub> とすると、通常の畳み込みの計算量は D<sub>K</sub>·D<sub>K</sub>·M·N·D<sub>F</sub>·D<sub>F</sub>、Depthwise Separable Convolution は D<sub>K</sub>·D<sub>K</sub>·M·D<sub>F</sub>·D<sub>F</sub> ＋ M·N·D<sub>F</sub>·D<sub>F</sub> である。比は 1/N ＋ 1/D<sub>K</sub><sup>2</sup> となり、3×3 では通常の畳み込みの8〜9分の1程度の計算量になる。",
  why: ["チャネルごとの 3×3 の畳み込み（depthwise）の分だけである（3×3×32×10×10 ＝ 28,800）。チャネルを混ぜ合わせる 1×1 の畳み込みの分が抜けている。", "1×1 の畳み込み（pointwise）の分だけである（32×64×10×10 ＝ 204,800）。チャネルごとの 3×3 の畳み込みの分が抜けている。", "正しい。28,800 ＋ 204,800 ＝ 233,600 回である。通常の畳み込みの 1,843,200 回と比べると約 0.127 倍（約8分の1）になる。", "置き換える前の通常の畳み込みの回数である（3×3×32×64×10×10 ＝ 1,843,200）。"],
  src: [{ t: "Howard et al. (2017). MobileNets: Efficient Convolutional Neural Networks for Mobile Vision Applications", u: "https://arxiv.org/abs/1704.04861" }] },
{ id: "M-066", set: "mock", sec: "T26", kw: ["物体識別","インスタンスセグメンテーション","姿勢推定","セマンティックセグメンテーション"], type: "best",
  stem: "次の（ア）〜（ウ）の場面と、それに最も合う画像認識のタスクの組み合わせとして、最も適切なものを1つ選べ。<br>（ア）製造ラインで製品を1個ずつ撮った画像から、その製品が良品か不良品かを判定する<br>（イ）顕微鏡画像の中で互いに接している細胞を1個ずつ区別し、それぞれの輪郭を画素単位で切り出す<br>（ウ）競技の動画から選手の肘や膝などの位置を求め、フォームを分析する",
  choices: ["（ア）物体識別　（イ）インスタンスセグメンテーション　（ウ）姿勢推定", "（ア）物体検出　（イ）セマンティックセグメンテーション　（ウ）姿勢推定", "（ア）物体識別　（イ）セマンティックセグメンテーション　（ウ）物体検出", "（ア）物体検出　（イ）インスタンスセグメンテーション　（ウ）パノプティックセグメンテーション"],
  ans: 0,
  exp: "画像全体に1つのラベルを付けるのが物体識別、物体ごとに枠とクラスを出すのが物体検出、画素ごとにクラスを付けて個体は区別しないのがセマンティックセグメンテーション、個体を区別して画素単位で切り出すのがインスタンスセグメンテーションである。関節などのキーポイントの位置を求めるのは姿勢推定である。タスクは「出力として何が欲しいか」で選ぶ。",
  why: ["正しい。（ア）は1枚の画像に良・不良の1つのラベルを付ける物体識別、（イ）は同じクラスの個体を区別して画素単位で切り出すインスタンスセグメンテーション、（ウ）はキーポイントの位置を求める姿勢推定である。", "（イ）のセマンティックセグメンテーションは、同じクラスの個体を区別しないため、接している細胞は1つの「細胞」の領域にまとまってしまう。また（ア）は位置を求める必要がなく、画像全体の判定である。", "（イ）は個体の区別が必要なのでセマンティックセグメンテーションでは足りない。（ウ）の物体検出は人を枠で囲むだけで、肘や膝の位置は出力しない。", "（ウ）のパノプティックセグメンテーションは、背景を含むすべての画素にラベルを付けるタスクで、関節の位置は出力しない。（ア）も位置を求める必要はない。"],
  src: [{ t: "Kirillov et al. (2018). Panoptic Segmentation", u: "https://arxiv.org/abs/1801.00868" }, { t: "He et al. (2017). Mask R-CNN", u: "https://arxiv.org/abs/1703.06870" }, { t: "Cao et al. (2018). OpenPose: Realtime Multi-Person 2D Pose Estimation using Part Affinity Fields", u: "https://arxiv.org/abs/1812.08008" }] },
{ id: "M-067", set: "mock", sec: "T26", kw: ["AlexNet","GoogLeNet","ResNet","SENet","VGG"], type: "best",
  stem: "ILSVRC（ImageNet を使った画像認識の競技会）の分類部門で優勝したモデルを、年の古い順に並べたものとして、最も適切なものを1つ選べ。",
  choices: ["AlexNet → VGG → ResNet → SENet", "AlexNet → GoogLeNet → SENet → ResNet", "GoogLeNet → AlexNet → ResNet → SENet", "AlexNet → GoogLeNet → ResNet → SENet"],
  ans: 3,
  exp: "分類部門の優勝は、2012年 AlexNet（top-5 誤り率 15.3%）、2014年 GoogLeNet（6.67%）、2015年 ResNet（MSRA のアンサンブル、3.57%）、2017年 SENet（WMW チーム、2.251%）である。2013年は Clarifai のチームが優勝した。VGG は2014年の分類部門で2位、位置特定部門で1位だった。",
  why: ["VGG は ILSVRC 2014 の分類部門では GoogLeNet に次ぐ2位であり、1位になったのは位置特定（localization）部門である。", "順序が逆である。ResNet は2015年、SENet は2017年に優勝した。", "AlexNet の優勝（2012年）は GoogLeNet（2014年）より前である。AlexNet の大差での優勝が、ディープラーニングが広まるきっかけになった。", "正しい。2012年 AlexNet、2014年 GoogLeNet、2015年 ResNet、2017年 SENet の順である。"],
  src: [{ t: "Krizhevsky, Sutskever & Hinton (2012). ImageNet Classification with Deep Convolutional Neural Networks", u: "https://proceedings.neurips.cc/paper/2012/hash/c399862d3b9d6b76c8436e924a68c45b-Abstract.html" }, { t: "ImageNet Large Scale Visual Recognition Challenge 2014 (ILSVRC2014) Results", u: "https://www.image-net.org/challenges/LSVRC/2014/results" }, { t: "ImageNet Large Scale Visual Recognition Challenge 2015 (ILSVRC2015) Results", u: "https://www.image-net.org/challenges/LSVRC/2015/results" }, { t: "ImageNet Large Scale Visual Recognition Challenge 2017 (ILSVRC2017) Results", u: "https://www.image-net.org/challenges/LSVRC/2017/results" }] },
{ id: "M-068", set: "mock", sec: "T26", kw: ["Faster R-CNN","Fast R-CNN","FPN","物体検出"], type: "worst",
  stem: "物体検出のモデルと処理に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["R-CNN 系の2段階の検出では、物体がありそうな領域の候補を挙げてから、各候補のクラスを分類し、枠の位置を補正する", "Faster R-CNN は、領域候補の生成を Selective Search に任せたまま、検出を行うネットワークの計算だけを速くすることで、Fast R-CNN より高速になった", "検出の結果、同じ物体に重なった複数の枠が出たときは、非最大値抑制（NMS）によって、確信度の高い枠を残し、それと大きく重なる枠を取り除く", "FPN は単独の検出器ではなく、深い層の特徴を浅い層へ戻しながら各解像度の特徴マップを作る仕組みであり、Faster R-CNN などの検出器と組み合わせて使われる"],
  ans: 1,
  exp: "Fast R-CNN は、画像全体に1回だけ CNN をかけることで R-CNN を高速化したが、領域候補の生成には Selective Search などの従来の手法を使っており、ここが処理全体のボトルネックとして残った。Faster R-CNN は、この領域候補の生成をニューラルネットワーク（RPN）で行い、検出部と特徴マップを共有させることで高速化した。",
  why: ["適切。R-CNN・Fast R-CNN・Faster R-CNN は、領域候補を挙げる段階と、それを分類・補正する段階をもつ2段階の検出モデルである。", "不適切（これが正解）。Selective Search を使っていたのは R-CNN と Fast R-CNN である。Faster R-CNN は、領域候補を出す部分を RPN（Region Proposal Network）に置き換えたことが要点である。", "適切。NMS は、確信度が最も高い枠を残し、それとの IoU が一定以上の枠を取り除く処理をくり返して、重複した検出を1つにまとめる。SSD などでも最後に使われる。", "適切。FPN は、トップダウンの経路と横方向の結合で、すべての解像度に意味的に強い特徴マップを作る特徴の取り出し方であり、論文でも Faster R-CNN と組み合わせて評価された。"],
  src: [{ t: "Girshick (2015). Fast R-CNN", u: "https://arxiv.org/abs/1504.08083" }, { t: "Ren et al. (2015). Faster R-CNN: Towards Real-Time Object Detection with Region Proposal Networks", u: "https://arxiv.org/abs/1506.01497" }, { t: "Liu et al. (2015). SSD: Single Shot MultiBox Detector", u: "https://arxiv.org/abs/1512.02325" }, { t: "Lin et al. (2016). Feature Pyramid Networks for Object Detection", u: "https://arxiv.org/abs/1612.03144" }] },
{ id: "M-069", set: "mock", sec: "T26", kw: ["DeepLab"], type: "blank",
  stem: "DeepLab は、カーネルの要素の間を空けて畳み込む（ア）を用いて、パラメータの数や計算量を増やさずに、フィルタが見る範囲を広げる。DeepLab v2 では、要素の間隔（rate）が異なる複数の（ア）を並列に適用し、さまざまな大きさの物体や文脈をとらえる（イ）を提案した。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）転置畳み込み　（イ）ASPP（Atrous Spatial Pyramid Pooling）", "（ア）Atrous Convolution　（イ）ASPP（Atrous Spatial Pyramid Pooling）", "（ア）Atrous Convolution　（イ）ピラミッドプーリングモジュール", "（ア）Depthwise Separable Convolution　（イ）FPN（Feature Pyramid Network）"],
  ans: 1,
  exp: "DeepLab（Chen ら）は、Atrous Convolution（Dilated Convolution）で、特徴マップの解像度を落としにくく、パラメータを増やさずに広い範囲を見られるようにした。v2 で提案された ASPP は、rate の異なる Atrous Convolution を並列に使い、複数の大きさの物体と文脈をとらえる。v1・v2 では全結合の CRF で境界を整える後処理も使った。",
  why: ["転置畳み込みは、特徴マップを拡大（アップサンプリング）するための畳み込みで、FCN などで使われる。カーネルの要素の間を空けて見る範囲を広げるものではない。", "正しい。Atrous Convolution と、それを rate を変えて並列に使う ASPP は、DeepLab の中心となる仕組みである。", "ピラミッドプーリングモジュールは PSPNet の部品で、特徴マップを大きさの異なる区画に分けてプーリングする。rate の異なる Atrous Convolution を並べたものではない。", "Depthwise Separable Convolution は計算量を減らすための畳み込み（MobileNet など）で、FPN は物体検出のための特徴の取り出し方である。"],
  src: [{ t: "Chen et al. (2016). DeepLab: Semantic Image Segmentation with Deep Convolutional Nets, Atrous Convolution, and Fully Connected CRFs", u: "https://arxiv.org/abs/1606.00915" }, { t: "Zhao et al. (2016). Pyramid Scene Parsing Network", u: "https://arxiv.org/abs/1612.01105" }] },
{ id: "M-070", set: "mock", sec: "T26", kw: ["EfficientNet","NAS (Neural Architecture Search)","MnasNet"], type: "best",
  stem: "EfficientNet の B0〜B7 の作り方の説明として、最も適切なものを1つ選べ。",
  choices: ["MnasNet と同じ探索空間で、精度と FLOPS（計算量）の両方を目的とする NAS によって基本モデル B0 を作り、B0 の深さ・幅・入力の解像度を複合スケーリングで同時に大きくして B1〜B7 を得た", "B0〜B7 のそれぞれについて、目標とするモデルの大きさごとに NAS を最初から実行し直し、互いに異なる構造を別々に探索した", "スマートフォンの実機で測った推論の速さ（レイテンシ）を目的に含めた NAS で、B0〜B7 のすべての構造を探索した", "人が設計した ResNet-50 を基本モデルとし、残差ブロックの数（深さ）だけを段階的に増やして B1〜B7 を作った"],
  ans: 0,
  exp: "EfficientNet（Tan と Le, 2019）は、MnasNet に倣った多目的の NAS で精度と FLOPS を最適化して基本モデル B0 を作った。特定の機器を対象にしないため、レイテンシではなく FLOPS を目的にしている。次に、深さ・幅・解像度の拡大の比率を小さな探索で決め、1つの係数 φ を大きくして B1〜B7 に拡大した。",
  why: ["正しい。NAS で作った B0 を、複合スケーリングで拡大したものが B1〜B7 である。", "大きなモデルで探索をくり返すと計算の費用が非常に大きくなる。EfficientNet は B0 で決めた拡大の比率を固定し、係数 φ を変えるだけで B1〜B7 を作った。", "実機で測ったレイテンシを目的に入れたのは MnasNet である。EfficientNet-B0 の探索では、特定の機器を対象にしないため FLOPS を使った。また B1〜B7 は探索ではなく拡大で作った。", "EfficientNet の基本モデルは NAS で作られた。また、深さだけを大きくするのではなく、深さ・幅・解像度の3つをバランスよく同時に大きくする点が提案の要点である。"],
  src: [{ t: "Tan & Le (2019). EfficientNet: Rethinking Model Scaling for Convolutional Neural Networks", u: "https://arxiv.org/abs/1905.11946" }, { t: "Tan et al. (2018). MnasNet: Platform-Aware Neural Architecture Search for Mobile", u: "https://arxiv.org/abs/1807.11626" }] },
{ id: "M-071", set: "mock", sec: "T26", kw: ["Vision Transformer"], type: "calc",
  stem: "Vision Transformer で、224×224 画素の画像を 16×16 画素の重ならないパッチに分割し、分類用のトークン（[class] トークン）を先頭に1つ加えて Transformer のエンコーダに入力する。このときエンコーダに入力される系列の長さ（トークンの数）として、正しいものを1つ選べ。",
  choices: ["15", "196", "257", "197"],
  ans: 3,
  exp: "ViT（Dosovitskiy ら, 2020）では、H×W の画像を P×P のパッチに分けると、パッチの数は N ＝ HW / P<sup>2</sup> になる。各パッチをベクトルに変換して位置埋め込みを加え、BERT の [CLS] と同様の学習可能な [class] トークンを先頭に付けて入力する。分類には、このトークンのエンコーダの出力を使う。",
  why: ["1辺に並ぶパッチの数（224 ÷ 16 ＝ 14）に1を足した値である。パッチは縦横に 14 × 14 個並ぶ。", "パッチの数（14 × 14 ＝ 196）だけで、先頭に加える [class] トークンを数えていない。", "パッチの大きさ（16 × 16 ＝ 256）をパッチの数と取り違えた値に1を足したものである。", "正しい。(224 ÷ 16)<sup>2</sup> ＝ 196 個のパッチに、[class] トークン1個を加えて 197 個になる。"],
  src: [{ t: "Dosovitskiy et al. (2020). An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale", u: "https://arxiv.org/abs/2010.11929" }] },
{ id: "M-072", set: "mock", sec: "T26", kw: ["姿勢推定","Open Pose"], type: "best",
  stem: "体育館での練習を撮った動画から、同時に写る数十人の選手の姿勢を推定したい。複数人の姿勢推定の方式に関する説明として、最も適切なものを1つ選べ。",
  choices: ["トップダウン型は、画像全体を一度だけ処理して全員の関節を同時に求めるため、人数が増えても処理時間はほとんど変わらない", "トップダウン型は、最初の人の検出に失敗しても、その後の関節の推定でその人を見つけ直せるため、人が密集した場面に強い", "ボトムアップ型は、全員分の関節などの部位をまとめて検出してから人ごとに組み合わせるため、トップダウン型に比べて、人数が増えたときの処理時間の増加を抑えやすい", "ボトムアップ型は、まず人を1人ずつ検出して枠で囲み、その枠ごとに1人用の姿勢推定を行う"],
  ans: 2,
  exp: "トップダウン型は、人を検出してから1人ずつ姿勢を推定するため、処理時間は人数におおむね比例する。また、密集した場面で人の検出に失敗すると、後から取り戻せない。OpenPose（Cao ら）のようなボトムアップ型は、画像全体から部位を検出し、Part Affinity Fields で人ごとに結び付けるため、人数が増えても処理時間が増えにくく、リアルタイムの処理を実現した。",
  why: ["トップダウン型は、検出した人ごとに1人用の姿勢推定を行うため、処理時間は人数に比例して増える。", "OpenPose の論文は、トップダウン型は人の検出に早い段階で頼るため、人が近接して検出に失敗すると回復の手段がないことを弱点として挙げている。", "正しい。部位の検出は画像全体に対して1回行い、それを人ごとに組み合わせるため、人数による処理時間の増加を抑えやすい。", "人を検出してから1人ずつ推定するのはトップダウン型の説明である。"],
  src: [{ t: "Cao et al. (2018). OpenPose: Realtime Multi-Person 2D Pose Estimation using Part Affinity Fields", u: "https://arxiv.org/abs/1812.08008" }] },
{ id: "M-073", set: "mock", sec: "T26", kw: ["ResNet"], type: "best",
  stem: "ResNet の論文（He ら, 2015）は、層を深くしていくと精度が飽和したのち急に下がる「劣化（degradation）」を指摘した。この劣化の原因と、ResNet による対処の説明として、最も適切なものを1つ選べ。",
  choices: ["原因は、訓練誤差は下がるがテスト誤差が上がる過学習である。ショートカットが正則化として働くことで、これを防いだ", "原因は、層を増やすと訓練誤差まで大きくなる最適化の難しさである。積み重ねた層には入力との差分（残差）を学習させ、入力をショートカットで出力に足すことで対処した", "原因は、層を増やすとパラメータが増えすぎることである。恒等写像のショートカットでパラメータの数を減らすことで対処した", "原因は、活性化関数のシグモイド関数による勾配消失だけであり、活性化関数を ReLU に替えるだけで解決した"],
  ans: 1,
  exp: "ResNet の論文は、劣化は過学習によるものではなく、層を増やすと訓練誤差まで大きくなる最適化の難しさだと指摘した。そこで、層に H(x) を直接学習させる代わりに残差 F(x) ＝ H(x) − x を学習させ、入力 x をショートカットで足す（出力は F(x) ＋ x）ことで、152層の非常に深いネットワークでも学習できるようにした。恒等写像のショートカットは、パラメータも計算量も増やさない。",
  why: ["過学習なら訓練誤差は下がるはずである。論文は、深いネットワークでは訓練誤差まで高くなることを示し、劣化は過学習が原因ではないとした。", "正しい。残差を学習させるブロックを積み重ねることで、深くしても最適化しやすくした。", "論文は、恒等写像のショートカットは余分なパラメータも計算の複雑さも加えないと述べている。ショートカットはパラメータを減らすためのものではない。", "論文は、勾配の消失・爆発の問題は重みの初期化の工夫や途中の正規化層（バッチ正規化）でおおむね解決されていると述べ、バッチ正規化を使った実験で信号が消えていないことも確かめたうえで、劣化は勾配消失によるものとは考えにくいとした。"],
  src: [{ t: "He et al. (2015). Deep Residual Learning for Image Recognition", u: "https://arxiv.org/abs/1512.03385" }] },
/* ── T27 自然言語処理 ── */
{ id: "M-074", set: "mock", sec: "T27", kw: ["word2vec","分散表現"], type: "calc",
  stem: "word2vec で学習した単語のベクトルを使い、「日本に対する東京」の関係を「フランスに対する何か」に当てはめる類推を行う。この類推では、ベクトル(東京) − ベクトル(日本) ＋ ベクトル(フランス) を計算し、それに最も近いベクトルを持つ単語を答えとする。説明のためベクトルを2次元とし、日本 ＝ (1, 4)、東京 ＝ (2, 7)、フランス ＝ (5, 3) とするとき、計算されるベクトルとして正しいものを1つ選べ。",
  choices: ["(6, 6)", "(4, 0)", "(8, 14)", "(−4, 0)"],
  ans: 0,
  exp: "単語のベクトルに足し算・引き算を行うことで類推ができる。例えば vector(\"King\") − vector(\"Man\") ＋ vector(\"Woman\") に最も近いのは Queen のベクトルである（同じ年の Mikolov・Yih・Zweig の論文が示した例）。word2vec の論文（Mikolov ら, 2013）は、この類推の精度を高めることを目指し、国と首都の関係（France と Paris、Germany と Berlin）なども含む評価用の問題で精度を測った。類推ができるのは、意味の関係が、ベクトルの差としてある程度一定の向きに表れるためである。",
  why: ["正しい。(2 − 1 ＋ 5, 7 − 4 ＋ 3) ＝ (6, 6) であり、これに最も近い単語（期待される答えは「パリ」）を探す。", "東京と日本の役割を逆にした ベクトル(日本) − ベクトル(東京) ＋ ベクトル(フランス) ＝ (4, 0) である。これでは「首都から国へ」の差を、逆向きに足すことになる。", "3つのベクトルをすべて足した値である。類推では、2語の差（日本から東京への関係）を取り出してから、フランスに足す。", "ベクトル(東京) − ベクトル(日本) − ベクトル(フランス) ＝ (−4, 0) である。フランスのベクトルは引くのではなく足す。"],
  src: [{ t: "Mikolov et al. (2013). Efficient Estimation of Word Representations in Vector Space", u: "https://arxiv.org/abs/1301.3781" }, { t: "Mikolov, Yih & Zweig (2013). Linguistic Regularities in Continuous Space Word Representations. NAACL-HLT 2013", u: "https://aclanthology.org/N13-1090/" }] },
{ id: "M-075", set: "mock", sec: "T27", kw: ["情報検索","機械翻訳","文書要約","統計的機械翻訳"], type: "worst",
  stem: "自然言語処理の応用に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["情報検索では、単語ごとにそれを含む文書の一覧（転置インデックス）をあらかじめ作っておくことで、<span class='no-terms'>クエリ</span>の単語を含む文書をすばやく見つけられる", "機械翻訳の自動評価に使われる BLEU は、機械による訳文と人が作った参照訳とで、n-gram がどれだけ一致するかをもとに訳の品質を測る", "生成型の文書要約は、元の文書にない表現も使って要約を作れる一方で、事実の細部を誤って再現したり、同じ内容をくり返したりする問題が指摘されてきた", "統計的機械翻訳は、言語学者が書いた文法の規則と辞書に従って訳文を組み立てる方式であり、対訳のデータを必要としない"],
  ans: 3,
  exp: "統計的機械翻訳（Brown ら, 1990 が枠組みを示した）は、大量の対訳コーパスから単語や句の対応とその確率を学習し、翻訳モデルと言語モデルを組み合わせて最も確率の高い訳文を選ぶ。人が書いた規則と辞書で翻訳するのはルールベース機械翻訳である。機械翻訳は、ルールベース → 統計的 → ニューラルの順に発展した。",
  why: ["適切。転置インデックスは検索エンジンの基本的な仕組みであり、見つけた文書を TF-IDF などで重み付けして関連の高い順に並べる。", "適切。BLEU（Papineni ら, 2002）は、参照訳との n-gram の一致の度合い（修正 n-gram 適合率）に、短すぎる訳への罰則を組み合わせた指標である。", "適切。See ら（2017）は、生成型の要約のこうした問題を指摘し、元の文書から単語をコピーする仕組みを組み合わせて改善した。", "不適切（これが正解）。規則と辞書による方式はルールベース機械翻訳である。統計的機械翻訳は、人が規則を書く代わりに、大量の対訳コーパスから確率を学習する。"],
  src: [{ t: "Brown et al. (1990). A Statistical Approach to Machine Translation", u: "https://aclanthology.org/J90-2002/" }, { t: "Papineni et al. (2002). Bleu: a Method for Automatic Evaluation of Machine Translation", u: "https://aclanthology.org/P02-1040/" }, { t: "See, Liu & Manning (2017). Get To The Point: Summarization with Pointer-Generator Networks", u: "https://arxiv.org/abs/1704.04368" }, { t: "Manning, Raghavan & Schütze. Introduction to Information Retrieval", u: "https://nlp.stanford.edu/IR-book/" }] },
{ id: "M-076", set: "mock", sec: "T27", kw: ["BERT","大規模言語モデル (LLM)"], type: "best",
  stem: "BERT と、GPT 系の言語モデル（大規模言語モデルの多くが採る形）の違いの説明として、最も適切なものを1つ選べ。",
  choices: ["BERT は Transformer のデコーダだけを積み重ねた構造で、左から右へ次の単語を予測する課題だけで事前学習される", "GPT 系のモデルは、文中の単語を無作為に隠して前後両側の文脈から当てる課題で事前学習されるため、次の単語を順に生成することはできない", "BERT は左右両方の文脈を使って事前学習するエンコーダ型で、主に分類などのタスクにファインチューニングして使う。GPT 系は左から右へ次のトークンを予測するデコーダ型で、その予測をくり返して文章を生成できる", "BERT も GPT 系のモデルも、LSTM を土台とした言語モデルであり、Transformer は使っていない"],
  ans: 2,
  exp: "BERT（Devlin ら, 2018）は Transformer のエンコーダを使い、マスク言語モデルによって左右両方の文脈から単語を予測する課題で事前学習する。論文は、GPT（Radford ら, 2018）が左から右への一方向の言語モデルで事前学習している点を対比として挙げている。GPT 系のモデルは、次のトークンの予測をくり返す自己回帰の形で文章を生成する。",
  why: ["これは GPT 系の説明である。BERT は Transformer のエンコーダを用い、マスク言語モデルと次文予測で事前学習する。", "これは BERT のマスク言語モデルの説明である。GPT 系は左から右へ次のトークンを予測する課題で事前学習され、文章の生成に向く。", "正しい。BERT は双方向のエンコーダ型、GPT 系は一方向のデコーダ型という違いがあり、用途の得意分野も異なる。", "どちらも Transformer を土台にしている。LSTM の言語モデルを使ったのは ELMo である。"],
  src: [{ t: "Devlin et al. (2018). BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding", u: "https://arxiv.org/abs/1810.04805" }, { t: "Brown et al. (2020). Language Models are Few-Shot Learners", u: "https://arxiv.org/abs/2005.14165" }] },
{ id: "M-077", set: "mock", sec: "T27", kw: ["BERT"], type: "blank",
  stem: "BERT では、入力の先頭に特別なトークン（ア）を置き、最終層でのその出力を、入力全体を表す表現として分類のタスクに使う。また、2つの文を1つの入力にまとめるときは、文と文の間に特別なトークン（イ）を挟んで区切り、どちらの文に属するかを表す埋め込みも加える。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）[CLS]　（イ）[SEP]", "（ア）[SEP]　（イ）[CLS]", "（ア）[MASK]　（イ）[SEP]", "（ア）[CLS]　（イ）[MASK]"],
  ans: 0,
  exp: "BERT の論文によれば、入力の最初のトークンは常に分類用の特別なトークン [CLS] で、それに対応する最終層の出力が、分類のタスクで系列全体を表す表現として使われる。2つの文は [SEP] で区切り、さらに文 A・文 B のどちらに属するかを表す埋め込みを各トークンに加える。[MASK] は、マスク言語モデルで隠したトークンの位置に置くものである。",
  why: ["正しい。[CLS] は classification、[SEP] は separator に由来する。", "役割が逆である。先頭に置いて分類に使うのが [CLS]、文の区切りに使うのが [SEP] である。", "[MASK] は、マスク言語モデルの事前学習で、当てさせる単語を隠すために置き換えるトークンである。分類に使う表現を得るためのものではない。", "[MASK] は文の区切りには使わない。2つの文の区切りには [SEP] を使う。"],
  src: [{ t: "Devlin et al. (2018). BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding", u: "https://arxiv.org/abs/1810.04805" }] },
{ id: "M-078", set: "mock", sec: "T27", kw: ["形態素解析","構文解析"], type: "best",
  stem: "日本語の文「兄が買った本を読んだ」を処理する。次の (1)(2) の処理の名称と、一般的に行う順序の組み合わせとして、最も適切なものを1つ選べ。<br>(1) 文を「兄／が／買っ／た／本／を／読ん／だ」のように区切り、それぞれの品詞や基本形を判定する<br>(2)「兄が」が「買った」に、「本を」が「読んだ」に係るといった、語と語の関係を求める",
  choices: ["(1) 構文解析、(2) 形態素解析。順序は (2) → (1) である", "(1) 形態素解析、(2) 構文解析（係り受け解析）。順序は (1) → (2) である", "(1) 形態素解析、(2) 構文解析（係り受け解析）。順序は (2) → (1) である", "(1) 形態素解析、(2) 文脈解析。日本語は単語が空白で区切られているため、(1) は省略できることが多い"],
  ans: 1,
  exp: "形態素解析は文を形態素に区切って品詞などを判定する処理、構文解析は語と語の関係（文の構造）を求める処理である。構文解析は形態素解析の結果を入力として行う。例えば日本語の係り受け解析のツール CaboCha は、形態素解析のツール MeCab を必要とし、その解析結果を使って文節の係り受けを求める。",
  why: ["名称が逆である。単語に区切って品詞を付けるのが形態素解析、語と語の関係を求めるのが構文解析である。", "正しい。まず形態素解析で単語に区切り、その結果をもとに係り受け解析などの構文解析を行う。", "名称は正しいが順序が逆である。語と語の関係を求めるには、先に文を単語に区切って品詞を知る必要がある。", "(2) は語と語の文法的な関係を求める構文解析である。また、日本語は単語が空白で区切られていないため、形態素解析が多くの処理の最初の段階として必要になる。"],
  src: [{ t: "MeCab: Yet Another Part-of-Speech and Morphological Analyzer", u: "https://taku910.github.io/mecab/" }, { t: "CaboCha: Yet Another Japanese Dependency Structure Analyzer", u: "https://taku910.github.io/cabocha/" }] },
{ id: "M-079", set: "mock", sec: "T27", kw: ["BoW (Bag-of-Words)","TF-IDF","word2vec","CBOW"], type: "worst",
  stem: "単語や文書をベクトルで表す方法に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["BoW で、単語の代わりに連続する2語（バイグラム）の出現回数を数えると、語順の情報を一部残せる", "TF-IDF の IDF は、その単語を含む文書の数が少ないほど大きな値になる", "word2vec で学習した単語のベクトルは、語彙の数と同じ次元を持ち、ほとんどの要素が0の疎なベクトルになる", "word2vec の CBOW では、文脈の単語のベクトルを平均してから中心の単語を予測するため、文脈の中での単語の並び順は予測に影響しない"],
  ans: 2,
  exp: "語彙の数と同じ次元で、ほとんどの要素が0になる疎なベクトルは、ワンホットベクトルや BoW の性質である。word2vec は、単語を数十〜数百次元程度の密な実数のベクトル（分散表現）で表し、意味の近い単語ほどベクトルが近くなるように学習する。",
  why: ["適切。scikit-learn の解説でも、単語の代わりに n-gram を数える Bag of n-grams にすると、局所的な語順の情報を一部残せると説明されている。", "適切。IDF は log(全文書数 ÷ その単語を含む文書数) などで求めるため、多くの文書に出てくる語ほど小さく、一部の文書にしか出てこない語ほど大きくなる。", "不適切（これが正解）。word2vec の単語ベクトルは、語彙の数よりはるかに少ない次元の密なベクトルである。疎で高次元なのはワンホットベクトルである。", "適切。word2vec の論文は、CBOW では文脈の単語がすべて同じ位置に射影され（ベクトルが平均され）、単語の順序が射影に影響しないため bag-of-words のモデルと呼ぶと述べている。"],
  src: [{ t: "Mikolov et al. (2013). Efficient Estimation of Word Representations in Vector Space", u: "https://arxiv.org/abs/1301.3781" }, { t: "scikit-learn User Guide: Feature extraction（Text feature extraction）", u: "https://scikit-learn.org/stable/modules/feature_extraction.html" }] },
{ id: "M-080", set: "mock", sec: "T27", kw: ["ELMo"], type: "best",
  stem: "ELMo の論文は、事前学習した双方向の言語モデル（biLM）の層ごとの内部状態を、品詞の付与と、語義の曖昧性解消（文脈に応じて多義語の意味を決めるタスク）にそのまま使って比べた。その結果と、それを踏まえた単語の表現の作り方の説明として、最も適切なものを1つ選べ。",
  choices: ["下の層の状態は語義の曖昧性解消に、上の層の状態は品詞の付与に向いていたため、品詞の付与のタスクでは最上層の状態だけを使う", "どの層の状態も同じ情報をとらえていたため、計算を減らすには、最下層（文脈を使わない単語の表現の層）だけを使えば十分である", "最上層の状態だけを使う方法の方が、全層の状態を組み合わせる方法より、すべてのタスクで性能が高かった", "上の層の状態は文脈に依存した語の意味を、下の層の状態は品詞のような文法の情報をとらえやすかったため、全層の状態をタスクごとに学習する重みで組み合わせて使う"],
  ans: 3,
  exp: "ELMo（Peters ら, 2018）は、大量の文章で双方向の LSTM の言語モデル（biLM）を事前学習し、文脈に応じた単語の表現を作る。論文は、上の層の状態は文脈に依存した語の意味をとらえ（そのまま語義の曖昧性解消に使える）、下の層の状態は文法の側面をとらえる（品詞の付与に使える）ことを示した。そのため、最上層だけを使うのではなく、全層の状態の線形結合を、タスクごとに重みを学習して使う。",
  why: ["上下が逆である。論文では、語義の曖昧性解消には上の層、品詞の付与には下の層の状態が向いていた。また ELMo は、1つの層に絞らず全層を組み合わせる。", "層によってとらえる情報は異なっていた。また、最下層の単語の表現は文脈を使わずに作られるため、多義語の意味を文脈に応じて区別できない。", "論文は、全層の状態を組み合わせると、最上層だけを使う場合より性能が大きく上がると報告している。", "正しい。層ごとに異なる情報をとらえるため、全層をタスクに合わせた重みで組み合わせることが ELMo の要点である。"],
  src: [{ t: "Peters et al. (2018). Deep contextualized word representations", u: "https://arxiv.org/abs/1802.05365" }] },
/* ── T28 音声処理 ── */
{ id: "M-081", set: "mock", sec: "T28", kw: ["パルス符号変調器 (PCM)","A-D 変換"], type: "calc",
  stem: "サンプリング周波数 44.1 kHz、量子化ビット数 16 ビット、2 チャネル（ステレオ）の線形 PCM で、音声を圧縮せずに記録する。1 秒あたりのデータ量（ビットレート）として最も近いものを1つ選べ。なお、1 kbps ＝ 1,000 ビット/秒とする。",
  choices: ["約 706 kbps", "約 1,411 kbps", "約 176 kbps", "約 2,822 kbps"],
  ans: 1,
  exp: "PCM は、標本化と量子化で得た各時点の値をそのまま2進数の符号で表す方式で、圧縮しない場合のデータ量は「サンプリング周波数 × 量子化ビット数 × チャネル数 × 時間」で決まる。1 秒あたりでは 44,100 × 16 × 2 ＝ 1,411,200 ビット、つまり約 1,411 kbps になる。",
  why: ["1 チャネル（モノラル）分の 44,100 × 16 ＝ 705,600 ビット/秒である。ステレオでは2チャネル分になる。", "正しい。44,100 × 16 × 2 ＝ 1,411,200 ビット/秒 ≒ 1,411 kbps である。", "1 秒あたりのバイト数（1,411,200 ÷ 8 ＝ 176,400 バイト）を、ビットの単位と取り違えた値である。", "サンプリング周波数をさらに2倍した値である。標本化定理の「2倍」は、表したい周波数の上限に対してサンプリング周波数をどう選ぶかの話であり、データ量の計算でさらに2倍する必要はない。"],
  src: [{ t: "ITU-T Recommendation G.711: Pulse code modulation (PCM) of voice frequencies", u: "https://www.itu.int/rec/T-REC-G.711" }, { t: "Jurafsky & Martin. Speech and Language Processing (3rd ed. draft)", u: "https://web.stanford.edu/~jurafsky/slp3/" }] },
{ id: "M-082", set: "mock", sec: "T28", kw: ["音声認識","隠れマルコフモデル"], type: "worst",
  stem: "音声認識と隠れマルコフモデル（HMM）に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["音声認識の精度は、認識結果を正解の文と比べた単語の誤り（置換・削除・挿入）の数を、正解の文の単語数で割った単語誤り率（WER）で評価することが多い","HMM で音素を表すと、話す速さが変わっても、同じ状態にとどまる時間の長さの違いとして吸収できる", "HMM の各状態の出力確率を表す混合ガウスモデル（GMM）をディープニューラルネットワークに置き換えることで、音声認識の精度が大きく向上した", "HMM では、ビタビアルゴリズムでデータからパラメータを学習し、バウム・ウェルチ法で観測系列に最も合う状態の並びを求める"],
  ans: 3,
  exp: "Rabiner（1989）は HMM の3つの基本問題を整理した。観測系列が出てくる確率は前向きアルゴリズムで、観測系列に最も合う状態の並びはビタビアルゴリズムで、パラメータの学習はバウム・ウェルチ法（EM アルゴリズムの一種）で求める。音声認識の音響モデルでは、HMM の出力確率に GMM が長く使われ、のちに DNN に置き換えられた（DNN-HMM）。",
  why: ["適切。WER は、認識結果を正解の文に直すのに必要な置換・削除・挿入の単語数を、正解の単語数で割って求める。挿入も数えるため、100% を超えることもある。","適切。音素を左から右へ進む数個の状態で表し、ゆっくり話した部分は同じ状態に長くとどまるとみなすことで、長さの揺れを吸収する。", "適切。Hinton ら（2012）は、複数の研究グループの結果をまとめ、GMM を DNN に置き換えた音響モデルが大きく精度を上げたことを報告した。", "不適切（これが正解）。役割が逆である。最も合う状態の並びを求めるのがビタビアルゴリズム、パラメータを学習するのがバウム・ウェルチ法である。"],
  src: [{ t: "Rabiner, L. R. (1989). A tutorial on hidden Markov models and selected applications in speech recognition", u: "https://doi.org/10.1109/5.18626" }, { t: "Hinton, G. et al. (2012). Deep Neural Networks for Acoustic Modeling in Speech Recognition: The Shared Views of Four Research Groups", u: "https://doi.org/10.1109/MSP.2012.2205597" }, { t: "Jurafsky & Martin. Speech and Language Processing (3rd ed. draft)", u: "https://web.stanford.edu/~jurafsky/slp3/" }] },
{ id: "M-083", set: "mock", sec: "T28", kw: ["フォルマント","フォルマント周波数","スペクトル包絡"], type: "blank",
  stem: "声は、声帯の振動でできた音（音源）が、のどや口からなる声道を通る間に、声道の形に応じて特定の周波数帯が共鳴して強められる（フィルタ）ことで作られる。声の高さは主に（ア）で決まる。一方、母音の違いは主に、声道の共鳴によってスペクトル包絡に現れる山である（イ）の位置の違いとして表れる。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）声道の形　（イ）基本周波数", "（ア）声帯の振動の速さ（基本周波数）　（イ）メル尺度", "（ア）声帯の振動の速さ（基本周波数）　（イ）フォルマント", "（ア）量子化ビット数　（イ）フォルマント"],
  ans: 2,
  exp: "音声を音源（声帯の振動）とフィルタ（声道の共鳴）に分けて考えるのがソース・フィルタモデルである。声の高さは声帯の振動の速さ（基本周波数 F0）で決まり、母音の違いは声道の形で決まるフォルマント（特に F1・F2 の周波数）に表れる。そのため、高い声でも低い声でも、同じ母音として聞き取れる。",
  why: ["逆である。声道の形が決めるのはフォルマントの位置（母音の違い）であり、声の高さを決めるのは声帯の振動である。基本周波数はスペクトル包絡の山ではない。", "メル尺度は、人が感じる音の高さの差が等しくなるように周波数に付けた目盛りであり、スペクトル包絡に現れる山の名前ではない。", "正しい。基本周波数（F0）は声の高さ、フォルマント（F1・F2 など）は声道の共鳴によるスペクトル包絡の山で、母音を区別する手がかりになる。", "量子化ビット数は、A-D 変換で振幅を何段階で表すかを示す値であり、声の高さとは関係がない。"],
  src: [{ t: "Peterson, G. E. & Barney, H. L. (1952). Control Methods Used in a Study of the Vowels", u: "https://doi.org/10.1121/1.1906875" }, { t: "Jurafsky & Martin. Speech and Language Processing (3rd ed. draft)", u: "https://web.stanford.edu/~jurafsky/slp3/" }] },
{ id: "M-084", set: "mock", sec: "T28", kw: ["メル周波数ケプストラム係数 (MFCC)","高速フーリエ変換 (FFT)","メル尺度"], type: "best",
  stem: "音声から MFCC（メル周波数ケプストラム係数）を求める処理の順序として、最も適切なものを1つ選べ。",
  choices: ["短いフレームに区切って窓関数をかける → FFT → メルフィルタバンク → 対数をとる → 離散コサイン変換", "短いフレームに区切って窓関数をかける → 離散コサイン変換 → 対数をとる → メルフィルタバンク → FFT", "FFT → 対数をとる → 離散コサイン変換 → メルフィルタバンク → 短いフレームに区切って窓関数をかける", "短いフレームに区切って窓関数をかける → FFT → 対数をとる → 離散コサイン変換 → メルフィルタバンク"],
  ans: 0,
  exp: "MFCC は、(1) 音声を 25 ミリ秒程度のフレームに区切って窓関数をかけ、(2) FFT でパワースペクトルを求め、(3) メル尺度に沿って並べたフィルタ群で帯域ごとのエネルギーにまとめ、(4) 対数をとり、(5) 離散コサイン変換でケプストラムにして低次の係数を取り出す、という順で求める。低次の係数はスペクトル包絡（声道の特徴）を表す。",
  why: ["正しい。周波数の成分を求めてから、人の聴覚に合わせてメル尺度でまとめ、対数と離散コサイン変換でケプストラムにする。", "FFT で周波数の成分を求める前に、メルフィルタバンクはかけられない。メルフィルタバンクは周波数の軸の上でエネルギーをまとめる処理である。", "音声は時間とともに性質が変わるため、最初に短いフレームに区切ってから FFT をかける。全体に FFT をかけてから最後に区切るのでは、時間ごとの特徴が得られない。", "メルフィルタバンクは、対数と離散コサイン変換の前に、パワースペクトルに対してかける。ケプストラムを求めたあとでかけるものではない。"],
  src: [{ t: "Davis, S. & Mermelstein, P. (1980). Comparison of parametric representations for monosyllabic word recognition in continuously spoken sentences", u: "https://doi.org/10.1109/TASSP.1980.1163420" }, { t: "Jurafsky & Martin. Speech and Language Processing (3rd ed. draft)", u: "https://web.stanford.edu/~jurafsky/slp3/" }] },
{ id: "M-085", set: "mock", sec: "T28", kw: ["WaveNet","音声合成"], type: "calc",
  stem: "WaveNet では、未来のサンプルを参照しない因果的な畳み込みに、間隔を空けて入力を取る Dilated Convolution を組み合わせる。フィルタの長さが 2 の層を、間隔（dilation）を 1, 2, 4, 8, 16, 32, 64, 128, 256, 512 と倍にしながら 10 層重ねたとき、最上層の1つの出力が参照できる入力のサンプルの範囲（受容野の大きさ）として、正しいものを1つ選べ。",
  choices: ["10", "1,024", "512", "20"],
  ans: 1,
  exp: "フィルタの長さが 2 の因果的な畳み込みでは、間隔 d の層を1つ重ねるごとに、参照できる範囲が d サンプルずつ広がる。よって受容野は 1 ＋ (1 ＋ 2 ＋ 4 ＋ … ＋ 512) ＝ 1 ＋ 1,023 ＝ 1,024 になる。WaveNet の論文も、1, 2, 4, …, 512 の1組の受容野は 1,024 であると述べている。間隔を空けない通常の畳み込みで同じ範囲を見るには、約 1,000 層が必要になる。",
  why: ["層の数である。間隔を倍にしていくため、受容野は層の数に比例するのではなく、指数的に広がる。", "正しい。1 ＋ (1 ＋ 2 ＋ … ＋ 512) ＝ 1,024 である。WaveNet は、このまとまりをさらに複数回重ねて受容野を広げた。", "最上層の間隔だけである。下の層が参照する範囲も合わせて考える必要がある。", "フィルタの長さ × 層の数（2 × 10）であり、間隔を空けない通常の畳み込みを重ねた場合（受容野は 層の数 ＋ フィルタの長さ − 1 ＝ 11）とも異なる。間隔を空けることで受容野は大きく広がる。"],
  src: [{ t: "van den Oord, A. et al. (2016). WaveNet: A Generative Model for Raw Audio", u: "https://arxiv.org/abs/1609.03499" }] },
/* ── T29 深層強化学習 ── */
{ id: "M-086", set: "mock", sec: "T29", kw: ["ダブル DQN","DQN"], type: "calc",
  stem: "ある経験で、報酬 r ＝ 1 を得て次の状態 s′ に移った。割引率は γ ＝ 0.9 で、行動は a<sub>1</sub>・a<sub>2</sub>・a<sub>3</sub> の3つである。次の状態 s′ での各行動の Q 値は、学習中のネットワーク（online）では (a<sub>1</sub>, a<sub>2</sub>, a<sub>3</sub>) ＝ (2, 5, 4)、ターゲットネットワークでは (4, 3, 6) であった。ダブル DQN で計算される目標値として、正しいものを1つ選べ（s′ は終端の状態ではないとする）。",
  choices: ["5.5", "6.4", "3.7", "4.6"],
  ans: 2,
  exp: "ダブル DQN（van Hasselt ら, 2015）の目標値は r ＋ γ Q<sub>target</sub>(s′, argmax<sub>a′</sub> Q<sub>online</sub>(s′, a′)) である。次の状態でとる行動を学習中のネットワークで選び、その行動の価値をターゲットネットワークで評価する。選択と評価を分けることで、推定の誤差でたまたま高く出た値をそのまま使ってしまう過大評価を抑える。",
  why: ["学習中のネットワークだけで、選択も評価も行った値（1 ＋ 0.9 × 5）である。これは過大評価が起きやすい通常の Q 学習の形である。", "ターゲットネットワークの最大値を使う DQN（2015年の論文）の目標値（1 ＋ 0.9 × 6）である。選択も評価もターゲットネットワークで行っている。", "正しい。online で最大の行動は a<sub>2</sub>（5）であり、その価値をターゲットネットワークで評価すると 3 なので、1 ＋ 0.9 × 3 ＝ 3.7 である。", "選択と評価の役割を逆にした値である。ターゲットネットワークで a<sub>3</sub>（6）を選び、online の値 4 で評価すると 1 ＋ 0.9 × 4 ＝ 4.6 になる。"],
  src: [{ t: "van Hasselt, H., Guez, A. & Silver, D. (2015). Deep Reinforcement Learning with Double Q-learning", u: "https://arxiv.org/abs/1509.06461" }, { t: "Mnih, V. et al. (2015). Human-level control through deep reinforcement learning. Nature", u: "https://doi.org/10.1038/nature14236" }] },
{ id: "M-087", set: "mock", sec: "T29", kw: ["RLHF"], type: "worst",
  stem: "RLHF（人間のフィードバックによる強化学習）に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["「役に立つ応答」のように、報酬を式で書き表しにくい目標を、人の判断をもとに学ぶための方法である", "Christiano ら（2017）は、人が2つの動きの短い映像を見比べてどちらが良いかを選ぶ形のフィードバックで、Atari のゲームやシミュレーション上のロボットの動作を学べることを示した", "InstructGPT の論文では、人による評価で、13億パラメータの InstructGPT の出力が、1,750億パラメータの GPT-3 の出力よりも好まれたと報告されている", "強化学習を行う間は、モデルが応答を1つ生成するたびに人がその場で点数を付け、その点数をそのまま報酬として使う必要がある"],
  ans: 3,
  exp: "RLHF では、人の比較や順位付けのデータから、出力の良さを予測する報酬モデルを学習し、強化学習の間はその報酬モデルが出す値を報酬として使う。そのため、人がすべての出力を評価する必要はない。Christiano ら（2017）は、エージェントと環境のやり取りの1%未満にフィードバックを与えるだけで複雑な課題を解けたと報告している。",
  why: ["適切。報酬関数を人が式で設計しにくい目標を、人の好みのデータから学ぶのが RLHF のねらいである。", "適切。Christiano らは、軌跡の短い区間の対を人に比べてもらい、その好みから報酬を学んで、報酬関数を使わずに課題を解いた。", "適切。パラメータが100分の1以下のモデルでも、RLHF で調整した出力の方が人に好まれた。", "不適切（これが正解）。強化学習で使う報酬は、人の比較データから学んだ報酬モデルが出す。生成のたびに人が採点するのでは費用が大きすぎるため、報酬モデルで人の判断を代わりに予測する。"],
  src: [{ t: "Christiano, P. et al. (2017). Deep reinforcement learning from human preferences", u: "https://arxiv.org/abs/1706.03741" }, { t: "Ouyang, L. et al. (2022). Training language models to follow instructions with human feedback", u: "https://arxiv.org/abs/2203.02155" }] },
{ id: "M-088", set: "mock", sec: "T29", kw: ["sim2real","ドメインランダマイゼーション"], type: "best",
  stem: "物体をつかむロボットの方策を、物理シミュレータの中だけで強化学習させた。シミュレータ上ではほぼ成功するが、実機では照明や物体の見た目、摩擦の違いのために失敗が多い。この問題への対処として、最も適切なものを1つ選べ。",
  choices: ["シミュレータの見た目を実機に似せて作り込むことにこだわらず、照明・物体の色や模様・摩擦などを学習のたびに大きく変えて学習させる。現実にはありえない模様が混ざっていてもよい","シミュレータの条件を最初の1つの設定に固定したまま、その設定での成功率が100%に近づくまで学習時間を延ばす", "シミュレータの中で成功したときの報酬の値を大きくすれば、実機との違いによる性能の低下は自然になくなる", "シミュレータと実機の違いは画像の見た目だけで生じるため、摩擦や質量などの物理の条件は考えなくてよい"],
  ans: 0,
  exp: "シミュレーションで学んだ方策を実世界に移す sim2real では、両者の違い（リアリティギャップ）が性能低下の原因になる。ドメインランダマイゼーション（Tobin ら, 2017）は、シミュレーションの条件を無作為にばらつかせ、十分に多様な条件で学習すれば現実も変化の1つに見える、という考え方で、この違いを埋める。",
  why: ["正しい。これはドメインランダマイゼーションである。Tobin ら（2017）は、写実的でない無作為な模様のシミュレーション画像だけで学習した物体の位置の推定器が、実世界で 1.5 cm の精度で働くことを示した。OpenAI のロボットハンドの研究では、摩擦などの物理の条件も無作為に変えた。","1つの設定に合わせて学習を続けても、その設定と現実の違いは埋まらない。かえってシミュレータに特有の性質に過度に適合するおそれがある。", "報酬の大きさを変えても、シミュレーションと現実の違いは小さくならない。", "摩擦・質量などの物理の違いも性能低下の原因になる。OpenAI のロボットハンドの研究では、物理の条件も無作為に変えて学習した。"],
  src: [{ t: "Tobin, J. et al. (2017). Domain Randomization for Transferring Deep Neural Networks from Simulation to the Real World", u: "https://arxiv.org/abs/1703.06907" }, { t: "OpenAI et al. (2019). Solving Rubik's Cube with a Robot Hand", u: "https://arxiv.org/abs/1910.07113" }] },
{ id: "M-089", set: "mock", sec: "T29", kw: ["オフライン強化学習"], type: "best",
  stem: "病院に蓄積された過去の診療の記録（患者の状態・行った処置・その後の経過）を使い、強化学習で処置の方針を学びたい。ただし、学習のために患者で新たに試行錯誤することはできない。この場面に関する説明として、最も適切なものを1つ選べ。",
  choices: ["記録にほとんど現れない処置は情報が少ないので、オンラインの強化学習の探索と同じように、その価値を高めに見積もって積極的に選ばせた方が、良い方針が見つかりやすい", "ε-greedy 方策で処置を無作為に選んで探索すれば、記録にない処置の価値も正しく学べる", "記録にほとんど現れない処置は、価値の推定が外れていても試して確かめられないため、価値を控えめに見積もったり、学ぶ方策が記録された処置から離れすぎないよう制約したりする工夫が使われる", "データが固定されているので分布のずれは起きず、通常のオンラインの強化学習より常に安定して学習できる"],
  ans: 2,
  exp: "オフライン強化学習は、追加のデータ収集をせず、過去に集めたデータだけで方策を学ぶ（Levine ら, 2020）。医療・教育・ロボットなど、試行錯誤が危険・高価な分野で期待されている。データにない行動の価値は正しく推定できず、誤って高く見積もっても実際に試して直せないため、CQL のように価値を控えめに見積もる工夫が使われる。",
  why: ["価値を高めに見積もって選ばせるのは、実際に試して確かめられるオンラインの探索の考え方である。オフラインでは、誤って高く見積もった処置を試して直す機会がないため、推定の誤りをそのまま利用した方策になってしまう。", "この場面では患者で新たに処置を試せないため、探索によってデータを増やすことはできない。", "正しい。データにない行動の価値の過大評価（分布のずれ）への対処が要点であり、CQL のように価値を控えめに見積もる方法や、方策を記録の行動に近づける方法がある。", "学ぶ方策が選ぶ行動の分布と、データを集めたときの行動の分布がずれることが、オフライン強化学習の主な難しさである。"],
  src: [{ t: "Levine, S. et al. (2020). Offline Reinforcement Learning: Tutorial, Review, and Perspectives on Open Problems", u: "https://arxiv.org/abs/2005.01643" }, { t: "Kumar, A. et al. (2020). Conservative Q-Learning for Offline Reinforcement Learning", u: "https://arxiv.org/abs/2006.04779" }] },
{ id: "M-090", set: "mock", sec: "T29", kw: ["ダブル DQN","デュエリングネットワーク","ノイジーネットワーク","Rainbow"], type: "best",
  stem: "DQN の課題と、それに対処するために提案された改良の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["目標値の計算の max によって、行動価値を実際より高く見積もりやすい ― デュエリングネットワーク", "ε-greedy 方策では、どの状態でも同じ確率で、見込みの低い行動も含めて無作為に試してしまう ― ノイジーネットワーク", "どの行動をとっても結果がほとんど変わらない状態が多く、状態そのものの良し悪しを効率よく学びにくい ― ダブル DQN", "経験を一様に無作為に取り出すと、学ぶことの多い経験もそうでない経験も同じ頻度でしか使われない ― ターゲットネットワーク"],
  ans: 1,
  exp: "ダブル DQN は行動の選択と評価を分けて過大評価を抑え、デュエリングネットワークは状態価値 V(s) とアドバンテージ A(s, a) の2つの流れに分けて状態の良し悪しを効率よく学ぶ。ノイジーネットワークは、重みに学習可能なノイズを加えて探索を行う。経験の使い方の偏りに対処するのは優先度付き経験再生である。Rainbow は、これらを含む6つの改良を組み合わせた。",
  why: ["過大評価に対処するのはダブル DQN である。デュエリングネットワークは、ネットワークの構造を V と A の2つの流れに分ける改良である。", "正しい。ノイジーネットワークは、ε-greedy 方策の無作為な行動の代わりに、重みに加えたノイズで探索し、ノイズの大きさも学習する。", "状態の良し悪しを効率よく学ぶ構造はデュエリングネットワークである。ダブル DQN は過大評価への対処である。", "学ぶことの多い（TD 誤差の大きい）経験を優先して使うのは優先度付き経験再生である。ターゲットネットワークは、目標値の計算に一定間隔でだけ更新するネットワークの写しを使い、目標が動き続けるのを防ぐ仕組みである。"],
  src: [{ t: "van Hasselt, H., Guez, A. & Silver, D. (2015). Deep Reinforcement Learning with Double Q-learning", u: "https://arxiv.org/abs/1509.06461" }, { t: "Wang, Z. et al. (2015). Dueling Network Architectures for Deep Reinforcement Learning", u: "https://arxiv.org/abs/1511.06581" }, { t: "Fortunato, M. et al. (2017). Noisy Networks for Exploration", u: "https://arxiv.org/abs/1706.10295" }, { t: "Schaul, T. et al. (2015). Prioritized Experience Replay", u: "https://arxiv.org/abs/1511.05952" }, { t: "Hessel, M. et al. (2017). Rainbow: Combining Improvements in Deep Reinforcement Learning", u: "https://arxiv.org/abs/1710.02298" }] },
{ id: "M-091", set: "mock", sec: "T29", kw: ["APE-X","OpenAI Five","アルファスター (AlphaStar)","Agent57"], type: "worst",
  stem: "大規模な深層強化学習の手法や成果に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["APE-X では、1つのアクターだけが環境で行動して経験を集め、多数の学習器がその経験を分け合って、それぞれ別のネットワークを並列に更新する", "OpenAI Five は、既存の強化学習の手法を大規模な分散学習で動かし、自己対戦で約10か月学習して、Dota 2 の世界王者のチームに勝った", "アルファスターは、人間の対戦の記録を使った模倣学習で初期の方策を作り、多数のエージェントが互いに対戦するリーグでさらに強化した", "Agent57 は、探索の強さが異なる方策の集まりを1つのネットワークで学び、学習中にどの方策を重点的に使うかを適応的に選んで、Atari の57種類すべてのゲームで人間の標準的な成績を上回った"],
  ans: 0,
  exp: "APE-X（Horgan ら, 2018）は、行動とデータ収集を担う多数のアクターと、学習を担う1つの学習器を切り離した分散型の仕組みである。アクターは共有のネットワークに従って自分の環境のコピーで行動し、経験を共有のメモリに送る。学習器は優先度付き経験再生でそこから経験を取り出してネットワークを更新する。",
  why: ["不適切（これが正解）。アクターと学習器の数が逆である。APE-X は、多数のアクターが集めた経験を、1つの学習器が優先度付き経験再生で学ぶ。", "適切。OpenAI Five は PPO を分散学習で大規模に動かし、2019年4月13日に Dota 2 の世界王者チーム OG に勝った。", "適切。StarCraft II の AI であるアルファスターは、模倣学習とリーグ形式のマルチエージェント強化学習を組み合わせ、グランドマスターの評価を得た。", "適切。Agent57 は、探索的なものから活用に徹するものまでの方策の集まりを学び、どれを優先するかをメタコントローラ（バンディットアルゴリズム）で選んだ。"],
  src: [{ t: "Horgan, D. et al. (2018). Distributed Prioritized Experience Replay", u: "https://arxiv.org/abs/1803.00933" }, { t: "OpenAI et al. (2019). Dota 2 with Large Scale Deep Reinforcement Learning", u: "https://arxiv.org/abs/1912.06680" }, { t: "Vinyals, O. et al. (2019). Grandmaster level in StarCraft II using multi-agent reinforcement learning. Nature", u: "https://doi.org/10.1038/s41586-019-1724-z" }, { t: "Badia, A. P. et al. (2020). Agent57: Outperforming the Atari Human Benchmark", u: "https://arxiv.org/abs/2003.13350" }] },
/* ── T30 データ生成 ── */
{ id: "M-092", set: "mock", sec: "T30", kw: ["Pix2Pix","CycleGAN","NeRF"], type: "best",
  stem: "次の（ア）〜（ウ）の目的と、それに最も合うモデルの組み合わせとして、最も適切なものを1つ選べ。<br>（ア）建物の線画と、それに対応する完成写真のペアが大量にある。線画から写真風の画像を作りたい<br>（イ）夏の風景写真の集まりと冬の風景写真の集まりはあるが、同じ場所・同じ構図の写真のペアはない。夏の写真を冬の写真風に変えたい<br>（ウ）ある部屋をさまざまな方向から撮った写真と、それぞれのカメラの位置・向きがある。撮影していない位置から見た部屋の画像を作りたい",
  choices: ["（ア）CycleGAN　（イ）Pix2Pix　（ウ）NeRF", "（ア）Pix2Pix　（イ）CycleGAN　（ウ）DCGAN", "（ア）DCGAN　（イ）Pix2Pix　（ウ）NeRF", "（ア）Pix2Pix　（イ）CycleGAN　（ウ）NeRF"],
  ans: 3,
  exp: "Pix2Pix（Isola ら, 2016）は、入力画像と正解の出力画像のペアから変換を学ぶ条件付き GAN である。CycleGAN（Zhu ら, 2017）は、2つの生成器とサイクル一貫性損失を使い、ペアのない2つの画像の集まりの間の変換を学ぶ。NeRF（Mildenhall ら, 2020）は、多視点の写真とカメラの位置・向きから、3次元の場面を関数として表し、新しい視点の画像を作る。",
  why: ["（ア）と（イ）が逆である。ペアがない（イ）に、ペアを必要とする Pix2Pix は使えない。", "（ウ）の DCGAN は、畳み込みを使ってノイズから画像を作る GAN であり、撮影した写真とカメラの位置・向きから別の視点の画像を作る仕組みはもたない。", "（ア）の DCGAN は入力画像を条件として変換するモデルではなく、（イ）の Pix2Pix はペアの画像が必要である。", "正しい。ペアがあれば Pix2Pix、ペアがなければ CycleGAN、多視点の写真から新しい視点を作るなら NeRF である。"],
  src: [{ t: "Isola, P. et al. (2016). Image-to-Image Translation with Conditional Adversarial Networks", u: "https://arxiv.org/abs/1611.07004" }, { t: "Zhu, J.-Y. et al. (2017). Unpaired Image-to-Image Translation using Cycle-Consistent Adversarial Networks", u: "https://arxiv.org/abs/1703.10593" }, { t: "Mildenhall, B. et al. (2020). NeRF: Representing Scenes as Neural Radiance Fields for View Synthesis", u: "https://arxiv.org/abs/2003.08934" }] },
{ id: "M-093", set: "mock", sec: "T30", kw: ["敵対的生成ネットワーク (GAN)","画像生成"], type: "worst",
  stem: "敵対的生成ネットワーク（GAN）に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["モード崩壊とは、生成器が多様なデータを作らず、一部の種類のデータばかり作るようになる現象である", "生成器は訓練データを直接見ることはなく、識別器を通して流れてくる勾配だけをもとに、本物らしいデータを作るように更新される", "GAN は、生成するデータの確率密度（尤度）を明示的な式で計算し、その値を最大にするように学習する", "条件付き GAN では、生成器と識別器の両方にクラスのラベルなどの条件を与えることで、指定したクラスのデータを生成できる"],
  ans: 2,
  exp: "GAN（Goodfellow ら, 2014）は、生成器と識別器を競わせることでデータの分布をまねる。原論文は、生成するデータの分布 p<sub>g</sub>(x) を明示的に表さないことを欠点として挙げ、生成器がデータそのものではなく識別器を通る勾配だけで更新される点を利点として挙げている。また、生成器と識別器の学習の釣り合いを保つ必要があり、生成器だけを学習しすぎると多くの入力のノイズが同じデータに対応してしまう（モード崩壊にあたる）ことも欠点として挙げている。",
  why: ["適切。生成器が識別器をだましやすい一部のデータばかりを作り、多様性が失われる現象である。", "適切。原論文は、生成器はデータの例で直接更新されず、識別器を通って流れてくる勾配だけで更新されると述べている。", "不適切（これが正解）。GAN は確率密度を明示的に表さず、識別器との競争を通じて分布を学ぶ。尤度を明示的に扱わない点が、VAE などとの違いの1つである。", "適切。Mirza と Osindero（2014）は、条件 y を生成器と識別器の両方に入力する条件付き GAN を示し、クラスのラベルを条件に MNIST の数字を生成した。Pix2Pix もこの考え方を使う。"],
  src: [{ t: "Goodfellow, I. et al. (2014). Generative Adversarial Networks", u: "https://arxiv.org/abs/1406.2661" }, { t: "Mirza, M. & Osindero, S. (2014). Conditional Generative Adversarial Nets", u: "https://arxiv.org/abs/1411.1784" }] },
{ id: "M-094", set: "mock", sec: "T30", kw: ["Diffusion Model","画像生成"], type: "blank",
  stem: "拡散モデルの DDPM では、画像にノイズを加えたものを入力として、（ア）を予測するようにニューラルネットワークを学習し、生成時は完全なノイズからその予測を使ってノイズを少しずつ取り除く。Stable Diffusion の基になった潜在拡散モデルでは、計算量を減らすため、拡散の過程を（イ）で行う。（ア）（イ）に入る語句の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["（ア）加えられたノイズ　（イ）事前学習したオートエンコーダで圧縮した潜在空間", "（ア）入力が本物の画像か生成された画像かの確率　（イ）事前学習したオートエンコーダで圧縮した潜在空間", "（ア）加えられたノイズ　（イ）元の画像よりも解像度を上げた画素の空間", "（ア）入力が本物の画像か生成された画像かの確率　（イ）元の画像よりも解像度を上げた画素の空間"],
  ans: 0,
  exp: "DDPM（Ho ら, 2020）は、ノイズを加えた画像から加えられたノイズ ε を予測するようにネットワークを学習し、生成時はそれを使ってノイズを取り除く操作を多数の段階くり返す。画素の空間で拡散を行うと学習・生成の計算量が大きいため、潜在拡散モデル（Rombach ら, 2021）は、事前学習したオートエンコーダの潜在空間で拡散を行った。",
  why: ["正しい。ノイズの予測と、圧縮した潜在空間での拡散が、それぞれ DDPM と潜在拡散モデルの要点である。", "本物か生成されたものかを判定するのは GAN の識別器の役割である。拡散モデルは識別器を使わない。", "（イ）が誤りである。画素の空間のまま解像度を上げると、計算量はかえって増える。潜在拡散モデルは、圧縮した潜在空間で拡散を行って計算量を減らした。", "（ア）（イ）とも誤りである。本物かどうかの確率は GAN の識別器の出力であり、画素の空間の解像度を上げても計算量は減らない。"],
  src: [{ t: "Ho, J., Jain, A. & Abbeel, P. (2020). Denoising Diffusion Probabilistic Models", u: "https://arxiv.org/abs/2006.11239" }, { t: "Rombach, R. et al. (2021). High-Resolution Image Synthesis with Latent Diffusion Models", u: "https://arxiv.org/abs/2112.10752" }] },
/* ── T31 転移学習・ファインチューニング ── */
{ id: "M-095", set: "mock", sec: "T31", kw: ["事前学習済みモデル","事前学習"], type: "best",
  stem: "工場で撮った部品の画像を、不良の種類ごとに分類したい。ラベル付きの画像は各クラス数十枚しかない。ImageNet で事前学習済みの CNN を使う進め方として、最も適切なものを1つ選べ。",
  choices: ["事前学習済みの重みは使わず、乱数で初期化した大きな CNN を数十枚の画像で最初から学習した方が、元のタスクの影響を受けず過学習もしにくい", "まず事前学習済みの層の重みを固定し、新しく加えた出力層だけを学習する。必要に応じて、そのあと固定を解き、小さな学習率でモデル全体を微調整する", "事前学習済みモデルは元の1,000クラスしか出力できないため、ImageNet にない不良の種類の分類には使えない", "データが少ないときほど、事前学習済みのすべての層の重みを大きな学習率で更新した方が、過学習しにくい"],
  ans: 1,
  exp: "転移学習の典型的な手順は、事前学習済みのモデルから層を取り出して重みを固定し、その上に新しい層を加えて、目的のデータで新しい層だけを学習するものである。そのあと、任意で固定を解き、非常に小さな学習率でモデル全体を学習し直す（ファインチューニング）。データが少ない場面で特に効果があるが、全体を更新すると過学習しやすいので注意が要る。",
  why: ["数十枚の画像で大きな CNN を最初から学習すると、過学習しやすく、精度も上がりにくい。少ないデータで高い精度を出すために事前学習済みモデルを使う。", "正しい。Keras の解説でも、層を固定して新しい層を学習し、最後に任意で非常に小さな学習率で全体を微調整する手順が示されている。", "出力層を目的のクラスの数に合わせて付け替えれば、入力に近い層が学んだエッジや形などの特徴を、別のクラスの分類に生かせる。", "データが少ないのに多くの重みを大きく動かすと、過学習しやすく、事前学習で得た特徴も壊れやすい。更新するなら小さな学習率を使う。"],
  src: [{ t: "Keras Developer Guides: Transfer learning & fine-tuning", u: "https://keras.io/guides/transfer_learning/" }, { t: "Yosinski et al. (2014). How transferable are features in deep neural networks?", u: "https://arxiv.org/abs/1411.1792" }] },
{ id: "M-096", set: "mock", sec: "T31", kw: ["自己教師あり学習"], type: "worst",
  stem: "自己教師あり学習の例として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["文中の単語の一部を隠し、前後の文脈から元の単語を当てさせる BERT のマスク言語モデル", "同じ画像に別々の加工をしたもの同士の表現を近づけ、他の画像の表現からは遠ざける SimCLR の対照学習", "それまでの文脈から次の単語を予測させる、GPT 系の言語モデルの事前学習", "人が1枚ずつクラスのラベルを付けた ImageNet の画像で、1,000 クラスのどれかを当てさせる画像分類の学習"],
  ans: 3,
  exp: "自己教師あり学習は、人がラベルを付ける代わりに、データ自体から自動的に作った正解を使って学習する方法である。隠した単語・次の単語・同じ画像から作った別の加工の組などは、データから機械的に作れる。人手で付けたクラスのラベルを当てる学習は、通常の教師あり学習である。",
  why: ["適切。隠す前の単語という正解を、文そのものから自動で作れる。", "適切。SimCLR は、同じ画像から作った2つの加工を正しい組とし、ラベルを使わずに表現を学ぶ（Chen ら, 2020）。", "適切。次の単語という正解は、テキストそのものから自動で得られる。", "不適切（これが正解）。正解が人手で付けたラベルなので、自己教師あり学習ではなく教師あり学習である。ただし、こうして学習したモデルも事前学習済みモデルとして転移学習に使われる。"],
  src: [{ t: "Jing, L. & Tian, Y. (2019). Self-supervised Visual Feature Learning with Deep Neural Networks: A Survey", u: "https://arxiv.org/abs/1902.06162" }, { t: "Chen et al. (2020). A Simple Framework for Contrastive Learning of Visual Representations", u: "https://arxiv.org/abs/2002.05709" }, { t: "Devlin et al. (2018). BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding", u: "https://arxiv.org/abs/1810.04805" }] },
/* ── T32 マルチモーダル ── */
{ id: "M-097", set: "mock", sec: "T32", kw: ["CLIP"], type: "calc",
  stem: "CLIP の事前学習では、N 組の画像と説明文を1つのバッチとして入れ、すべての画像とすべての文の組み合わせについて埋め込みの類似度を計算する。そして、本来の組（正しい組）の類似度を高め、それ以外の組（誤った組）の類似度を低くするように学習する。N ＝ 32 のとき、バッチ全体での正しい組と誤った組の数として、正しいものを1つ選べ。",
  choices: ["正しい組 32、誤った組 31", "正しい組 32、誤った組 992", "正しい組 32、誤った組 1,024", "正しい組 1、誤った組 31"],
  ans: 1,
  exp: "CLIP（Radford ら, 2021）は、N 組の（画像, 文）について N × N 通りの組み合わせのうち、どれが実際の組かを当てるように学習する。正しい N 組の埋め込みのコサイン類似度を高め、残りの N<sup>2</sup> − N 組の類似度を低くする対照学習である。N ＝ 32 なら、32 × 32 ＝ 1,024 通りのうち、正しい組が 32、誤った組が 1,024 − 32 ＝ 992 になる。",
  why: ["画像1枚について見た誤った組の数（32 − 1 ＝ 31）であり、バッチ全体の数ではない。", "正しい。32 × 32 ＝ 1,024 通りから正しい 32 組を除いた 992 組が、誤った組である。", "1,024 は組み合わせ全体の数であり、正しい 32 組を差し引いていない。", "画像1枚あたりの数（正しい組 1、誤った組 31）であり、バッチ全体の数ではない。"],
  src: [{ t: "Radford et al. (2021). Learning Transferable Visual Models From Natural Language Supervision", u: "https://arxiv.org/abs/2103.00020" }] },
{ id: "M-098", set: "mock", sec: "T32", kw: ["基盤モデル","マルチタスク学習","Flamingo","Visual Question Answering"], type: "worst",
  stem: "マルチモーダルなモデルや関連する学習の方法に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["基盤モデルという呼び名は、大規模で幅広いデータで学習し、多様な下流タスクに適応させられるモデルを指して、スタンフォード大学の Bommasani ら（2021）が提唱した", "マルチタスク学習で、隠れ層を全タスクで共有し、出力層だけをタスクごとに分ける方法（ハードパラメータ共有）は、過学習の危険を大きく下げるとされる", "Flamingo は、文章を入力して画像を生成する Text-To-Image のモデルであり、画像を入力として受け取ることはできない", "VQA の研究には、視覚障害のある人が撮影した写真と、その写真について録音した質問を集めたデータセット（VizWiz）も使われている"],
  ans: 2,
  exp: "Flamingo（Alayrac ら, 2022）は、画像や動画と文章が交互に並んだ入力を受け取り、文章を出力する視覚言語モデルである。事前学習済みで重みを固定した画像のエンコーダと言語モデルを、新しく学習する層でつなぎ、入力の中で数例を示すだけで画像の説明や VQA などをこなす。文章から画像を作るのは DALL-E などの Text-To-Image のモデルである。",
  why: ["適切。論文は BERT・GPT-3・CLIP などを例に挙げ、規模による新しい能力の出現と、欠陥や偏りが下流に引き継がれるリスクを論じた。", "適切。Ruder（2017）は、ハードパラメータ共有が過学習の危険を大きく下げると述べている。", "不適切（これが正解）。Flamingo は画像と文章を入力して文章を出力するモデルであり、入出力の向きが Text-To-Image とは逆である。", "適切。VizWiz（Gurari ら, 2018）は、日常生活の中で生じる視覚的な質問に答える技術の研究に使われている。"],
  src: [{ t: "Bommasani et al. (2021). On the Opportunities and Risks of Foundation Models", u: "https://arxiv.org/abs/2108.07258" }, { t: "Ruder, S. (2017). An Overview of Multi-Task Learning in Deep Neural Networks", u: "https://arxiv.org/abs/1706.05098" }, { t: "Alayrac et al. (2022). Flamingo: a Visual Language Model for Few-Shot Learning", u: "https://arxiv.org/abs/2204.14198" }, { t: "Gurari et al. (2018). VizWiz Grand Challenge: Answering Visual Questions from Blind People", u: "https://arxiv.org/abs/1802.08218" }] },
{ id: "M-099", set: "mock", sec: "T32", kw: ["DALL-E","Text-To-Image"], type: "best",
  stem: "DALL-E 2（2022）が文章から画像を生成する仕組みの説明として、最も適切なものを1つ選べ。",
  choices: ["文から CLIP の画像埋め込みを作る部分（prior）と、その埋め込みを条件として画像を作る拡散モデルのデコーダの、2段階で生成する", "初代の DALL-E と同じく、画像を離散的なトークンの列に変え、文のトークンに続けて Transformer で前から順に生成する方法だけを使う", "生成器と識別器を競わせる GAN だけで画像を生成し、CLIP は一切使わない", "CLIP そのものが文から画像を生成するモデルであり、DALL-E 2 は CLIP の出力した画像をそのまま表示している"],
  ans: 0,
  exp: "DALL-E 2（Ramesh ら, 2022。論文では unCLIP と呼ぶ）は、文のキャプションから CLIP の画像埋め込みを作る prior と、画像埋め込みを条件に画像を作るデコーダの2段階のモデルである。デコーダには拡散モデルを使い、prior には自己回帰モデルと拡散モデルの両方を試した。初代の DALL-E（2021）は、画像トークンを Transformer で自己回帰的に生成する方式だった。",
  why: ["正しい。CLIP の画像埋め込みを明示的に作ってから画像にすることで、写実性をほとんど損なわずに多様性が上がったと報告されている。", "これは初代の DALL-E（2021）の方式である。DALL-E 2 は CLIP の埋め込みと拡散モデルを使う方式に変わった。", "DALL-E 2 は GAN ではなく拡散モデルのデコーダで画像を作り、CLIP の埋め込み空間を利用する。", "CLIP は画像と文を同じ空間に埋め込んで近さを測るモデルであり、それ自体は画像を生成しない。"],
  src: [{ t: "Ramesh et al. (2022). Hierarchical Text-Conditional Image Generation with CLIP Latents", u: "https://arxiv.org/abs/2204.06125" }, { t: "Ramesh et al. (2021). Zero-Shot Text-to-Image Generation", u: "https://arxiv.org/abs/2102.12092" }] },
/* ── T33 モデルの解釈性 ── */
{ id: "M-100", set: "mock", sec: "T33", kw: ["SHAP","Permutation Importance","Grad-CAM","LIME","CAM"], type: "best",
  stem: "次の（ア）〜（ウ）の目的に最も合う説明の手法の組み合わせとして、最も適切なものを1つ選べ。<br>（ア）融資の審査モデルで、ある申込者が否決された理由を特徴量ごとの寄与として示し、寄与を合計すると、その申込者の予測値と基準値（予測の平均）の差に一致するようにしたい<br>（イ）学習済みのモデル全体が、どの特徴量に頼っているかを、ある特徴量の値をデータの間で並べ替えたときの性能の低下で調べたい<br>（ウ）全結合層を持つ画像分類の CNN が「猫」と判定した根拠の領域を、構造を変えたり学習し直したりせずにヒートマップで示したい",
  choices: ["（ア）Permutation Importance　（イ）SHAP　（ウ）Grad-CAM", "（ア）SHAP　（イ）LIME　（ウ）CAM", "（ア）LIME　（イ）Permutation Importance　（ウ）CAM", "（ア）SHAP　（イ）Permutation Importance　（ウ）Grad-CAM"],
  ans: 3,
  exp: "SHAP（Lundberg と Lee, 2017）は、各特徴量の寄与（SHAP 値）を足し合わせると予測値と基準値の差に一致する、個々の予測の説明である。Permutation Importance は、1つの特徴量を並べ替えたときの性能の低下でモデル全体での重要度を測る大域的な説明である。Grad-CAM は勾配から特徴マップの重みを求めるため、CAM と違って構造を変えずに多くの CNN に使える。",
  why: ["（ア）と（イ）が逆である。特徴量を並べ替えて性能の低下を見るのは Permutation Importance、寄与の合計が予測値と基準値の差に一致するのは SHAP である。", "（イ）の LIME は、1つの入力の周りで単純なモデルに近似する局所的な説明であり、並べ替えによる性能の低下は測らない。（ウ）の CAM は、最後の畳み込み層の直後に GAP を置いた構造でないと使えない。", "（ア）の LIME は、寄与の合計が予測値と基準値の差に一致することを保証しない。（ウ）の CAM は、全結合層を持つ CNN では構造を変えて学習し直す必要がある。", "正しい。個々の予測の加法的な説明は SHAP、モデル全体の重要度は Permutation Importance、構造を変えずに根拠の領域を示すのは Grad-CAM である。"],
  src: [{ t: "Lundberg, S. M. & Lee, S.-I. (2017). A Unified Approach to Interpreting Model Predictions", u: "https://arxiv.org/abs/1705.07874" }, { t: "scikit-learn User Guide: Permutation feature importance", u: "https://scikit-learn.org/stable/modules/permutation_importance.html" }, { t: "Selvaraju et al. (2017). Grad-CAM: Visual Explanations from Deep Networks via Gradient-Based Localization", u: "https://doi.org/10.1109/ICCV.2017.74" }, { t: "Ribeiro, M. T., Singh, S. & Guestrin, C. (2016). \"Why Should I Trust You?\": Explaining the Predictions of Any Classifier", u: "https://doi.org/10.1145/2939672.2939778" }] },
{ id: "M-101", set: "mock", sec: "T33", kw: ["Grad-CAM","Permutation Importance","SHAP","LIME"], type: "worst",
  stem: "説明可能 AI の手法を使うときの注意点に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Grad-CAM のヒートマップは、入力画像の画素ごとに求めた勾配から直接作るため、入力画像と同じ細かさで根拠の領域を示せる", "Permutation Importance では、強く相関する特徴量があると、片方を並べ替えてももう片方で補えるため、両方の重要度が実際より低く出ることがある", "SHAP 値を厳密に求めるには特徴量の組み合わせを数多く調べる必要があるため、Kernel SHAP のような近似や、決定木系のモデルに特化した効率のよい計算法が使われる", "LIME の説明は、説明したい入力の周りで元のモデルを単純なモデルで近似したものであり、モデル全体の振る舞いを表すものではない"],
  ans: 0,
  exp: "Grad-CAM（Selvaraju ら, 2017）は、対象クラスのスコアの、最後の畳み込み層の特徴マップに対する勾配から重みを求め、特徴マップの重み付き和に ReLU をかけてヒートマップを作る。そのため結果は特徴マップと同じ大きさ（VGG や AlexNet の最後の畳み込み層なら 14×14）の粗いものになる。論文では、画素単位の細かな可視化である Guided Backpropagation と掛け合わせた Guided Grad-CAM も提案している。",
  why: ["不適切（これが正解）。Grad-CAM が使うのは最後の畳み込み層の特徴マップに対する勾配であり、ヒートマップは特徴マップと同じ粗い解像度になる。", "適切。scikit-learn の解説でも、相関する特徴量の一方を並べ替えても、モデルはもう一方の特徴量を使えるため、両方の重要度が低く報告されることがあると注意している。", "適切。シャープレイ値の厳密な計算は特徴量の数が増えると難しくなるため、Kernel SHAP（モデル非依存の近似）や、決定木系のモデルで効率よく厳密な値を求める方法が提案されている。", "適切。LIME は局所的な説明であり、その近似はその入力の周りでだけ成り立つ。"],
  src: [{ t: "Selvaraju et al. (2017). Grad-CAM: Visual Explanations from Deep Networks via Gradient-Based Localization", u: "https://doi.org/10.1109/ICCV.2017.74" }, { t: "scikit-learn User Guide: Permutation feature importance", u: "https://scikit-learn.org/stable/modules/permutation_importance.html" }, { t: "Lundberg, S. M. & Lee, S.-I. (2017). A Unified Approach to Interpreting Model Predictions", u: "https://arxiv.org/abs/1705.07874" }, { t: "Lundberg et al. (2020). From local explanations to global understanding with explainable AI for trees", u: "https://doi.org/10.1038/s42256-019-0138-9" }, { t: "Ribeiro, M. T., Singh, S. & Guestrin, C. (2016). \"Why Should I Trust You?\": Explaining the Predictions of Any Classifier", u: "https://doi.org/10.1145/2939672.2939778" }] },
/* ── T34 モデルの軽量化 ── */
{ id: "M-102", set: "mock", sec: "T34", kw: ["宝くじ仮説","量子化","蒸留"], type: "worst",
  stem: "モデルの軽量化に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["8 ビットの整数で表せる値は 256 段階しかないため、量子化では、元の実数の値の範囲をこの段階に割り当てる幅（スケール）を決める必要がある", "蒸留では、教師モデルが誤りのクラスに与えた小さな確率どうしの違いにも、クラスどうしの似かたについての情報が含まれており、生徒モデルはそれも手がかりに学習できる", "宝くじ仮説の論文では、部分ネットワーク（当たりくじ）を、学習を一度も行わずに、乱数で初期化した直後の重みの絶対値の大きさだけで選び出した", "蒸留で生徒モデルの学習に使うデータは、元の訓練データでもよく、正解ラベルの付いていないデータでもよい"],
  ans: 2,
  exp: "宝くじ仮説（Frankle と Carbin, 2019）は、ランダムに初期化した密なネットワークに、単独で学習しても同程度の精度に達する部分ネットワーク（当たりくじ）が含まれているとする。論文では、(1) ネットワークを初期化して学習し、(2) 学習後の重みの絶対値が小さいものを取り除き、(3) 残った重みを学習前の初期値に戻す、という手順（くり返すこともある）で当たりくじを見つけた。",
  why: ["適切。量子化では、実数の値をスケールで割って整数に丸める。値の範囲（クリッピングの範囲）をいくつの区画に分けられるかが、ビット数で決まる（Gholami ら, 2021）。", "適切。Hinton ら（2015）は、例えば BMW の画像がごみ収集車と間違えられる確率は非常に小さいが、それでもニンジンと間違えられる確率よりはずっと大きい、といった誤りのクラスの確率の比に、教師モデルの汎化の仕方が表れると述べている。", "不適切（これが正解）。当たりくじは、いったん学習したあとの重みの大きさで取り除く結合を決め、残った重みを学習前の初期値に戻して見つける。学習前の重みの大きさだけで選んだのではない。", "適切。Hinton ら（2015）は、生徒モデルの学習に使うデータ（転移用のデータ）は、ラベルのないデータだけでもよく、元の訓練データを使ってもよいと述べている。"],
  src: [{ t: "Frankle, J. & Carbin, M. (2019). The Lottery Ticket Hypothesis: Finding Sparse, Trainable Neural Networks", u: "https://arxiv.org/abs/1803.03635" }, { t: "Hinton, G., Vinyals, O. & Dean, J. (2015). Distilling the Knowledge in a Neural Network", u: "https://arxiv.org/abs/1503.02531" }, { t: "Gholami et al. (2021). A Survey of Quantization Methods for Efficient Neural Network Inference", u: "https://arxiv.org/abs/2103.13630" }] },
{ id: "M-103", set: "mock", sec: "T34", kw: ["プルーニング","モデル圧縮"], type: "best",
  stem: "学習済みの画像分類の CNN を、スマートフォンでより速く動かしたい。端末では、まばらな行列の計算に対応した専用のライブラリやハードウェアは使えず、通常の密な行列計算のライブラリしか使えない。推論の計算の大部分は畳み込み層が占めている。この場面でのプルーニングの進め方として、最も適切なものを1つ選べ。",
  choices: ["畳み込み層の個々の重みのうち、絶対値の小さいものから9割を0にする。層の形はそのままにして、通常のライブラリで計算する", "出力への影響が小さい畳み込みのフィルタを、それにつながる特徴マップごと取り除いて層を細くし、そのあと再学習して精度を取り戻す", "全結合層の重みのうち絶対値の小さいものを中心に取り除く。パラメータの数が大きく減れば、推論の計算時間もそれに比例して減る", "フィルタを取り除くと層の形が変わり、残った重みはそのまま使えないため、小さくした構造を乱数で初期化して最初から学習し直す"],
  ans: 1,
  exp: "個々の重みを取り除くプルーニング（Han ら, 2015）はパラメータを大きく減らせるが、取り除かれるパラメータの多くは計算量の小さい全結合層のもので、畳み込み層の重みを取り除いても不規則にまばらな行列になるだけなので、通常の密な行列計算では計算時間が減りにくい。Li ら（2017）は、出力への影響が小さいフィルタを、つながる特徴マップごと取り除く方法を示した。この方法はまばらな結合を生まないため、通常の密な行列計算のライブラリで計算を減らせ、残った重みを引き継いで再学習することで元に近い精度を取り戻した。",
  why: ["層の形は変わらず、0 になった重みが不規則に散らばるだけである。通常の密な行列計算では 0 との掛け算も行うため、計算は減りにくい。", "正しい。フィルタ単位のプルーニングは層そのものを細くするため、通常の密な行列計算のままでも計算量が減る。", "Li ら（2017）によれば、VGG-16 の全結合層はパラメータ全体の90%を占めるが、浮動小数点演算の1%未満しか担っていない。パラメータの数が減っても、計算時間はそれに比例しては減らない。", "Li ら（2017）は、取り除かれなかった重みを新しいモデルに写して再学習しており、小さくした構造を最初から学習し直すと、再学習した場合より精度が下がったと報告している。"],
  src: [{ t: "Han et al. (2015). Learning both Weights and Connections for Efficient Neural Networks", u: "https://arxiv.org/abs/1506.02626" }, { t: "Li et al. (2017). Pruning Filters for Efficient ConvNets", u: "https://arxiv.org/abs/1608.08710" }, { t: "Cheng et al. (2017). A Survey of Model Compression and Acceleration for Deep Neural Networks", u: "https://arxiv.org/abs/1710.09282" }] },
/* ── T35 AI プロジェクトの進め方 ── */
{ id: "M-104", set: "mock", sec: "T35", kw: ["CRISP-DM"], type: "best",
  stem: "CRISP-DM の段階と、その段階で行う作業の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["データの準備 ― プロジェクトの目的を踏まえ、何をもってビジネス上の成功とするかの基準を定める", "モデリング ― 作ったモデルの結果が、プロジェクトの初めに定めたビジネス上の成功の基準を満たすかを、意思決定者を交えて判断する", "データの理解 ― 最初のデータを集めて内容を記述・探索し、欠測値やコードの誤りがないかなど、データの品質を確かめる", "評価 ― 業務で使い始めたモデルの監視と保守の計画を立て、最終報告書をまとめる"],
  ans: 2,
  exp: "CRISP-DM は、ビジネスの理解 → データの理解 → データの準備 → モデリング → 評価 → 展開の6段階で進める。データの理解では、最初のデータを集め、記述・探索し、データの品質を確かめる。見つけた欠測値などを実際に補ったり取り除いたりするのは、次のデータの準備（クリーニング）である。成功の基準は最初のビジネスの理解で定め、評価の段階でその基準に照らして結果を判断する。",
  why: ["成功の基準を定めるのは、最初の段階であるビジネスの理解である。データの準備では、データの選択・クリーニング・新しい属性の作成・統合・形式の変換を行う。", "ビジネス上の成功の基準に照らして結果を判断するのは評価の段階である。モデリングでは、手法を選び、パラメータを調整してモデルを作り、データマイニングの観点から技術的に評価する。", "正しい。データの理解は、最初のデータの収集、記述、探索、データの品質の確認からなる。", "監視と保守の計画や最終報告書の作成は、最後の展開の段階の作業である。なお、運用中の監視と保守を独立した段階として設けたのが CRISP-ML(Q) である。"],
  src: [{ t: "IBM SPSS Modeler CRISP-DM Guide", u: "https://public.dhe.ibm.com/software/analytics/spss/documentation/modeler/17.0FP1/en/ModelerCRISPDM.pdf" }, { t: "Chapman, P. et al. (2000). CRISP-DM 1.0: Step-by-step data mining guide（Internet Archive 保存版）", u: "https://web.archive.org/web/20220401041957/https://www.the-modeling-agency.com/crisp-dm.pdf" }] },
{ id: "M-105", set: "mock", sec: "T35", kw: ["Python","Docker","クラウド","Jupyter Notebook"], type: "worst",
  stem: "AI の開発に使われる道具や環境に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Python はインタプリタ型の言語であり、実行ファイルを別に作らなくても、ソースファイルをそのまま実行できる", "Docker のイメージはコンテナを作るための読み取り専用のテンプレートであり、コンテナはイメージを実行できる形にしたもの（実行の単位）である", "クラウドの IaaS では、利用者は計算資源やストレージを借りて OS やアプリケーションを自由に導入できるが、その下にあるクラウドの基盤（物理的なサーバーやネットワークなど）は管理しない", "Jupyter Notebook のカーネルはセルを実行するたびに状態がリセットされるため、前に実行したセルで定義した変数は、次のセルでは使えない"],
  ans: 3,
  exp: "Jupyter Notebook では、ノートブックごとに起動したカーネル（コードを実行する別のプロセス）が、計算の状態を保ち続ける。そのため、前のセルで定義した変数を後のセルで使える。状態を消したいときはカーネルを再起動する。セルは任意の順に実行できるので、実行した順によって結果が変わることがある点に注意が要る。",
  why: ["適切。Python の公式の用語集は、Python をコンパイル型ではなくインタプリタ型の言語とし、ソースファイルを直接実行できるとしている（実際にはバイトコードへのコンパイルも行われる）。", "適切。Docker の公式文書は、イメージを「コンテナを作るための指示を含む読み取り専用のテンプレート」、コンテナを「イメージの実行可能なインスタンス」と説明している。", "適切。NIST の定義では、IaaS の利用者は OS やアプリケーションを含む任意のソフトウェアを導入・実行できるが、その下のクラウドの基盤は管理しない。", "不適切（これが正解）。公式文書は「カーネルはノートブックの計算の状態を保持する」とし、状態を消すにはカーネルを再起動するとしている。"],
  src: [{ t: "Python Documentation. Glossary（interpreted・bytecode）", u: "https://docs.python.org/3/glossary.html" }, { t: "Docker Docs. What is Docker?", u: "https://docs.docker.com/get-started/docker-overview/" }, { t: "Mell, P. & Grance, T. (2011). The NIST Definition of Cloud Computing（NIST SP 800-145）", u: "https://doi.org/10.6028/NIST.SP.800-145" }, { t: "Jupyter Notebook Documentation. Running Code", u: "https://jupyter-notebook.readthedocs.io/en/stable/examples/Notebook/Running%20Code.html" }] },
{ id: "M-106", set: "mock", sec: "T35", kw: ["MLOps"], type: "best",
  stem: "Google Cloud による MLOps の解説（機械学習の継続的デリバリーと自動化のパイプライン）の内容として、最も適切なものを1つ選べ。",
  choices: ["機械学習システムの CI（継続的インテグレーション）は、従来のソフトウェアと同じく、コードとコンポーネントのテストだけを対象とする", "最も成熟度の低いレベル 0（手動のプロセス）では、モデルの予測を記録して性能を能動的に監視し、新しいモデルを頻繁に自動でリリースする", "CT（継続的トレーニング）は従来のソフトウェア開発にもともとある性質であり、機械学習に特有の考え方ではない", "レベル 1 の目標は、機械学習のパイプラインを自動化して、モデルの継続的トレーニング（CT）を行うことである"],
  ans: 3,
  exp: "この解説は、機械学習システムでは CI がコードだけでなくデータ・データのスキーマ・モデルの検証も含み、CD が学習パイプラインそのものを届ける仕組みになると説明する。さらに、モデルを自動で再学習して予測サービスに反映する CT を、機械学習システムに特有の新しい性質としている。自動化の度合いをレベル 0〜2 に分け、レベル 1 の目標をパイプラインの自動化による継続的トレーニングとしている。",
  why: ["解説は、機械学習の CI は「コードとコンポーネントのテストと検証だけではなくなる」とし、データ・スキーマ・モデルのテストと検証も含むとしている。", "逆である。レベル 0 では新しいモデルのリリースは年に数回程度で、CI・CD は考慮されず、モデルの予測や動作を記録しない（能動的な性能監視がない）とされている。", "解説は CT を「機械学習システムに特有の新しい性質」とし、モデルを自動で再学習して提供することにかかわるものと説明している。", "正しい。レベル 1 の目標は、機械学習パイプラインを自動化して、モデルの継続的トレーニングを行うことである。"],
  src: [{ t: "Google Cloud Architecture Center. MLOps: Continuous delivery and automation pipelines in machine learning", u: "https://docs.cloud.google.com/architecture/mlops-continuous-delivery-and-automation-pipelines-in-machine-learning" }] },
{ id: "M-107", set: "mock", sec: "T35", kw: ["オープン・イノベーション"], type: "blank",
  stem: "2003年、当時ハーバード大学経営大学院の教授だった（　）は、著書『Open Innovation』で、企業の内部と外部の技術やアイデアの出入りを意図的に活用するオープン・イノベーションを提唱し、自社内の資源だけで研究開発から製品化までを行う従来のやり方を「クローズドイノベーション」と呼んだ。（　）に入る人物として、最も適切なものを1つ選べ。",
  choices: ["マイケル・ハマー", "ヘンリー・チェスブロウ", "トーマス・ダベンポート", "ウィンストン・ロイス"],
  ans: 1,
  exp: "オープン・イノベーションの概念が注目されるきっかけは、Henry W. Chesbrough（チェスブロウ）が2003年に発表した著書である。同氏は、組織内のイノベーションを促すために内部と外部の資源の流出入を意図的・積極的に活用し、組織内で生まれたイノベーションを外部で展開する機会も増やすことと定義した。日本では NEDO などの「オープンイノベーション白書」がこの定義を紹介している。",
  why: ["ハマーは、1990年の論文「Reengineering Work: Don't Automate, Obliterate」で BPR（業務の流れの抜本的な再設計）を提唱した人物である。", "正しい。2003年の著書でオープン・イノベーションを定義し、従来の自前主義をクローズドイノベーションと呼んだ。", "ダベンポートは、2012年に Patil と共著で、データサイエンティストを「21世紀で最もセクシーな職業」と呼んだ HBR の記事で知られる。", "ロイスは、ウォーターフォール型の開発の説明でよく引かれる1970年の論文「Managing the Development of Large Software Systems」の著者である。"],
  src: [{ t: "オープンイノベーション協議会・NEDO「オープンイノベーション白書 初版」（2016年7月）", u: "https://www.nedo.go.jp/content/100790965.pdf" }, { t: "Hammer, M. (1990). Reengineering Work: Don't Automate, Obliterate. Harvard Business Review", u: "https://hbr.org/1990/07/reengineering-work-dont-automate-obliterate" }, { t: "Davenport, T. H. & Patil, D. J. (2012). Data Scientist: The Sexiest Job of the 21st Century. Harvard Business Review", u: "https://hbr.org/2012/10/data-scientist-the-sexiest-job-of-the-21st-century" }, { t: "Royce, W. W. (1970). Managing the Development of Large Software Systems", u: "https://faculty.washington.edu/hazeline/misc/reserve/royce_waterfall.pdf" }] },
{ id: "M-108", set: "mock", sec: "T35", kw: ["BPR","AI のビジネス活用"], type: "best",
  stem: "ある会社の経費精算は、紙の申請書を提出し、上長の3段階の承認を経て、経理担当者が会計システムに手で入力する流れになっている。AI の導入にあたり、BPR（ビジネスプロセス・リエンジニアリング）の考え方に最も沿った取組を1つ選べ。",
  choices: ["紙の申請書を AI の文字認識で読み取り、経理担当者の入力作業だけを自動化する。申請と承認の手順はそのまま残す", "なぜ3段階の承認が必要かという前提から見直して不要な工程をなくし、申請の時点からデータで受け付け、AI が不正や誤りの疑いを示したものだけを人が確認する流れに作り直す", "申請する部門・承認する上長・経理部門が、それぞれ自部門の担当する作業だけに AI を取り入れて効率化する。部門をまたぐ申請から入力までの流れや受け渡しの順序は変えない", "紙の申請書と3段階の承認はそのまま残し、承認を終えた申請を AI がもう一度審査する工程を最後に加えて、不正や誤りを見つけやすくする"],
  ans: 1,
  exp: "BPR は、既存の業務の流れを前提にせず、根本から見直して抜本的に設計し直す経営手法である。提唱した Hammer の1990年の論文の題名「Don't Automate, Obliterate（自動化するな、一掃せよ）」が示すとおり、古いやり方をそのまま自動化するのではなく、やり方そのものを作り直す。AI の導入でも、今の手作業を AI に置き換えるだけでは効果が限られることがあり、AI を前提に業務の流れ全体を設計し直すことが重要になる。",
  why: ["既存の流れを変えずに一部の作業を自動化するもので、BPR の論文の題名が戒める「そのままの自動化」にあたる。効率化にはなるが、抜本的な再設計ではない。", "正しい。業務の前提から見直して流れ全体を作り直し、そのうえで AI と人の役割を設計している。", "部門ごとの作業を個別に効率化するもので、部門をまたぐ業務の流れ全体は見直していない。BPR は、個々の作業ではなく、業務の流れ全体を設計し直す。", "既存の流れをそのまま残し、その上に AI による確認の工程を重ねるもので、流れを設計し直すものではない。工程が増える分、処理にかかる時間はかえって長くなりうる。"],
  src: [{ t: "Hammer, M. (1990). Reengineering Work: Don't Automate, Obliterate. Harvard Business Review", u: "https://hbr.org/1990/07/reengineering-work-dont-automate-obliterate" }] },
{ id: "M-109", set: "mock", sec: "T35", kw: ["データサイエンティスト","ステークホルダーのニーズ","他企業や他業種との連携"], type: "worst",
  stem: "AI プロジェクトを担う人材や関係者との連携に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["データサイエンティスト協会の定義では、データサイエンティストに求められるのはデータサイエンス力だけであり、課題の背景を理解してビジネス課題を整理・解決する力は、ビジネス部門の担当者に求められるもので、データサイエンティストのスキルには含まれない", "データサイエンティスト協会は、データエンジニアリング力を「データサイエンスを意味のある形に使えるようにし、実装、運用できるようにする力」としている", "CRISP-ML(Q) は、プロジェクトの成功の基準を、ビジネス上の基準、機械学習の基準、経済的な基準（KPI）の3つの層で定めることを勧めている", "他社とデータを持ち寄って AI を共同で開発する場合は、提供するデータの利用範囲や、生まれた成果物の権利の扱いを、契約で取り決めておくことが重要である"],
  ans: 0,
  exp: "データサイエンティスト協会は、データサイエンティストに求められるスキルを、ビジネス力・データサイエンス力・データエンジニアリング力の3つとしている。ビジネス力は「課題背景を理解した上で、ビジネス課題を整理し、解決する力」である。分析の技術だけでなく、関係者のニーズを課題として整理し、成功の基準に落とし込む力も求められる。",
  why: ["不適切（これが正解）。協会はビジネス力を3つのスキルの一つとしており、データサイエンティストを「ビジネス課題に答えを出すプロフェッショナル」と定義している。", "適切。協会の示すデータエンジニアリング力の説明である。データサイエンス力は「情報処理、人工知能、統計学などの情報科学系の知恵を理解し、使う力」とされる。", "適切。CRISP-ML(Q) は、ビジネス・機械学習・経済の3つの層で成功の基準を定め、互いに矛盾しないようにすることを勧めている。", "適切。経済産業省の契約ガイドラインは、データの利用権限は契約で当事者間で定めるものとし、データや学習済みモデルの扱いを契約で明確にすることの重要性を示している。"],
  src: [{ t: "データサイエンティスト協会「データサイエンティストのスキルチェックリスト」等の公開に関するプレスリリース（2015年11月20日）", u: "https://www.datascientist.or.jp/common/docs/skillcheck.pdf" }, { t: "Studer, S. et al. (2021). Towards CRISP-ML(Q): A Machine Learning Process Model with Quality Assurance Methodology", u: "https://doi.org/10.3390/make3020020" }, { t: "経済産業省「AI・データの利用に関する契約ガイドライン 1.1版」（AI編を含む全体版）", u: "https://www.meti.go.jp/policy/mono_info_service/connected_industries/sharing_and_utilization/20200619001.pdf" }] },
/* ── T36 データの収集・加工・分析・学習 ── */
{ id: "M-110", set: "mock", sec: "T36", kw: ["データリーケージ"], type: "best",
  stem: "ある病院で、患者 300 人から1人あたり平均 10 枚、合計約 3,000 枚の皮膚の画像を集め、病変を判定するモデルを作った。画像を1枚ずつ無作為に訓練用と評価用に分けて評価したところ、評価用データでは非常に高い精度が出たが、新しい患者の画像では精度が大きく下がった。この問題とその対策の説明として、最も適切なものを1つ選べ。",
  choices: ["評価用データの枚数が少なすぎたことが原因なので、訓練用を減らして評価用の割合を増やせば、新しい患者でも同じ精度が出る", "画像の解像度が高すぎたことが原因なので、解像度を下げて学習し直せば解決する", "同じ患者の画像が訓練用と評価用の両方に入り、患者ごとの特徴を手がかりに当てていた可能性がある。患者を単位として、同じ患者の画像がどちらか一方だけに入るように分けて評価する", "新しい患者の画像は病院の外のデータなので、評価に使ってはならず、元の評価用データでの精度だけを報告すればよい"],
  ans: 2,
  exp: "1人の患者から複数のデータを取ると、同じ患者のデータどうしは似ており、独立ではない。データを1件ずつ無作為に分けると、評価用データと同じ患者のデータが訓練用にも入り、モデルが病変ではなく患者ごとの特徴を手がかりにしても高い精度が出てしまう。これは、評価に本来使えない情報が学習の側に入り込むデータリーケージの一種と考えられる。scikit-learn の GroupKFold のように、患者などのグループを単位に分けると、未知のグループへの汎化を正しく評価できる。",
  why: ["評価用データの割合を変えても、同じ患者が訓練用と評価用にまたがる問題は解消しない。", "解像度は、この現象の原因として示された事情と関係がない。問題は、データの分け方にある。", "正しい。グループ（患者）単位で分けることで、学習に使っていない患者に対する性能を評価できる。", "本番で対象となるのは新しい患者であり、その性能を確かめることが評価の目的である。高すぎる評価の値だけを報告するのは誤解を招く。"],
  src: [{ t: "scikit-learn User Guide: Cross-validation（Cross-validation iterators for grouped data）", u: "https://scikit-learn.org/stable/modules/cross_validation.html" }, { t: "Kaufman, S. et al. (2012). Leakage in data mining: Formulation, detection, and avoidance", u: "https://doi.org/10.1145/2382577.2382579" }] },
/* ── T37 AI に必要な数理・統計知識 ── */
{ id: "M-111", set: "mock", sec: "T37", kw: ["平均","標準偏差","分散"], type: "calc",
  stem: "ある都市の日ごとの最高気温（摂氏 ℃）は、平均 20 ℃、標準偏差 5 ℃ であった。このデータをすべて華氏（℉）に変換する（℉ = 1.8 × ℃ + 32）。変換後のデータの平均と標準偏差の組み合わせとして正しいものを1つ選べ。",
  choices: ["平均 68 ℉、標準偏差 9 ℉", "平均 68 ℉、標準偏差 41 ℉", "平均 36 ℉、標準偏差 9 ℉", "平均 68 ℉、標準偏差 81 ℉"],
  ans: 0,
  exp: "データ X を Y = aX + b と変換すると、平均は aμ + b、分散は a² 倍、標準偏差は |a| 倍になる。定数 b を足しても全体が平行に移るだけで、散らばりは変わらない。この例では平均が 1.8 × 20 + 32 = 68、標準偏差が 1.8 × 5 = 9（分散は 25 から 81）となる。",
  why: ["正しい。平均は 1.8 × 20 + 32 = 68、標準偏差は 1.8 × 5 = 9 である。", "標準偏差にも 32 を足した値（9 + 32）である。定数を足しても散らばりは変わらない。", "平均に 32 を足し忘れた値（1.8 × 20）である。", "81 は分散（9²）であり、標準偏差ではない。"],
  src: [{ t: "STAT 414 Introduction to Probability Theory, Lesson 8: Mathematical Expectation（Penn State）", u: "https://online.stat.psu.edu/stat414/Lesson08.html" }] },
{ id: "M-112", set: "mock", sec: "T37", kw: ["二項分布","期待値","分散"], type: "calc",
  stem: "ある広告を 50 人に表示する。各人は互いに独立に、確率 0.2 で広告をクリックするとする。クリックする人数 X の期待値と分散の組み合わせとして正しいものを1つ選べ。",
  choices: ["期待値 10、分散 10", "期待値 0.2、分散 0.16", "期待値 10、分散 1.6", "期待値 10、分散 8"],
  ans: 3,
  exp: "成功確率 p の独立な試行を n 回行ったときの成功回数は二項分布に従い、期待値は np、分散は np(1 − p) である。この例では期待値 50 × 0.2 = 10、分散 50 × 0.2 × 0.8 = 8（標準偏差は約 2.83）となる。期待値と分散が等しくなるのはポアソン分布であり、二項分布では分散は期待値より小さい。",
  why: ["期待値と分散が等しいのはポアソン分布の性質である。二項分布の分散は np(1 − p) = 8 である。", "1人分（1回の試行）のベルヌーイ分布の期待値 p と分散 p(1 − p) である。50 人分の合計ではない。", "p(1 − p) = 0.16 に、n = 50 ではなく期待値の 10 を掛けた誤りである。", "正しい。期待値 np = 10、分散 np(1 − p) = 8 である。"],
  src: [{ t: "STAT 414 Introduction to Probability Theory, Lesson 10: The Binomial Distribution（Penn State）", u: "https://online.stat.psu.edu/stat414/Lesson10.html" }] },
{ id: "M-113", set: "mock", sec: "T37", kw: ["正規分布","標準偏差"], type: "calc",
  stem: "ある試験の得点は平均 50 点、標準偏差 10 点の正規分布に従うとする。受験者 A の得点は 70 点であった。A の得点を標準化した値 z と、70 点以上の受験者の割合の組み合わせとして、最も近いものを1つ選べ。なお、標準正規分布で Z ≦ 2 となる確率は約 0.977 である。",
  choices: ["z = 2、約 5%", "z = 2、約 2.3%", "z = 20、ほぼ 0%", "z = 2、約 47.7%"],
  ans: 1,
  exp: "標準化は z = (x − 平均) ÷ 標準偏差 で行い、ここでは z = (70 − 50) ÷ 10 = 2 となる。標準正規分布で Z ≦ 2 の確率が約 0.977 なので、Z > 2 は約 1 − 0.977 = 0.023（約 2.3%）である。平均 ± 2 標準偏差の範囲に約 95% が入るので、その外側の約 5% が上下に半分ずつ分かれる、と考えても同じ結果になる。",
  why: ["約 5% は、平均から 2 標準偏差より外側にある割合の上下の合計である。70 点以上は上側だけなので、その半分になる。", "正しい。z = 2 で、上側の確率は約 2.3% である。", "平均との差を標準偏差で割っていない値である。", "約 47.7% は、平均（50 点）以上 70 点未満の割合（0.977 − 0.5）である。"],
  src: [{ t: "STAT 414 Introduction to Probability Theory, Lesson 16: Normal Distributions（Penn State）", u: "https://online.stat.psu.edu/stat414/Lesson16.html" }] },
{ id: "M-114", set: "mock", sec: "T37", kw: ["偏相関係数","疑似相関","相関係数"], type: "calc",
  stem: "多数の火災について、出動した消防車の台数 x、火災の損害額 y、火災の規模 z を調べたところ、相関係数は r<sub>xy</sub> = 0.6、r<sub>xz</sub> = 0.8、r<sub>yz</sub> = 0.75 であった。z の影響を取り除いた x と y の偏相関係数 r<sub>xy·z</sub> = (r<sub>xy</sub> − r<sub>xz</sub>r<sub>yz</sub>) / √{(1 − r<sub>xz</sub><sup>2</sup>)(1 − r<sub>yz</sub><sup>2</sup>)} の値と、その解釈の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["0.60。z の影響を取り除いても、x と y の相関の強さは変わらない", "1.51。z の影響を取り除くと、x と y の間により強い正の相関が残る", "0。x と y の相関は、z を通じて生じた見かけの相関（疑似相関）である可能性がある", "0.36。z の影響を取り除くと相関は弱まるが、x と y の間にはなお正の相関が残る"],
  ans: 2,
  exp: "分子は 0.6 − 0.8 × 0.75 = 0.6 − 0.6 = 0 なので、偏相関係数は 0 になる。消防車の台数と損害額の正の相関は、どちらも火災の規模が大きいほど増えることで説明でき、規模をそろえると直線的な関係は残らない。このように、第3の変数を通じて生じる見かけの相関を疑似相関という。偏相関係数は、他の変数の影響を取り除いたうえでの関係を調べるために使う。",
  why: ["r<sub>xy</sub> の値をそのまま答えたものである。分子から r<sub>xz</sub>r<sub>yz</sub> を引く必要がある。", "分子で r<sub>xz</sub>r<sub>yz</sub> を引かずに計算した値（0.6 ÷ 約 0.397）である。偏相関係数も −1 以上 1 以下の値をとるので、1 を超える値は計算の誤りを示す。", "正しい。分子が 0 になり、偏相関係数は 0 である。", "r<sub>xy</sub> を2乗した値（0.6² = 0.36）であり、偏相関係数ではない。式どおりに計算すると分子は 0 になる。"],
  src: [{ t: "STAT 505 Applied Multivariate Statistical Analysis, Lesson 6: Multivariate Conditional Distribution and Partial Correlation（Penn State）", u: "https://online.stat.psu.edu/stat505/Lesson06" }, { t: "Simon, H. A. (1954). Spurious Correlation: A Causal Interpretation", u: "https://doi.org/10.1080/01621459.1954.10483515" }] },
{ id: "M-115", set: "mock", sec: "T37", kw: ["マハラノビス距離","ユークリッド距離","外れ値"], type: "calc",
  stem: "2つの変数 x<sub>1</sub>, x<sub>2</sub> の分布は、平均が (0, 0)、x<sub>1</sub> の分散が 9、x<sub>2</sub> の分散が 1、共分散が 0 である。点 P(3, 0) と点 Q(0, 2) について、分布の平均からのユークリッド距離とマハラノビス距離を求め、外れ値の候補としてどちらがより外れているかを判断した。組み合わせとして正しいものを1つ選べ。",
  choices: ["ユークリッド距離は P が 3、Q が 2。マハラノビス距離は P が 1、Q が 2。分布の広がりを考えると Q の方がより外れている", "ユークリッド距離は P が 3、Q が 2。マハラノビス距離も P が 3、Q が 2。どちらの距離でみても P の方がより外れている", "ユークリッド距離は P が 3、Q が 2。マハラノビス距離は P が 0.33、Q が 2。分布の広がりを考えると Q の方がより外れている", "ユークリッド距離は P が 9、Q が 4。マハラノビス距離は P が 1、Q が 4。分布の広がりを考えると Q の方がより外れている"],
  ans: 0,
  exp: "マハラノビス距離は √{(x − μ)ᵀ Σ⁻¹ (x − μ)} で、共分散が 0 のときは、各成分の差を標準偏差で割ってからユークリッド距離をとったものになる。P は x<sub>1</sub> 方向に 3 離れているが、x<sub>1</sub> の標準偏差が 3 なので 1 標準偏差分にすぎない。Q は x<sub>2</sub> 方向に 2 離れ、標準偏差 1 の 2 倍にあたる。ユークリッド距離では P の方が遠いが、データの散らばりを考えると Q の方がまれな点である。",
  why: ["正しい。P のマハラノビス距離は √(3²/9) = 1、Q は √(2²/1) = 2 である。", "マハラノビス距離を分散で調整していない値であり、これはユークリッド距離と同じになってしまう。共分散行列が単位行列のときだけ両者は一致する。", "差を標準偏差（3）ではなく分散（9）で割った誤りである。正しくは 3 ÷ 3 = 1 である。", "距離の2乗の値である。ユークリッド距離は √9 = 3 と √4 = 2、マハラノビス距離は 1 と 2 である。"],
  src: [{ t: "STAT 505 Applied Multivariate Statistical Analysis, Lesson 4: Multivariate Normal Distribution（Penn State）", u: "https://online.stat.psu.edu/stat505/Lesson04" }, { t: "Reprint of: Mahalanobis, P.C. (1936) 「On the Generalised Distance in Statistics.」（Sankhya A, 2018）", u: "https://doi.org/10.1007/s13171-019-00164-5" }] },
{ id: "M-116", set: "mock", sec: "T37", kw: ["最尤法","ポアソン分布"], type: "calc",
  stem: "あるコールセンターで、1時間ごとの問い合わせ件数を6時間記録したところ、3, 0, 2, 5, 1, 1 件であった。件数が互いに独立に、平均 λ のポアソン分布に従うと仮定するとき、λ の最尤推定値として正しいものを1つ選べ。",
  choices: ["1.5", "2.67", "12", "2"],
  ans: 3,
  exp: "ポアソン分布の尤度は L(λ) = Π e<sup>−λ</sup>λ<sup>x<sub>i</sub></sup> / x<sub>i</sub>! で、対数尤度 −nλ + (Σx<sub>i</sub>) log λ − Σ log x<sub>i</sub>! を λ で微分して 0 とおくと、λ = Σx<sub>i</sub> / n（標本平均）が得られる。ここでは 12 ÷ 6 = 2 となる。最尤法は、観測されたデータが得られる確率（尤度）を最大にするパラメータを推定値とする方法である。",
  why: ["データを小さい順に並べた 0, 1, 1, 2, 3, 5 の中央値である。ポアソン分布の λ の最尤推定値は中央値ではない。", "データの分散（n で割った値）である。ポアソン分布では期待値と分散が等しいが、最尤推定値は標本平均になる。", "6時間分の件数の合計である。1時間あたりの平均にするには 6 で割る。", "正しい。最尤推定値は標本平均 12 ÷ 6 = 2 である。"],
  src: [{ t: "STAT 415 Introduction to Mathematical Statistics, Lesson 4: Maximum Likelihood Estimation (MLE) (Part I)（Penn State）", u: "https://online.stat.psu.edu/stat415/Lesson04.html" }, { t: "Fisher, R. A. (1922). On the mathematical foundations of theoretical statistics", u: "https://doi.org/10.1098/rsta.1922.0009" }] },
{ id: "M-117", set: "mock", sec: "T37", kw: ["帰無仮説","対立仮説"], type: "best",
  stem: "新しいウェブページのデザインで購入率が変わるかを調べるため、帰無仮説「購入率は変わらない」、対立仮説「購入率は変わる」として、有意水準 5% で検定を行ったところ、p 値は 0.03 であった。この結果の解釈として、最も適切なものを1つ選べ。",
  choices: ["帰無仮説が正しい確率が 3% であることが示された", "帰無仮説が正しいと仮定したとき、観測されたのと同じかそれより極端な結果が得られる確率が 3% であり、有意水準 5% を下回るので帰無仮説を棄却する", "p 値が小さいので、新しいデザインによる購入率の変化は、ビジネス上も大きな効果であることが示された", "対立仮説が正しい確率が 97% であることが示された"],
  ans: 1,
  exp: "p 値は、帰無仮説（と統計モデル）が正しいと仮定したとき、データから計算した統計量が観測された値と同じかそれより極端になる確率である。p 値が有意水準より小さければ帰無仮説を棄却し、対立仮説を採択する。米国統計学会（ASA）の声明は、p 値は仮説が正しい確率を表すものではなく、効果の大きさや結果の重要性も表さない、と注意している。",
  why: ["p 値は帰無仮説が正しいと仮定したうえで計算する確率であり、帰無仮説が正しい確率そのものではない。", "正しい。p 値 0.03 は有意水準 0.05 より小さいので、帰無仮説を棄却する。", "p 値は効果の大きさを表さない。データが多いと、実用上は小さな差でも p 値は小さくなる。効果の大きさは別に評価する必要がある。", "p 値から対立仮説が正しい確率は求まらない。1 − p 値をそのような確率と解釈するのは誤りである。"],
  src: [{ t: "Wasserstein, R. L. & Lazar, N. A. (2016). The ASA Statement on p-Values: Context, Process, and Purpose", u: "https://doi.org/10.1080/00031305.2016.1154108" }, { t: "総務省統計局 なるほど統計学園「統計的推定と統計的仮説検定」", u: "https://www.stat.go.jp/naruhodo/11_tokusei/kentei.html" }] },
{ id: "M-118", set: "mock", sec: "T37", kw: ["条件付き確率","移動平均","度数分布","共分散"], type: "worst",
  stem: "データの集計や確率に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["移動平均をとる期間（項数）を長くするほど、細かな変動がならされ、より滑らかな曲線になる", "度数分布表は、データの範囲をいくつかの階級に分けて各階級に入るデータの個数（度数）を数えたもので、これを柱で表したものがヒストグラムである", "条件付き確率 P(A|B) と P(B|A) は、どちらも A と B が同時に起こる確率から求めるので、常に等しい", "共分散の値は2つの変数の単位に左右されるため、関係の強さを比べるには、単位によらない相関係数を使う"],
  ans: 2,
  exp: "P(A|B) = P(A∩B) / P(B)、P(B|A) = P(A∩B) / P(A) であり、分母が異なる。両者が等しくなるのは P(A) = P(B) のときなどに限られる。例えば、病気の人が検査で陽性になる確率 P(陽性|病気) が 90% でも、陽性の人が実際に病気である確率 P(病気|陽性) は、病気の人の割合が小さければずっと低くなる。両者を取り違える誤りはよく起こる。",
  why: ["適切。移動平均の項数が大きいほど、得られる曲線は滑らかになる（Hyndman と Athanasopoulos の教科書）。", "適切。ヒストグラムは、データの範囲を等しい幅の階級に分け、各階級の度数を縦軸にとって表したものである（NIST の統計ハンドブック）。", "不適切（これが正解）。分母が P(B) と P(A) で異なるので、一般には等しくない。", "適切。共分散は両方の変数の単位を反映するため、単位のない尺度である相関係数（共分散を両者の標準偏差の積で割ったもの）が使われる。"],
  src: [{ t: "STAT 414 Introduction to Probability Theory, Lesson 4: Conditional Probability（Penn State）", u: "https://online.stat.psu.edu/stat414/Lesson04.html" }, { t: "Hyndman & Athanasopoulos. Forecasting: Principles and Practice (3rd ed.), 3.3 Moving averages", u: "https://otexts.com/fpp3/moving-averages.html" }, { t: "NIST/SEMATECH e-Handbook of Statistical Methods, 1.3.3.14 Histogram", u: "https://www.itl.nist.gov/div898/handbook/eda/section3/histogra.htm" }, { t: "STAT 414 Introduction to Probability Theory, Lesson 18: The Correlation Coefficient（Penn State）", u: "https://online.stat.psu.edu/stat414/Lesson18.html" }] },
/* ── L01 個人情報保護法 ── */
{ id: "M-119", set: "mock", sec: "L01", kw: ["第三者提供","個人データ"], type: "best",
  stem: "ウェブサイトを運営する A 社は、Cookie を使って集めた閲覧履歴（A 社の手元では特定の個人を識別できない個人関連情報で、データベースとして整理されている）を、広告事業者の B 社に提供しようとしている。B 社は、受け取った閲覧履歴を ID で自社の会員の個人データに紐付けて使う予定であることを、A 社に伝えている。個人情報保護法に照らした説明として、最も適切なものを1つ選べ。",
  choices: ["A 社は、B 社が閲覧履歴を個人データとして取得することを認める本人の同意が得られていることを、提供の前に確認しなければならない。この同意は原則として B 社が取得するが、A 社が代わって取得することも認められている", "閲覧履歴は A 社の手元では個人情報に当たらないので、提供先で個人データになるとしても、A 社は何も確認せずに提供できる", "A 社に確認の義務が生じるのは、B 社が外国にある場合に限られる", "本人の同意は A 社が自ら取得しなければならず、B 社が取得した同意を A 社が確認する方法は認められていない"],
  ans: 0,
  exp: "個人関連情報とは、生存する個人に関する情報で、個人情報・仮名加工情報・匿名加工情報のいずれにも当たらないもの（Cookie で集めた閲覧履歴など）をいう。提供先がそれを個人データとして取得することが想定されるときは、提供元は、本人の同意が得られていることなどをあらかじめ確認しなければ提供できない（法31条）。委員会のガイドラインは、同意を取得する主体は原則として本人と接点を持つ提供先であり、提供元が代行することも認められるとしている。提供元は、確認したことなどの記録も作成する。",
  why: ["正しい。提供先で個人データとして取得されることが想定されるため、法31条1項による同意の確認が必要になる。", "提供元の手元で個人情報に当たらなくても、提供先で個人データとして取得されることが想定されるときは、確認の義務がある。", "外国にある第三者への提供では、外国の制度などの情報が本人に提供されていることも確認する必要があるが、同意の確認は国内の提供先でも必要である。", "ガイドラインは、同意の取得は原則として提供先が行うとしており、提供先からの申告を受ける方法などで確認できる。"],
  src: [{ t: "個人情報の保護に関する法律（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/415AC0000000057" }, { t: "個人情報保護委員会「個人情報の保護に関する法律についてのガイドライン（通則編）」", u: "https://www.ppc.go.jp/personalinfo/legal/guidelines_tsusoku/" }] },
{ id: "M-120", set: "mock", sec: "L01", kw: ["要配慮個人情報","個人データ"], type: "best",
  stem: "個人情報取扱事業者に次の事態が起きた。個人情報保護法に基づき、個人情報保護委員会への報告が義務づけられるものとして、最も適切なものを1つ選べ。",
  choices: ["取引先の担当者 800 人分の氏名とメールアドレス（個人データ）を、担当者の操作ミスで別の取引先1社にメールで送ってしまった。不正の目的によるものではなく、財産的な被害が生じるおそれもない", "社員 50 人分の健康診断の結果を含むファイル（個人データ）を保存したノートパソコンを紛失した。ファイルは安全性の高い方式で暗号化されており、復号するための鍵は漏えいしていない", "顧客1人分の病歴を含む相談記録（個人データ）を、誤って無関係の第三者にメールで送ってしまった", "来店客の人数を年代別に集計した表（特定の個人を識別できない統計情報）を、誤って社外に送ってしまった"],
  ans: 2,
  exp: "法26条により、個人の権利利益を害するおそれが大きい漏えい等が起きたときは、委員会への報告と本人への通知が義務づけられる。対象は施行規則7条が定める4つの場合である。(1) 要配慮個人情報を含む個人データ、(2) 不正に使われると財産的被害が生じるおそれがある個人データ、(3) 不正の目的によるおそれがある行為による漏えい等、(4) 本人の数が 1,000 人を超える漏えい等。いずれも、高度な暗号化などの措置を講じた個人データは除かれる。報告は、知った後速やかに行い（速報）、30日以内（(3) の場合は60日以内）に詳しい内容を報告する（確報）。",
  why: ["人数は 1,000 人以下で、要配慮個人情報も含まず、不正の目的や財産的被害のおそれもないので、報告が義務づけられる4つの場合のいずれにも当たらない。", "健康診断の結果は要配慮個人情報だが、高度な暗号化などの措置を講じた個人データは報告の対象から除かれる。", "正しい。病歴は要配慮個人情報であり、それを含む個人データの漏えいは、1人分でも報告の対象となる。", "特定の個人を識別できない統計情報は個人情報ではなく、個人データの漏えいに当たらない。"],
  src: [{ t: "個人情報の保護に関する法律（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/415AC0000000057" }, { t: "個人情報の保護に関する法律施行規則（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/428M60020000003" }, { t: "個人情報保護委員会「個人情報の保護に関する法律についてのガイドライン（通則編）」", u: "https://www.ppc.go.jp/personalinfo/legal/guidelines_tsusoku/" }] },
{ id: "M-121", set: "mock", sec: "L01", kw: ["GDPR"], type: "worst",
  stem: "EU の一般データ保護規則（GDPR）に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["IP アドレスや Cookie 識別子などのオンライン識別子によって識別されうる自然人の情報も、個人データになりうる", "匿名化されて、データ主体を識別できなくなった情報には、データ保護の原則は適用されない", "一部の重大な違反に対する制裁金の上限は、2,000 万ユーロと、事業者の場合は前年度の全世界の売上高の 4% のうち、いずれか高い方である", "GDPR が保護するのは EU 加盟国の国籍を持つ人の個人データに限られ、EU 域内に住んでいても加盟国の国籍を持たない人の個人データは対象外である"],
  ans: 3,
  exp: "GDPR の前文14項は、保護はその国籍や居住地にかかわらず、自然人の個人データの取扱いについて適用されるとしている。また3条2項により、EU 域内に拠点がない事業者でも、EU 域内にいるデータ主体に商品・サービスを提供したり、その行動を監視したりする場合は適用されうる。適用の判断で問われるのは国籍ではなく、拠点の場所やデータ主体が EU 域内にいるかどうかである。",
  why: ["適切。4条1号は識別子の例としてオンライン識別子を挙げ、前文30項は IP アドレスや Cookie 識別子に触れている。", "適切。前文26項は、匿名化されてデータ主体を識別できなくなった情報には、データ保護の原則は適用されないとしている。", "適切。83条5項・6項の違反の上限である。それ以外の一部の違反（83条4項）の上限は 1,000 万ユーロまたは 2% である。", "不適切（これが正解）。保護は国籍や居住地にかかわらず自然人に及ぶ。"],
  src: [{ t: "個人情報保護委員会「一般データ保護規則（GDPR）の条文」（仮日本語訳）", u: "https://www.ppc.go.jp/files/pdf/gdpr-provisions-ja.pdf" }, { t: "個人情報保護委員会「一般データ保護規則（GDPR）の前文」（仮日本語訳）", u: "https://www.ppc.go.jp/files/pdf/gdpr-preface-ja.pdf" }] },
/* ── L02 著作権法 ── */
{ id: "M-122", set: "mock", sec: "L02", kw: ["著作権侵害","著作権"], type: "best",
  stem: "ある企業が、ニュース記事を集めたデータベースを検索し、その結果をもとに生成 AI が質問に回答する RAG（検索拡張生成）のサービスを作ろうとしている。文化審議会著作権分科会法制度小委員会「AIと著作権に関する考え方について」に照らした説明として、最も適切なものを1つ選べ。",
  choices: ["記事をベクトルに変換したデータベースを作れば、元の記事は数値になるので、著作権法上の問題は一切生じない", "回答の生成の際に記事の創作的表現の全部または一部を出力することを目的としてデータベースを作る場合、その複製には30条の4は適用されないと考えられる。47条の5の「軽微利用」の程度を超えて記事を利用するなら、原則として権利者の許諾が必要になる", "データベースに含まれる記事が著作物であっても、出力の目的にかかわらず、30条の4によって常に許諾なく利用できる", "47条の5は、既存の著作物の創作的表現を提供することを主な目的とする場合でも、分量の制限なく利用を認めている"],
  ans: 1,
  exp: "「考え方」は、RAG のためのデータベースの作成に伴う複製について、回答の生成の際に元の著作物の創作的表現を出力することを目的としないなら30条の4が適用されうるが、出力を目的とするなら非享受目的とはいえず30条の4は適用されないとする。その場合でも、回答の生成に47条の5第1項（電子計算機による情報処理及びその結果の提供に付随する軽微利用等）が適用されることがある。ただし、軽微利用を超える場合や、創作的表現の提供が主な目的の場合は対象外で、原則として許諾が必要になる。",
  why: ["ベクトルに変換したデータベースの作成にも、著作物の複製が伴いうる。「考え方」は、その複製に権利制限規定が適用されるかを目的に応じて検討している。", "正しい。出力を目的とする複製には30条の4が適用されず、47条の5の軽微利用を超えれば原則として許諾が必要とされている。", "30条の4は、著作物に表現された思想・感情の享受を目的としない利用に限られる。創作的表現を出力する目的があれば適用されない。", "47条の5による利用は軽微なものに限られ、検索などの処理に「付随して」行われる必要がある。創作的表現の提供を主な目的とする場合は対象外とされている。"],
  src: [{ t: "文化審議会著作権分科会法制度小委員会「AIと著作権に関する考え方について」（2024年3月15日）", u: "https://www.bunka.go.jp/seisaku/bunkashingikai/chosakuken/pdf/94037901_01.pdf" }, { t: "著作権法（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/345AC0000000048" }] },
{ id: "M-123", set: "mock", sec: "L02", kw: ["AI 生成物","著作権侵害"], type: "worst",
  stem: "生成 AI の生成・利用の段階で既存の著作物を利用する場面について、「AIと著作権に関する考え方について」に照らした説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["個人が私的に楽しむために、既存のキャラクターに似た画像を生成することは、私的使用目的の複製（30条1項）として、許諾なく行える場合がある", "企業の内部で、生成物が既存の著作物に類似していないかを検討する過程での利用には、検討の過程における利用（30条の3）の適用が考えられる", "生成物による著作権侵害が認められても、利用者に故意や過失がなければ損害賠償請求は認められないが、差止請求は故意・過失の有無を問わず受けうる", "生成の段階で私的使用目的の複製に当たれば、その画像を後から SNS で公開する行為にも同じ規定が及ぶので、許諾は不要である"],
  ans: 3,
  exp: "「考え方」は、生成・利用段階では、生成の行為と、生成物を利用する行為のそれぞれについて権利制限規定が適用されるかを検討する必要があるとしている。一方の行為に権利制限規定が適用されても、他方は適用の範囲外となり、許諾が必要になる場合がある。私的に楽しむための生成は私的使用目的の複製に当たりうるが、SNS での公開（公衆送信）は私的使用の範囲を超える。",
  why: ["適切。「考え方」は、生成・利用段階で適用されうる権利制限規定として、私的使用目的の複製（30条1項）を挙げている。", "適切。企業・団体の内部で、生成物が既存の著作物と類似していないかを検討する過程での利用には、30条の3の適用が考えられるとしている。", "適切。差止請求は故意・過失の有無を問わず可能であり、損害賠償請求には故意または過失が必要とされている。", "不適切（これが正解）。生成と利用の行為は別々に検討され、私的使用目的の複製に当たっても、SNS での公開まで許されるわけではない。"],
  src: [{ t: "文化審議会著作権分科会法制度小委員会「AIと著作権に関する考え方について」（2024年3月15日）", u: "https://www.bunka.go.jp/seisaku/bunkashingikai/chosakuken/pdf/94037901_01.pdf" }, { t: "著作権法（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/345AC0000000048" }] },
/* ── L03 特許法 ── */
{ id: "M-124", set: "mock", sec: "L03", kw: ["特許権","発明"], type: "worst",
  stem: "AI 関連の発明と特許制度に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["特許出願は、特許掲載公報の発行をしたものを除き、出願の日から1年6か月を経過すると出願公開され、内容が公開される", "同じ発明について異なる日に2つ以上の特許出願があったときは、最も先に出願した者だけが特許を受けることができる", "特許を受ける権利は発明をした本人だけのものであり、他人に移転することはできない", "特許権の効力は、試験または研究のためにする特許発明の実施には及ばない"],
  ans: 2,
  exp: "特許法33条1項は「特許を受ける権利は、移転することができる」と定めている。発明者から会社などに特許を受ける権利を移し、会社が出願することは一般に行われている。また職務発明では、勤務規則などで定めれば、特許を受ける権利は発生したときから会社に帰属する（35条3項）。なお、特許を受ける権利を質権の目的とすることはできない（33条2項）。",
  why: ["適切。出願公開を定めた64条1項の内容である。", "適切。先願主義を定めた39条1項の内容である。同じ日の出願は協議で1人を定める（39条2項）。", "不適切（これが正解）。33条1項により、特許を受ける権利は移転できる。", "適切。69条1項は、特許権の効力は試験または研究のためにする特許発明の実施には及ばないと定めている。"],
  src: [{ t: "特許法（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/334AC0000000121" }] },
{ id: "M-125", set: "mock", sec: "L03", kw: ["職務発明"], type: "best",
  stem: "AI 企業の X 社は、勤務規則で、職務発明について特許を受ける権利を X 社が取得すると定めている。X 社は、発明をした従業者に与える「相当の利益」の基準を作ろうとしている。特許法に照らした説明として、最も適切なものを1つ選べ。",
  choices: ["相当の利益は会社が一方的に決めればよく、基準を作る際の従業者との協議の状況や、基準の開示の状況は、その定めが不合理かどうかの判断に関係しない", "相当の利益の定めがない場合や、定めたところによる利益の付与が不合理と認められる場合は、会社がその発明により受けるべき利益の額、会社の負担・貢献、従業者の処遇などの事情を考慮して、相当の利益の内容が定められる", "勤務規則に相当の利益の定めを置かなければ、従業者は相当の利益を受ける権利を失う", "経済産業大臣が定める指針は、会社が従業者に与える相当の利益の金額を一律に定めたものであり、会社はその金額に従わなければならない"],
  ans: 1,
  exp: "職務発明の特許を受ける権利を会社に取得させた従業者は、相当の金銭その他の経済上の利益（相当の利益）を受ける権利を持つ（35条4項）。勤務規則などで相当の利益を定める場合、基準を作る際の協議の状況、基準の開示の状況、従業者からの意見の聴取の状況などを考慮して、不合理と認められるものであってはならない（35条5項）。定めがない場合や不合理な場合は、35条7項の事情を考慮して定められる。",
  why: ["35条5項は、協議・開示・意見の聴取の状況などを考慮して、定めが不合理であってはならないとしている。手続の状況は判断の重要な要素である。", "正しい。35条7項の内容である。", "定めがない場合でも、従業者は相当の利益を受ける権利を持ち、その内容は35条7項に従って定められる。", "35条6項の指針は、5項で考慮すべき状況など（協議・開示・意見の聴取の進め方など）に関する事項を示すものであり、金額を一律に定めるものではない。"],
  src: [{ t: "特許法（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/334AC0000000121" }] },
/* ── L04 不正競争防止法 ── */
{ id: "M-126", set: "mock", sec: "L04", kw: ["限定提供データ","営業秘密"], type: "best",
  stem: "2023年（令和5年）の不正競争防止法の改正で変わった限定提供データの定義に関する説明として、最も適切なものを1つ選べ。",
  choices: ["限定提供データから除かれるものが「秘密として管理されているもの」から「営業秘密」に改められた。そのため、秘密として管理されていても営業秘密の要件を満たさないデータは、ほかの要件を満たせば限定提供データとして保護されうる", "改正により、限定提供データの不正取得などの行為にも、営業秘密と同じく刑事罰が科されるようになった", "改正後は、1つの情報が営業秘密と限定提供データの両方として、同時に重ねて保護されるようになった", "改正により相当蓄積性の要件がなくなり、少量のデータでも限定提供データとして保護されるようになった"],
  ans: 0,
  exp: "限定提供データは、業として特定の者に提供する情報として、電磁的方法により相当量蓄積され、管理されている技術上または営業上の情報をいう（2条7項）。2018年の制度の創設時は「秘密として管理されているもの」を除いていたが、2023年の改正（2024年4月1日施行）で「営業秘密を除く」に改められた。経済産業省の指針は、これを両制度の重なりを避けつつ、保護の対象を広げる措置と説明している。",
  why: ["正しい。除外の範囲が営業秘密に限られたため、秘密として管理されているが営業秘密に当たらないデータも保護の対象になりうる。", "限定提供データの不正取得などは、民事上の措置（差止請求・損害賠償請求）の対象だが、刑事罰の対象とはなっていない。", "「営業秘密を除く」とした趣旨は、両制度の保護が重ねて及ばないようにすることにある。", "改正後の2条7項も「相当量蓄積され」と定めており、相当蓄積性は引き続き要件である。"],
  src: [{ t: "不正競争防止法（e-Gov 法令検索）", u: "https://laws.e-gov.go.jp/law/405AC0000000047" }, { t: "経済産業省「限定提供データに関する指針」（最終改訂：令和6年2月）", u: "https://www.meti.go.jp/policy/economy/chizai/chiteki/guideline/h31pd.pdf" }] },
/* ── L05 独占禁止法 ── */
{ id: "M-127", set: "mock", sec: "L05", kw: ["競争制限"], type: "best",
  stem: "公正取引委員会の研究会の報告書「アルゴリズム/AIと競争政策」（2021年）は、アルゴリズムによる協調的行為を4つの類型に分けて検討している。事例と類型の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["価格カルテルの参加者が、互いの価格を自動で調べ、合意から外れた事業者にはすぐに値下げで対抗するツールを使う ― 自己学習アルゴリズムによる協調的行為", "競合する複数のネット通販事業者が、同じベンダーの価格設定アルゴリズムを使い、そのベンダーを中心にして互いの価格がそろう ― アルゴリズムの並行利用による協調的行為（ハブアンドスポーク型）", "顧客がほとんど見ていない深夜に、ごく短い時間だけ値上げを示し、競合他社の反応を確かめる ― 監視型アルゴリズムを利用した協調的行為", "各社が独自に機械学習による価格設定を使い、互いに意思の連絡がないまま、競争的な水準を上回る価格に至る ― シグナリングアルゴリズムを利用した協調的行為"],
  ans: 1,
  exp: "報告書は OECD（2017）の分類に従い、(1) 監視型アルゴリズムを利用した協調的行為、(2) アルゴリズムの並行利用による協調的行為、(3) シグナリングアルゴリズムを利用した協調的行為、(4) 自己学習アルゴリズムによる協調的行為に分けている。同じ第三者のアルゴリズムを複数の競争事業者が使って価格がそろう場合は、第三者を中心（ハブ）とするハブアンドスポーク型と整理される。この型では、利用事業者どうしが情報交換をしない場合や、価格をそろえる仕組みを知らない場合でも価格が同調しうる点に特徴がある。",
  why: ["合意の実効性を確保するため、価格を監視して逸脱に報復するのは、監視型アルゴリズムを利用した協調的行為である。", "正しい。同じベンダーのアルゴリズムを中心に価格が同調するハブアンドスポーク型である。", "顧客に気づかれにくい形で値上げの意図を示し、競合の反応を確かめるのは、シグナリングアルゴリズムを利用した協調的行為である。", "各社の自己学習アルゴリズムの相互作用によって、意思がなくても競争的な水準を上回る価格に至るのは、自己学習アルゴリズムによる協調的行為である。"],
  src: [{ t: "公正取引委員会「デジタル市場における競争政策に関する研究会 報告書『アルゴリズム/AIと競争政策』について」（2021年3月31日）", u: "https://www.jftc.go.jp/houdou/pressrelease/2021/mar/210331_digital.html" }, { t: "公正取引委員会 デジタル市場における競争政策に関する研究会「報告書 アルゴリズム/AIと競争政策」（2021年3月31日）", u: "https://www.jftc.go.jp/houdou/pressrelease/2021/mar/210331_digital/210331digital_hokokusho.pdf" }] },
/* ── L06 AI開発委託契約 ── */
{ id: "M-128", set: "mock", sec: "L06", kw: ["PoC","準委任契約","AI・データの利用に関する契約ガイドライン"], type: "best",
  stem: "経済産業省「AI・データの利用に関する契約ガイドライン」（AI編）が示す、探索的段階型の開発の各段階と、用意されたモデル契約の前提の組み合わせとして、最も適切なものを1つ選べ。",
  choices: ["アセスメント段階 ― ソフトウェア開発契約書。請負型の契約で、ベンダが学習済みモデルの完成を約束する", "PoC 段階 ― 導入検証契約書。準委任型の契約を前提とし、サンプルデータで学習済みモデルの生成や精度向上の作業を行って開発の可否や妥当性を検証し、その結果をレポートにまとめる", "開発段階 ― ソフトウェア開発契約書。ウォーターフォールモデルと請負型の契約を前提とする", "追加学習段階 ― 専用のモデル契約書が用意されており、開発段階とはまったく異なる権利関係を定めることを前提としている"],
  ans: 1,
  exp: "ガイドラインのモデル契約は、アセスメント段階に秘密保持契約書、PoC 段階に導入検証契約書、開発段階にソフトウェア開発契約書を用意している。導入検証契約書は準委任型で、PoC の初期段階に、サンプルデータで開発の可否や妥当性を検証し、レポートを作ることを前提とする。ソフトウェア開発契約書は、非ウォーターフォールモデルで、準委任型（成果完成型・履行割合型のいずれも含む）を前提とする。",
  why: ["アセスメント段階のモデル契約は秘密保持契約書であり、限られたサンプルデータで短期間に導入の可否を検討することを前提としている。", "正しい。導入検証契約書のモデル契約の前提である。", "開発段階のモデル契約は、非ウォーターフォールモデルで、準委任型を前提としている。", "追加学習段階は、開発段階の契約の権利関係・責任関係の条項とほぼ同じ内容になると考えられるため、モデル契約は作成されていない。"],
  src: [{ t: "経済産業省「AI・データの利用に関する契約ガイドライン 1.1版」（AI編を含む全体版）", u: "https://www.meti.go.jp/policy/mono_info_service/connected_industries/sharing_and_utilization/20200619001.pdf" }] },
{ id: "M-129", set: "mock", sec: "L06", kw: ["AI・データの利用に関する契約ガイドライン"], type: "blank",
  stem: "経済産業省「AI・データの利用に関する契約ガイドライン」（AI編）は、「学習済みモデル」とは「学習済みパラメータ」が組み込まれた「（　）」をいう、としている。そのうえで、実務では「学習済みモデル」という言葉が多義的に使われるため、その範囲を契約で明確に定めておくことが望ましいとしている。（　）に入る語句として、最も適切なものを1つ選べ。",
  choices: ["推論プログラム", "学習用プログラム", "学習用データセット", "生データ"],
  ans: 0,
  exp: "学習済みパラメータは、学習用データセットを学習用プログラムに入力して得られる係数であり、単体では数値にすぎない。これを推論プログラムに組み込むことで、初めて学習済みモデルとして機能する。実務では、生データ・学習用データセット・学習用プログラムなどまで含めて「学習済みモデル」と呼ぶことがあり、確立した定義がないため、権利帰属や利用条件を決める前提として範囲を明確にしておくことが重要になる。",
  why: ["正しい。学習済みモデルは、学習済みパラメータが組み込まれた推論プログラムと定義されている。", "学習用プログラムは、学習用データセットから規則を見出し、モデルを生成するアルゴリズムを実行するプログラムである。学習済みパラメータを作る側のプログラムにあたる。", "学習用データセットは、生データに前処理やラベル付けなどを行って、学習に使える形にしたデータである。", "生データは、センサやカメラなどで収集・蓄積されたデータで、欠測値や外れ値を含むなど、多くはそのままでは学習に適さない。学習用データセットを作る元になるものである。"],
  src: [{ t: "経済産業省「AI・データの利用に関する契約ガイドライン 1.1版」（AI編を含む全体版）", u: "https://www.meti.go.jp/policy/mono_info_service/connected_industries/sharing_and_utilization/20200619001.pdf" }] },
/* ── L07 AIサービス提供契約 ── */
{ id: "M-130", set: "mock", sec: "L07", kw: ["データ利用権"], type: "best",
  stem: "空調機器メーカーの X 社は、ビル管理会社の Y 社に納めた空調機器にセンサーを付けて稼働データを集め、故障予知の AI サービスを提供している。稼働データは、X 社の機器と Y 社によるビルの運用の双方が関わって新たに生まれるものである。経済産業省「AI・データの利用に関する契約ガイドライン」（データ編）の整理として、最も適切なものを1つ選べ。",
  choices: ["データ提供型にあたる。データはもともと X 社だけが保持しているので、利用条件は X 社が一方的に決めればよい", "データ共用型（プラットフォーム型）にあたる。複数の事業者がプラットフォームにデータを提供して共用する場面である", "データ創出型にあたる。複数の当事者が関与して新たに生まれるデータであり、データの創出への寄与などを考慮して、利用権限を当事者間の契約で取り決める", "データは機器の所有者である Y 社の所有物となるので、所有権に基づいて Y 社だけが利用権限を持つ"],
  ans: 2,
  exp: "データ編は、データ契約を、データ提供型（一方の当事者だけが保持するデータを提供する）、データ創出型（複数の当事者が関与して新たにデータが生まれる）、データ共用型（プラットフォームを通じて複数の事業者がデータを共用する）の3つに整理している。また、データは無体物で所有権の対象ではなく、利用権限は契約で当事者間で定めるものだとして、データの創出や利活用への寄与度などを考慮して柔軟に取り決めることを勧めている。",
  why: ["この稼働データは、複数の当事者が関与して新たに生まれるもので、一方の当事者だけが保持しているデータではない。", "この事例は2社の間の取引であり、プラットフォームを通じて多数の事業者がデータを共用する場面ではない。", "正しい。複数の当事者が関与して新たに生まれるデータの利用権限を取り決めるのが、データ創出型の契約である。", "データは無体物であり、所有権の対象ではない。利用権限は契約で定める。"],
  src: [{ t: "経済産業省「AI・データの利用に関する契約ガイドライン 1.1版」（AI編を含む全体版）", u: "https://www.meti.go.jp/policy/mono_info_service/connected_industries/sharing_and_utilization/20200619001.pdf" }] },
/* ── L08 国内外のガイドライン ── */
{ id: "M-131", set: "mock", sec: "L08", kw: ["AI ガバナンス"], type: "best",
  stem: "AI事業者ガイドライン（第1.2版）が、AI ガバナンスの構築について実践が重要だとしている「アジャイル・ガバナンス」の説明として、最も適切なものを1つ選べ。",
  choices: ["社会の変化に左右されないよう、ルールや手続を事前に固定し、一度設定した AI ガバナンス・ゴールは運用を始めた後も見直さない", "AI ガバナンスは技術部門が担うものであり、経営層は関与せず、短期的な利益を損なわないよう、かける費用を最小限に抑える", "AI のもたらすリスクの程度や各主体の資源の制約にかかわらず、すべての AI システムに同じ水準の対策を一律に行う", "「環境・リスク分析」「ゴール設定」「システムデザイン」「運用」「評価」のサイクルを、マルチステークホルダーで継続的かつ高速に回し、外部環境の変化に応じてゴールも見直す"],
  ans: 3,
  exp: "ガイドラインは、社会が複雑で変化が速く、AI ガバナンスが目指すゴールも常に変わるため、事前にルールや手続を固定したガバナンスではなく、アジャイル・ガバナンスの実践が重要だとしている。運用開始後も、規制の変更などの外部環境の変化を踏まえて環境・リスク分析をやり直し、必要に応じてゴールを見直す。また、経営層のリーダーシップのもとで、AI ガバナンスを単なるコストではなく、中長期的な発展のための先行投資ととらえることが重要だとしている。",
  why: ["ガイドラインは、事前にルールや手続が固定されたガバナンスではなく、サイクルを回して変化に対応するガバナンスを求めている。", "ガイドラインは経営層の責任は大きいとし、AI ガバナンスの構築を単なるコストではなく先行投資ととらえることを求めている。", "ガイドラインは、検討にあたっては AI のもたらすリスクの程度と蓋然性、各主体の資源の制約に配慮することが重要だとしている。", "正しい。ガイドラインが示すアジャイル・ガバナンスの基本的なモデルである。"],
  src: [{ t: "総務省・経済産業省「AI事業者ガイドライン（第1.2版）」本編（2026年3月31日）", u: "https://www.meti.go.jp/shingikai/mono_info_service/ai_shakai_jisso/pdf/20260331_1.pdf" }] },
{ id: "M-132", set: "mock", sec: "L08", kw: ["ソフトロー","価値原則"], type: "best",
  stem: "OECD の「人工知能に関する理事会勧告」（いわゆる OECD AI 原則）の説明として、最も適切なものを1つ選べ。",
  choices: ["原則に違反した参加国に対し、OECD が制裁金を科すことのできる、法的拘束力のある条約である", "OECD の加盟国だけが参加でき、加盟国でない国がこの勧告に参加（adhere）することはできない", "2019年に採択された AI に関する最初の政府間の基準で、法的拘束力はないが、参加国がその実施に最善を尽くすという政治的な約束を表している。同年の G20 の AI 原則のもとにもなった", "2019年の採択以来一度も改訂されておらず、生成 AI の登場などの変化は反映されていない"],
  ans: 2,
  exp: "OECD AI 原則は、2019年5月22日に OECD 閣僚理事会で採択された、AI に関する最初の政府間の基準である。包摂的な成長、人権と民主的価値（公平性・プライバシーを含む）、透明性と説明可能性、頑健性・セキュリティ・安全性、アカウンタビリティの5つの価値に基づく原則と、政策立案者への5つの勧告からなる。OECD の理事会勧告は法的拘束力を持たないソフトローであり、2023年11月と2024年5月に、生成 AI などを踏まえて改訂された。",
  why: ["OECD の勧告（Recommendation）は法的拘束力を持たない。法的拘束力があるのは理事会の決定（Decision）である。", "勧告は「加盟国および参加する非加盟国」を名あて人としており、非加盟国も参加できる。", "正しい。G20 大阪サミット（2019年6月）で歓迎された G20 AI 原則は、この勧告から作られた。", "2023年11月に AI システムの定義が、2024年5月に生成 AI などを踏まえた内容が改訂された。"],
  src: [{ t: "OECD. Recommendation of the Council on Artificial Intelligence, OECD/LEGAL/0449（PDF）", u: "https://legalinstruments.oecd.org/public/doc/648/648.en.pdf" }, { t: "OECD.AI: OECD AI Principles overview", u: "https://oecd.ai/en/ai-principles" }] },
/* ── L09 プライバシー ── */
{ id: "M-133", set: "mock", sec: "L09", kw: ["プライバシー・バイ・デザイン"], type: "best",
  stem: "健康管理アプリの開発で、位置情報の共有や第三者へのデータ提供の設定を、初期状態ではすべて「オフ」にし、利用者が何も設定しなくてもプライバシーが守られるようにした。この設計が最も直接に対応する、プライバシー・バイ・デザインの7原則の一つとして、最も適切なものを1つ選べ。",
  choices: ["事後的ではなく事前的、救済的ではなく予防的", "ゼロサムではなくポジティブサム（機能を損なわない）", "可視性・透明性（公開を保つ）", "初期設定としてのプライバシー"],
  ans: 3,
  exp: "プライバシー・バイ・デザインは、カナダ・オンタリオ州の情報・プライバシー・コミッショナーだった Cavoukian が提唱した、システムの設計段階からプライバシー保護を組み込む考え方である。7原則の一つ「初期設定としてのプライバシー（Privacy as the Default Setting）」は、利用者が何もしなくてもプライバシーが守られるよう、<span class='no-terms'>個人データ</span>が自動的に保護される状態を初期設定にすることを求める。",
  why: ["侵害が起きる前に予測して防ぐことを求める原則である。初期設定の内容を直接扱うものではない。", "プライバシーと機能・安全などを二者択一にせず、両立させることを求める原則である。", "仕組みや運用が約束どおりであることを、利用者などが確かめられるようにすることを求める原則である。", "正しい。何も設定しなくてもプライバシーが守られる状態を初期設定とする原則である。"],
  src: [{ t: "Cavoukian, A. Privacy by Design: The 7 Foundational Principles（総務省掲載の参考資料）", u: "https://www.soumu.go.jp/main_content/000196321.pdf" }] },
/* ── L10 公平性 ── */
{ id: "M-134", set: "mock", sec: "L10", kw: ["公平性の定義","センシティブ属性"], type: "calc",
  stem: "ある企業が書類選考に AI を使ったところ、男性は応募者 200 人のうち 120 人、女性は応募者 120 人のうち 54 人が選考を通過した。米国の雇用差別を扱う当局が用いる「4/5（80%）ルール」（選考率が最も高い集団の選考率に対し、ある集団の選考率が 4/5 未満なら、選考率に大きな差があるとみなす目安）に当てはめた結果として、正しいものを1つ選べ。",
  choices: ["女性の選考率は 45%、男性は 60% で、比は 0.75 である。4/5 を下回るので、選考率に大きな差があるとみなされる", "比は 0.75 だが、選考率の差は 15 ポイントで 20 ポイント未満なので、4/5 ルールの目安には当たらない", "通過者の数は女性 54 人、男性 120 人で、比は 0.45 である。4/5 を大きく下回る", "男性の選考率を女性の選考率で割ると 1.33 で、1 を上回るので女性が有利である"],
  ans: 0,
  exp: "選考率は、女性 54 ÷ 120 = 0.45、男性 120 ÷ 200 = 0.60 であり、比は 0.45 ÷ 0.60 = 0.75 となる。米国の雇用機会均等委員会（EEOC）などの統一ガイドラインは、選考率が最も高い集団の 4/5（80%）未満の選考率を、大きな差の目安とする。これは集団ごとの結果の割合をそろえる人口統計学的パリティの考え方に近い指標である。ただし、EEOC はこの目安を法的な定義ではなく、重大な差に注意を向けるための実務上の手段だとしている。",
  why: ["正しい。0.45 ÷ 0.60 = 0.75 で、0.8 を下回る。", "4/5 ルールは選考率の比で判断するものであり、差（ポイント）で判断するものではない。", "人数ではなく、応募者に対する通過者の割合（選考率）で比べる必要がある。応募者数が異なるので、人数の比は意味を持たない。", "比は、選考率が最も高い集団（男性）の選考率を分母にとる。分母と分子を逆にしており、結論も誤っている。"],
  src: [{ t: "EEOC. Questions and Answers to Clarify and Provide a Common Interpretation of the Uniform Guidelines on Employee Selection Procedures", u: "https://www.eeoc.gov/laws/guidance/questions-and-answers-clarify-and-provide-common-interpretation-uniform-guidelines" }, { t: "29 CFR 1607.4 Information on impact（govinfo）", u: "https://www.govinfo.gov/content/pkg/CFR-2024-title29-vol4/pdf/CFR-2024-title29-vol4-sec1607-4.pdf" }] },
{ id: "M-135", set: "mock", sec: "L10", kw: ["アルゴリズムバイアス","データの偏り"], type: "worst",
  stem: "AI の公平性が問題となった事例や研究に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Amazon の採用 AI は、10年間に応募された主に男性の履歴書で学習した結果、「women's」という語を含む履歴書を低く評価したと報じられた。特定の語を中立に扱うよう修正しても、ほかの形で差別的な選別をしないとは保証できなかったという", "ProPublica は、米国フロリダ州ブロワード郡の再犯予測ツール COMPAS について、実際には再犯しなかった人のうち高リスクと判定された割合が、黒人で 44.9%、白人で 23.5% だったと報じた", "Gender Shades の研究では、商用の顔画像の性別分類システムの誤り率は、肌の色や性別による差がほとんどなく、どの集団でも 1% 未満であった", "予測に基づく警察の配置では、予測された地域に警察官が多く送られて、そこで発見される犯罪が増え、そのデータでさらに同じ地域が予測される、という暴走するフィードバックループが起こりうると指摘されている"],
  ans: 2,
  exp: "Buolamwini と Gebru の Gender Shades（2018年）は、商用の性別分類システムを評価し、肌の色が濃い女性で誤り率が最も高く（最大 34.7%）、肌の色が明るい男性では最大 0.8% だったことを示した。また、広く使われていた顔画像のデータセット（IJB-A・Adience）は、肌の色が明るい人が大部分（79.6%・86.2%）を占めていた。データの偏りや評価の偏りが、集団による性能の差につながる例である。",
  why: ["適切。Reuters の報道の内容である。特定の語を除いても、ほかの特徴が代わりに性別を表す（代理変数）おそれが残る。", "適切。ProPublica の分析では、逆に、再犯したのに低リスクと判定された割合は白人（47.7%）の方が黒人（28.0%）より高かった。", "不適切（これが正解）。肌の色が濃い女性の誤り率は最大 34.7% で、集団による大きな差があった。", "適切。Ensign ら（2018年）は、警察が真の犯罪率にかかわらず同じ地域に繰り返し送られる、暴走するフィードバックループを指摘した。"],
  src: [{ t: "Buolamwini, J. & Gebru, T. (2018). Gender Shades: Intersectional Accuracy Disparities in Commercial Gender Classification", u: "https://proceedings.mlr.press/v81/buolamwini18a.html" }, { t: "Angwin, J. et al. (2016). Machine Bias（ProPublica）", u: "https://www.propublica.org/article/machine-bias-risk-assessments-in-criminal-sentencing" }, { t: "Dastin, J. (2018). Amazon scraps secret AI recruiting tool that showed bias against women（Reuters、CNBC 掲載）", u: "https://www.cnbc.com/2018/10/10/amazon-scraps-a-secret-ai-recruiting-tool-that-showed-bias-against-women.html" }, { t: "Ensign, D. et al. (2018). Runaway Feedback Loops in Predictive Policing", u: "https://proceedings.mlr.press/v81/ensign18a.html" }] },
/* ── L11 安全性とセキュリティ ── */
{ id: "M-136", set: "mock", sec: "L11", kw: ["データ窃取"], type: "best",
  stem: "ある病院が、患者の退院記録で学習した予測モデルを API として公開した。攻撃者は、特定の人物の記録を手元に持っており、その記録を API に入力したときの出力の傾向から、その人物の記録がモデルの学習データに含まれていたかどうか（つまり、その病院の患者だったかどうか）を判定しようとしている。この攻撃として、最も適切なものを1つ選べ。",
  choices: ["モデル反転攻撃", "メンバーシップ推論攻撃", "モデル窃取", "データ汚染"],
  ans: 1,
  exp: "メンバーシップ推論攻撃は、あるデータとモデルへの問い合わせの手段が与えられたとき、そのデータがモデルの学習データに含まれていたかを判定する攻撃である。Shokri らは、モデルが学習に使った入力と使っていない入力とで予測の傾向が異なることを利用し、病院の退院データのように所属そのものが機微な情報になる例で危険性を示した。学習データに関する情報を引き出す攻撃（データ窃取）の一種である。",
  why: ["モデル反転攻撃は、モデルの出力（確信度など）を手がかりに、学習データの特徴（例：顔画像）を復元しようとする攻撃である。", "正しい。特定の記録が学習データに含まれていたかを判定する攻撃である。", "モデル窃取は、問い合わせの入出力の組を集めて、元のモデルとほぼ同じ働きをするモデルを複製する攻撃である。", "データ汚染は、学習データに不正なデータを混ぜて、モデルに誤った学習をさせる攻撃である。"],
  src: [{ t: "Shokri, R. et al. (2016). Membership Inference Attacks against Machine Learning Models", u: "https://arxiv.org/abs/1610.05820" }, { t: "Fredrikson, M., Jha, S. & Ristenpart, T. (2015). Model Inversion Attacks that Exploit Confidence Information and Basic Countermeasures", u: "https://doi.org/10.1145/2810103.2813677" }, { t: "Tramèr, F. et al. (2016). Stealing Machine Learning Models via Prediction APIs", u: "https://arxiv.org/abs/1609.02943" }] },
{ id: "M-137", set: "mock", sec: "L11", kw: ["データ汚染","Adversarial Attack (Adversarial Examples)","モデル窃取","データ窃取"], type: "worst",
  stem: "機械学習に特有の攻撃への対策に関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["Adversarial Examples を正しいラベルとともに学習データに加えて訓練する敵対的訓練は、回避攻撃への対策の一つである", "モデル窃取への対策として、出力から確信度を省いてラベルだけを返す方法があるが、それだけでは攻撃を完全には防げないことが報告されている", "データ汚染は運用中のモデルへの入力に小さな加工を加える攻撃なので、学習データの出所の確認や、異常なデータの除去は対策にならない", "差分プライバシーを用いた学習は、メンバーシップ推論などによる学習データの情報の漏えいへの対策になる"],
  ans: 2,
  exp: "データ汚染（データポイズニング）は、学習データの一部に不正なデータを混ぜ込み、学習の段階でモデルをゆがめる攻撃である。NIST の報告書（AI 100-2）は、対策として、汚染されたデータが通常のデータと異なる傾向を使って学習データを清浄化する方法や、データの来歴（出所）と完全性を確かめる仕組みを挙げている。運用中の入力に小さな加工を加えて誤認識させるのは、Adversarial Examples による回避攻撃である。",
  why: ["適切。敵対的訓練は Goodfellow らが導入し、回避攻撃への代表的な対策とされている。", "適切。Tramèr ら（2016年）は、確信度を省くという自然な対策をとっても、なお有害なモデル窃取が可能なことを示した。", "不適切（これが正解）。データ汚染は学習の段階を狙う攻撃であり、学習データの清浄化や来歴の確認が対策になる。", "適切。NIST の報告書は、差分プライバシーはメンバーシップ推論やデータの再構成の攻撃を防ぐとしている。"],
  src: [{ t: "NIST AI 100-2e2025 (2025). Adversarial Machine Learning: A Taxonomy and Terminology of Attacks and Mitigations", u: "https://doi.org/10.6028/NIST.AI.100-2e2025" }, { t: "Goodfellow, I. J., Shlens, J. & Szegedy, C. (2014). Explaining and Harnessing Adversarial Examples", u: "https://arxiv.org/abs/1412.6572" }, { t: "Tramèr, F. et al. (2016). Stealing Machine Learning Models via Prediction APIs", u: "https://arxiv.org/abs/1609.02943" }] },
/* ── L12 悪用 ── */
{ id: "M-138", set: "mock", sec: "L12", kw: ["ディープフェイク"], type: "best",
  stem: "EU AI 法（Regulation (EU) 2024/1689）における、ディープフェイクや AI が生成したコンテンツの透明性に関する説明として、最も適切なものを1つ選べ。",
  choices: ["ディープフェイクにあたる画像・音声・動画を生成・操作する AI システムを使う導入者（deployer）は、そのコンテンツが人工的に生成・操作されたものであることを開示しなければならない。明らかに芸術的・風刺的な作品などでは、鑑賞を妨げない適切な方法で示せばよい", "ディープフェイクを生成できる AI システムは、用途を問わず、すべて禁止される AI に分類されている", "作品が芸術的・風刺的なものであれば、ディープフェイクであることの開示の義務は完全に免除される", "合成したコンテンツに機械で読み取れる表示を付ける提供者の義務は、画像・音声・動画が対象であり、文章を生成する AI には適用されない"],
  ans: 0,
  exp: "EU AI 法50条は、AI と対話することや AI が生成したコンテンツであることを人が知れるようにする透明性の義務を定めている。50条2項は、音声・画像・動画・文章の合成コンテンツを生成する AI システムの提供者に、出力を機械で読み取れる形式で表示し、人工的に生成・操作されたものと検出できるようにすることを求める。50条4項は、ディープフェイクを生成・操作する AI システムの導入者に、そのことの開示を求めている。",
  why: ["正しい。50条4項の内容である。芸術的・創作的・風刺的・架空の作品などでは、作品の表示や鑑賞を妨げない適切な方法で、生成・操作されたコンテンツがあることを示すことに限られる。", "ディープフェイクを生成する AI 一般は、禁止ではなく透明性の義務の対象である。なお、改正規則 (EU) 2026/1744 により、本人の同意のない性的な画像などを生成する AI が禁止に加えられた（5条1項 ba 号。2026年12月2日から適用）。", "芸術的・風刺的な作品などでも、開示の義務は「鑑賞を妨げない適切な方法での開示」に限られるだけで、なくなるわけではない。", "50条2項は、音声・画像・動画に加えて文章（テキスト）の合成コンテンツを生成する AI システムも対象としている。"],
  src: [{ t: "AI Act Service Desk: Article 50 Transparency obligations for providers and deployers of certain AI systems（European Commission）", u: "https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-50" }, { t: "Regulation (EU) 2024/1689 (Artificial Intelligence Act)（EUR-Lex）", u: "https://eur-lex.europa.eu/eli/reg/2024/1689/oj" }] },
/* ── L13 透明性 ── */
{ id: "M-139", set: "mock", sec: "L13", kw: ["データの来歴"], type: "best",
  stem: "電子部品に性能や試験結果を記した資料（データシート）が添えられるのにならい、機械学習のデータセットごとに、作成の動機、構成、収集の過程、推奨される用途などを記した文書を添えることを提案したものとして、最も適切なものを1つ選べ。",
  choices: ["Model Cards for Model Reporting", "SHAP", "差分プライバシー", "Datasheets for Datasets"],
  ans: 3,
  exp: "Gebru ら（2018年）の「Datasheets for Datasets」は、機械学習の分野にデータセットを記録する標準的な手順がなく、重大な影響を及ぼしうる分野で問題になりうると指摘した。そのうえで、データセットごとに、作成の動機、構成、収集の過程、推奨される用途などを記したデータシートを添えることを提案した。データの来歴を記録して作成者と利用者の意思疎通を助け、透明性とアカウンタビリティを高めることがねらいである。",
  why: ["Model Cards（Mitchell ら）は、学習済みモデルについて、想定される用途や、集団ごとの性能の評価などを記した文書を添える提案である。データセットではなくモデルが対象である。", "SHAP は、個々の予測に対する各特徴量の寄与を示す説明手法であり、データセットの記録の提案ではない。", "差分プライバシーは、個々のデータの有無が分析の結果にほとんど影響しないようにして、プライバシーを守る枠組みである。", "正しい。データセットごとにデータシートを添えることを提案したものである。"],
  src: [{ t: "Gebru, T. et al. (2018). Datasheets for Datasets", u: "https://arxiv.org/abs/1803.09010" }, { t: "Mitchell, M. et al. (2018). Model Cards for Model Reporting", u: "https://arxiv.org/abs/1810.03993" }] },
/* ── L14 民主主義 ── */
{ id: "M-140", set: "mock", sec: "L14", kw: ["フィルターバブル"], type: "blank",
  stem: "検索サービスや SNS が利用者ごとに表示する情報を選ぶ（個人化する）ことで、利用者が自分の関心や考えに合う情報に包まれ、それ以外の情報が見えにくくなる状態を「フィルターバブル」と名付け、2011年の著書や講演で警鐘を鳴らしたのは（　）である。（　）に入る人物として、最も適切なものを1つ選べ。",
  choices: ["イーライ・パリサー", "ソロウシュ・ヴォスギ", "リサンヌ・ベインブリッジ", "アン・カブキアン"],
  ans: 0,
  exp: "Eli Pariser（パリサー）は、2011年の著書『The Filter Bubble』や同年の TED の講演で、ウェブ企業が利用者の好みに合わせて情報を選ぶことで、利用者が自分では気づかないうちに、異なる見方から切り離されることに注意を促した。フィルターバブルはアルゴリズムによる情報の選別に着目した概念であり、似た考えの人どうしのやり取りで意見が反響・増幅されるエコーチェンバーとは区別される。",
  why: ["正しい。フィルターバブルという言葉を広めた人物である。", "Vosoughi（ヴォスギ）らは、Twitter 上で虚偽のニュースが真実のニュースより速く広く拡散することを示した研究（2018年）で知られる。", "Bainbridge（ベインブリッジ）は、1983年の論文「Ironies of automation」で、自動化が進むほど人の技能が衰えるという「自動化の皮肉」を指摘した。", "Cavoukian（カブキアン）は、プライバシー・バイ・デザインを提唱した人物である。"],
  src: [{ t: "Eli Pariser: Beware online \"filter bubbles\"（TED, 2011）", u: "https://www.ted.com/talks/eli_pariser_beware_online_filter_bubbles" }, { t: "Vosoughi, S., Roy, D. & Aral, S. (2018). The spread of true and false news online", u: "https://doi.org/10.1126/science.aap9559" }, { t: "Bainbridge, L. (1983). Ironies of automation", u: "https://doi.org/10.1016/0005-1098(83)90046-8" }] },
/* ── L15 環境保護 ── */
{ id: "M-141", set: "mock", sec: "L15", kw: ["モデル学習の電力消費"], type: "calc",
  stem: "あるモデルを、GPU 8 基（1基あたり平均 300 W）と、CPU・メモリ（合計で平均 600 W）を使って 100 時間学習した。データセンターの PUE（冷却なども含めた施設全体の電力 ÷ 計算機器の電力）は 1.5、電力 1 kWh あたりの CO<sub>2</sub> 排出量は 0.4 kg と仮定する。機器の消費電力の合計に時間と PUE を掛けて電力量を求め、排出係数を掛けて CO<sub>2</sub> 排出量を推計するとき、その値として正しいものを1つ選べ。",
  choices: ["80 kg", "120 kg", "144 kg", "180 kg"],
  ans: 3,
  exp: "機器の消費電力は 8 × 300 W + 600 W = 3,000 W = 3 kW で、100 時間では 300 kWh となる。施設全体では PUE を掛けて 300 × 1.5 = 450 kWh、CO<sub>2</sub> 排出量は 450 × 0.4 = 180 kg である。Strubell ら（2019年）も、CPU・メモリ・GPU の消費電力の合計に学習時間と PUE（当時のデータセンターの世界平均 1.58）を掛けて電力量を求め、排出係数を掛けて推計した。同じ計算でも、電力の発電構成によって排出係数が変わり、排出量は大きく変わる。",
  why: ["電力量 300 kWh を PUE で割ってしまった値（300 ÷ 1.5 × 0.4）である。PUE は掛ける。", "PUE を掛け忘れた値（300 × 0.4）である。冷却などの施設の電力が含まれていない。", "GPU の電力だけで計算した値（2.4 kW × 100 × 1.5 × 0.4）である。CPU・メモリの電力も含める。", "正しい。3 kW × 100 時間 × 1.5 × 0.4 kg/kWh = 180 kg である。"],
  src: [{ t: "Strubell, E., Ganesh, A. & McCallum, A. (2019). Energy and Policy Considerations for Deep Learning in NLP", u: "https://arxiv.org/abs/1906.02243" }, { t: "Lacoste, A. et al. (2019). Quantifying the Carbon Emissions of Machine Learning", u: "https://arxiv.org/abs/1910.09700" }] },
/* ── L16 労働政策 ── */
{ id: "M-142", set: "mock", sec: "L16", kw: ["AI との協働"], type: "worst",
  stem: "Brynjolfsson らの研究「Generative AI at Work」（2025年）は、カスタマーサポートの担当者に、生成 AI による会話の支援ツールを段階的に導入した効果を分析した。この研究の結果として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["AI の支援を受けると、顧客の態度がより丁寧になり、管理者との交代を求めることも減った", "AI の支援により、1時間あたりに解決した問い合わせの件数で測った生産性は、平均で約 15% 高まった", "経験が豊富で技能の高い担当者ほど、仕事の速さと質の両方が大きく向上した", "経験の浅い担当者や技能の低い担当者では、仕事の速さと質の両方が向上した"],
  ans: 2,
  exp: "この研究は、5,172 人のカスタマーサポートの担当者のデータを使い、生成 AI による支援で生産性が平均 15% 高まったことを示した。効果は担当者によって大きく異なり、経験の浅い人や技能の低い人で速さと質の両方が向上した一方、最も経験豊富で技能の高い人では、速さはわずかに上がったが、質はわずかに下がった。AI との協働の効果は一様ではなく、人の経験や技能によって異なることを示す例である。",
  why: ["適切。研究は、AI の支援が働く環境のいくつかの面を改善し、顧客がより丁寧になり、管理者を求めることが減ったとしている。", "適切。平均 15% の向上が報告されている。", "不適切（これが正解）。最も経験豊富で技能の高い担当者では、速さの向上はわずかで、質はわずかに下がった。", "適切。経験の浅い担当者や技能の低い担当者では、速さと質の両方が向上した。"],
  src: [{ t: "Brynjolfsson, E., Li, D. & Raymond, L. (2025). Generative AI at Work. The Quarterly Journal of Economics", u: "https://doi.org/10.1093/qje/qjae044" }] },
/* ── L17 その他の重要な価値 ── */
{ id: "M-143", set: "mock", sec: "L17", kw: ["人間の自律性","インクルージョン"], type: "worst",
  stem: "AI と人間の自律性・インクルージョンに関する説明として、<strong>最も不適切な</strong>ものを1つ選べ。",
  choices: ["AI事業者ガイドラインは、人間の意思決定や感情を不当に操作することを目的とした AI や、意識的に知覚できないレベルでの操作を前提とした AI の開発・提供・利用は行わないよう求めている", "EU AI 法は、年齢・障害・特定の社会的または経済的な状況による脆弱性につけ込んで人の行動を大きくゆがめ、重大な損害を与えうる AI について、利用者に AI であることを知らせれば利用してよいとしている", "AI事業者ガイドラインは、自動化バイアスなど、AI に過度に依存するリスクに注意を払い、必要な対策を講じるよう求めている", "AI事業者ガイドラインは、いわゆる情報弱者や技術弱者を生じさせず、社会的弱者が AI を活用しやすくなるよう注意を払うことを求めている"],
  ans: 1,
  exp: "EU AI 法5条1項は、許容できないリスクの AI として、人の意識を超えたサブリミナルな技術や意図的に操作的・欺瞞的な技術を使う AI（a 号）と、年齢・障害・特定の社会的または経済的な状況による脆弱性につけ込む AI（b 号）を、行動を大きくゆがめて重大な損害を与えうる場合に禁止している。AI であることを知らせる透明性の義務で足りる、限定的なリスクの扱いではない。",
  why: ["適切。AI事業者ガイドラインの「人間中心」の項目にある内容である。", "不適切（これが正解）。脆弱性につけ込む AI は、5条1項 b 号で禁止されている。", "適切。ガイドラインは、自動化バイアスなど AI への過度な依存のリスクへの注意を求めている。", "適切。ガイドラインの「多様性・包摂性の確保」の内容で、ユニバーサルデザインやアクセシビリティの確保などが例に挙げられている。"],
  src: [{ t: "総務省・経済産業省「AI事業者ガイドライン（第1.2版）」本編（2026年3月31日）", u: "https://www.meti.go.jp/shingikai/mono_info_service/ai_shakai_jisso/pdf/20260331_1.pdf" }, { t: "AI Act Service Desk: Article 5 Prohibited AI practices（European Commission）", u: "https://ai-act-service-desk.ec.europa.eu/en/ai-act/article-5" }] },
/* ── L18 AIガバナンス ── */
{ id: "M-144", set: "mock", sec: "L18", kw: ["AI に対する監査"], type: "best",
  stem: "AI のマネジメントシステムと監査に関する説明として、最も適切なものを1つ選べ。",
  choices: ["ISO/IEC 42001 は、組織が AI マネジメントシステムを確立・実施・維持し、継続的に改善するための要求事項を定めた国際規格で、AI を提供する組織だけでなく利用する組織も対象とする。AI事業者ガイドラインの別添は、監査を行う組織の基準として ISO/IEC 42006 なども参照することが有用だとしている", "ISO/IEC 42001 は、AI モデルごとに精度の合格基準を数値で定め、製品ごとに性能を試験するための規格である", "AI事業者ガイドラインは、小規模な企業も含むすべての AI 事業者に、独立した内部監査部門を設けることを法的に義務づけている", "ISO/IEC 42001 は EU AI 法の一部として制定された規則であり、EU 域内の事業者に法的拘束力をもって適用される"],
  ans: 0,
  exp: "ISO/IEC 42001:2023 は、2023年12月に発行された AI マネジメントシステムの国際規格である。規模・種類を問わず、AI を使う製品やサービスを提供・利用する組織が対象で、組織の中で AI マネジメントシステムを確立し、継続的に改善するための要求事項と手引きを定めている。AI事業者ガイドラインの別添は、マネジメントの標準として ISO/IEC 42001 を、監査・認証を行う組織の基準として ISO/IEC 42006 などを参照することが有用だとし、内部監査・外部監査を組み合わせる実践例も示している。",
  why: ["正しい。IEC の規格の説明とガイドラインの別添の内容に合う。", "ISO/IEC 42001 は組織のマネジメントシステムについての規格であり、個々のモデルの精度の基準を定める規格ではない。", "AI事業者ガイドラインは法的拘束力のないソフトローである。別添は、小規模企業が内部監査部門を設けず、自己監査を中心にする実践例も紹介している。", "ISO/IEC 42001 は国際標準化機構（ISO）と国際電気標準会議（IEC）の国際規格であり、EU の法令ではない。"],
  src: [{ t: "IEC Webstore: ISO/IEC 42001:2023 Information technology - Artificial intelligence - Management system", u: "https://webstore.iec.ch/en/publication/90574" }, { t: "総務省・経済産業省「AI事業者ガイドライン（第1.2版）」別添（2026年3月31日）", u: "https://www.meti.go.jp/shingikai/mono_info_service/ai_shakai_jisso/pdf/20260331_3.pdf" }] },
{ id: "M-145", set: "mock", sec: "L18", kw: ["倫理アセスメント"], type: "blank",
  stem: "欧州委員会の AI に関する高レベル専門家グループ（AI HLEG）は、2020年7月、「信頼できる AI のための倫理ガイドライン」が示した7つの要件を、AI の開発者や導入者が実務で確かめるための自己評価用のチェックリストを公表した。これを（　）という。（　）に入る語句として、最も適切なものを1つ選べ。",
  choices: ["AI RMF（AI リスクマネジメントフレームワーク）", "ISO/IEC 42001", "Model Cards", "ALTAI（信頼できる AI のための評価リスト）"],
  ans: 3,
  exp: "ALTAI（Assessment List for Trustworthy Artificial Intelligence）は、350 を超える関係者が参加した試行を経て、2020年7月17日に AI HLEG が最終版を示した自己評価用のツールである。7つの要件（人間の主体性と監視、技術的な頑健性と安全性、プライバシーとデータガバナンス、透明性、多様性・無差別・公平性、環境的・社会的な幸福、アカウンタビリティ）を、具体的な確認の手順に落とし込んでいる。ウェブで使える版もある。",
  why: ["AI RMF 1.0 は、米国の NIST が2023年に公表した、AI のリスクを管理するための枠組みである。", "ISO/IEC 42001 は、AI マネジメントシステムの要求事項を定めた国際規格である。", "Model Cards は、学習済みモデルの想定用途や性能の評価を記した文書を添える提案である。", "正しい。AI HLEG による自己評価用のチェックリストである。"],
  src: [{ t: "European Commission: Assessment List for Trustworthy Artificial Intelligence (ALTAI) for self-assessment", u: "https://digital-strategy.ec.europa.eu/en/library/assessment-list-trustworthy-artificial-intelligence-altai-self-assessment" }, { t: "NIST (2023). Artificial Intelligence Risk Management Framework (AI RMF 1.0)", u: "https://doi.org/10.6028/NIST.AI.100-1" }] },
]);
